INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f55363ac-175b-45f9-b69c-00b0331576ef', '漢宮新寵', '漢宮新寵', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["位在嬪妃最上頭，笑他長信女悲秋。","日中月滿可能久，花落色衰殊未憂。","公主鏡中爭翠羽，君王袖底奪金鉤。","妾家兄弟知多少，恰要同時拜列侯。"]', '["位在嬪妃最上头，笑他长信女悲秋。","日中月满可能久，花落色衰殊未憂。","公主镜中爭翠羽，君王袖底奪金鉤。","妾家兄弟知多少，恰要同时拜列侯。"]', '诗', 'shi', '', NULL, '漢宮新寵 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c838ef9-5f85-4449-94b2-0054b8ba57d1', '開元即事', '开元即事', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["曲江真宰國中訛，尋奏漁陽忽荷戈。","堂上有兵天不用，幄中無策印空多。","塵驚騎透潼關鎖，雲護龍遊渭水波。","未必蛾眉能破國，千秋休恨馬嵬坡。"]', '["曲江真宰国中訛，尋奏漁陽忽荷戈。","堂上有兵天不用，幄中無策印空多。","塵驚騎透潼关鎖，云護龙游渭水波。","未必蛾眉能破国，千秋休恨马嵬坡。"]', '诗', 'shi', '', NULL, '開元即事 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b708015-b661-4296-954d-339e15b3bfec', '李翰林', '李翰林', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["謫下三清列八仙，獲調羹鼎侍龍顏。","吟開鎖闥窺天近，醉臥金鑾待詔閑。","舊隱不歸劉備國，旅魂長寄謝公山。","遺編往簡應飛去，散入祥雲瑞日間。"]', '["謫下三清列八仙，獲調羹鼎侍龙顏。","吟开鎖闥窺天近，醉臥金鑾待詔闲。","旧隐不归劉備国，旅魂长寄謝公山。","遺編往簡應飞去，散入祥云瑞日间。"]', '诗', 'shi', '', NULL, '李翰林 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bec1c179-ce28-4797-baad-032a75164879', '聞長安庚子歲事', '闻长安庚子歲事', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["羽檄交馳觸冕旒，函關飛入鐵兜鍪。","皇王去國未爲恨，寰海失君方是憂。","五色大雲凝蜀郡，幾般妖氣撲神州。","唐堯縱禪乾坤位，不是重華莫謾求。"]', '["羽檄交驰觸冕旒，函关飞入鐵兜鍪。","皇王去国未爲恨，寰海失君方是憂。","五色大云凝蜀郡，幾般妖氣撲神州。","唐堯縱禪乾坤位，不是重华莫謾求。"]', '诗', 'shi', '', NULL, '聞長安庚子歲事 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f8dacd2-59f5-4218-8635-0f1ae67612e6', '公子行', '公子行', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["十五轅門學控弦，六街騎馬去如煙。","金多倍著牡丹價，髮白未知章甫賢。","有耳不聞經國事，拜官方買謝恩箋。","相如謾說凌雲賦，四壁何曾有一錢。"]', '["十五轅门学控弦，六街騎马去如煙。","金多倍著牡丹價，髮白未知章甫賢。","有耳不闻經国事，拜官方買謝恩箋。","相如謾说凌云賦，四壁何曾有一錢。"]', '诗', 'shi', '', NULL, '公子行 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25554349-d0a1-43f8-afde-6c4e8ff4a1cc', '依韻贈嚴司直', '依韻贈嚴司直', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["曾轉雙蓬到玉京，宣尼恩奏樂卿名。","歌殘白石扣牛角，賦換黃金愛馬卿。","滄海二隅身漸老，太行千疊路難行。","夫君才大官何小，堪恨人間事不平。"]', '["曾轉雙蓬到玉京，宣尼恩奏乐卿名。","歌殘白石扣牛角，賦換黄金愛马卿。","滄海二隅身漸老，太行千叠路难行。","夫君才大官何小，堪恨人间事不平。"]', '诗', 'shi', '', NULL, '依韻贈嚴司直 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e21988a-b05a-4077-b07c-9787e423c17c', '傷前翰林楊左丞', '傷前翰林楊左丞', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["飛上鰲頭侍玉皇，三台遺耀換餘光。","人間搦管窮蒼頡，地上修文待卜商。","真魄肯隨金石化，真風留伴蕙蘭香。","皇天未啓昇平運，不使伊臯相禹湯。"]', '["飞上鰲头侍玉皇，三台遺耀換餘光。","人间搦管窮蒼頡，地上修文待卜商。","真魄肯隨金石化，真风留伴蕙蘭香。","皇天未啓昇平運，不使伊臯相禹湯。"]', '诗', 'shi', '', NULL, '傷前翰林楊左丞 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad258f6-8437-4742-a5ce-33e9079758c6', '日月無情', '日月無情', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["日月無情也有情，朝昇夕沒照均平。","雖催前代英雄死，還促後來賢聖生。","三尺靈烏金借耀，一輪飛鏡水饒清。","憑誰築斷東溟路，龍影蟬光免運行。"]', '["日月無情也有情，朝昇夕沒照均平。","雖催前代英雄死，還促後来賢聖生。","三尺靈烏金借耀，一輪飞镜水饒清。","憑誰築斷东溟路，龙影蟬光免運行。"]', '诗', 'shi', '', NULL, '日月無情 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec045964-fdc5-49d2-bef1-a9a613d8cd48', '新月', '新月', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雲際[嬋娟]出又藏，美人腸斷拜金方。","姮娥一隻眉先掃，織女三分鏡未光。","珠箔寄鉤懸杳靄，白龍遺爪印穹蒼。","更期十五圓明夜，與破陰霾照八荒。"]', '["云際[嬋娟]出又藏，美人腸斷拜金方。","姮娥一隻眉先掃，织女三分镜未光。","珠箔寄鉤懸杳靄，白龙遺爪印穹蒼。","更期十五圓明夜，與破陰霾照八荒。"]', '诗', 'shi', '', NULL, '新月 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29efd110-184b-4974-8912-6695f7f72de9', '和尚書詠煙', '和尚书詠煙', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["無根無蒂結還融，曾觸嵐光徹底空。","不散幾知離畢雨，欲飛須待落花風。","玲瓏薄展蛟綃片，羃歷輕含鳳竹叢。","瓊什捧來思舊隱，撲窗穿戶曉溟濛。"]', '["無根無蒂結還融，曾觸嵐光徹底空。","不散幾知離畢雨，欲飞須待落花风。","玲瓏薄展蛟綃片，羃歷轻含鳳竹叢。","瓊什捧来思旧隐，撲窗穿戶晓溟濛。"]', '诗', 'shi', '', NULL, '和尚書詠煙 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606be72f-bce4-41ca-82bc-f5d85bfeb157', '宮鸎', '宮鸎', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["領得春光在帝家，早從深谷出煙霞。","閑棲仙禁日邊柳，飢啄御園天上花。","睍睆只宜陪閣鳳，間關多是問宮娃。","可憐鸚鵡矜言語，長閉雕籠歲月賒。"]', '["領得春光在帝家，早從深谷出煙霞。","闲棲仙禁日邊柳，飢啄御园天上花。","睍睆只宜陪閣鳳，间关多是问宮娃。","可怜鸚鵡矜言語，长閉雕籠歲月賒。"]', '诗', 'shi', '', NULL, '宮鸎 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('445ee2a7-ae62-490b-b15e-05a69677c43e', '鬢髮', '鬢髮', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["鬢添華髮數莖新，羅雀門前絕故人。","減食爲緣疎五味，不眠非是守庚申。","深園竹綠齊抽笋，古木蛇青自脫鱗。","天地有鑪長鑄物，濁泥遺塊待陶鈞。"]', '["鬢添华髮數莖新，羅雀门前絕故人。","減食爲緣疎五味，不眠非是守庚申。","深园竹綠齊抽笋，古木蛇青自脫鱗。","天地有鑪长鑄物，濁泥遺塊待陶鈞。"]', '诗', 'shi', '', NULL, '鬢髮 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6a5f083-adbe-4813-b767-e3704fde3422', '春入鯉湖', '春入鯉湖', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["到來峭壁白雲齊，載酒春遊渡九溪。","鐵嶂有樓霾欲墮，石門無鎖路還迷。","湖頭鯉去轟雷在，樹杪猨啼落日低。","回首浮生真幻夢，何如斯地傍幽棲。"]', '["到来峭壁白云齊，載酒春游渡九溪。","鐵嶂有楼霾欲墮，石门無鎖路還迷。","湖头鯉去轟雷在，樹杪猨啼落日低。","回首浮生真幻梦，何如斯地傍幽棲。"]', '诗', 'shi', '', NULL, '春入鯉湖 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87957990-cfc7-4b03-8ba8-ff9ecd8b2566', '雙鷺', '雙鷺', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雙鷺雕籠昨夜開，月明飛出立庭隈。","但教綠水池塘在，自有碧天鴻雁來。","清韻叫霜歸島樹，素翎遺雪落漁臺。","何人爲我追尋得，重勸溪翁酒一桮。"]', '["雙鷺雕籠昨夜开，月明飞出立庭隈。","但教綠水池塘在，自有碧天鴻雁来。","清韻叫霜归島樹，素翎遺雪落漁台。","何人爲我追尋得，重勸溪翁酒一桮。"]', '诗', 'shi', '', NULL, '雙鷺 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e48ea0e0-363a-47ea-ac23-941854a558cb', '鷓鴣', '鷓鴣', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["繡僕梅兼羽翼全，楚雞非瑞莫爭先。","啼歸明月落邊樹，飛入百花深處煙。","避燒幾曾遺遠岫，引雛時見飲晴川。","茘枝初熟無人際，啄破紅苞墜野田。"]', '["繡僕梅兼羽翼全，楚雞非瑞莫爭先。","啼归明月落邊樹，飞入百花深处煙。","避燒幾曾遺远岫，引雛时见饮晴川。","茘枝初熟無人際，啄破紅苞墜野田。"]', '诗', 'shi', '', NULL, '鷓鴣 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d0a5204-9f81-4192-a320-dc95cdae4b08', '鷹', '鷹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["害物傷生性豈馴，且宜籠罩待知人。","惟擒燕雀啗腥血，却笑鸞皇啄翠筠。","狡兔穴多非爾識，鳴鳩脰短罰君身。","豪門不讀詩書者，走馬平原放翫頻。"]', '["害物傷生性豈馴，且宜籠罩待知人。","惟擒燕雀啗腥血，却笑鸾皇啄翠筠。","狡兔穴多非爾識，鳴鳩脰短罰君身。","豪门不读诗书者，走马平原放翫頻。"]', '诗', 'shi', '', NULL, '鷹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a199ac-e508-46c2-b3ed-ecbcda4e4d81', '晦日宴高氏林亭', '晦日宴高氏林亭', 'b2070cea-4816-4daf-8b44-2c52fc1de7e5', '唐', '["公子申敬愛，攜朋翫物華。","人是平陽客，地即石崇家。","水文生舊浦，風色滿新花。","日暮連歸騎，長川照晚霞。"]', '["公子申敬愛，携朋翫物华。","人是平陽客，地即石崇家。","水文生旧浦，风色满新花。","日暮連归騎，长川照晚霞。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 陳嘉言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3098b52-2a7b-4e81-9afc-af4f6ed53817', '晦日重宴', '晦日重宴', 'b2070cea-4816-4daf-8b44-2c52fc1de7e5', '唐', '["高門引冠蓋，下客抱支離。","綺席珍羞滿，文場翰藻摛。","蓂華彫上月，柳色藹春池。","日斜歸戚里，連騎勒金羈。"]', '["高门引冠蓋，下客抱支離。","綺席珍羞满，文場翰藻摛。","蓂华彫上月，柳色藹春池。","日斜归戚里，連騎勒金羈。"]', '诗', 'shi', '', NULL, '晦日重宴 陳嘉言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0abe69-b0e5-40d9-a852-5bddc6c38abf', '上元夜效小庾體', '上元夜效小庾體', 'b2070cea-4816-4daf-8b44-2c52fc1de7e5', '唐', '["今夜可憐春，河橋多麗人。","寶馬金爲絡，香車玉作輪。","連手窺潘掾，分頭看洛神。","重城自不掩，出向小平津。"]', '["今夜可怜春，河橋多丽人。","寶马金爲絡，香车玉作輪。","連手窺潘掾，分头看洛神。","重城自不掩，出向小平津。"]', '诗', 'shi', '', NULL, '上元夜效小庾體 陳嘉言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d756f172-bcc6-4835-9efa-e3adc7c7d939', '晦日宴高氏林亭', '晦日宴高氏林亭', 'bb5a959c-02f6-4811-84fa-fb174b97cc85', '唐', '["砌蓂收晦魄，津柳競年華。","既狎忘筌友，方淹投轄車。","綺筵迴舞雪，瓊醑泛流霞。","雲低上天晚，絲雨帶風斜。"]', '["砌蓂收晦魄，津柳競年华。","既狎忘筌友，方淹投轄车。","綺筵迴舞雪，瓊醑泛流霞。","云低上天晚，絲雨带风斜。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 周彥暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb57f9c-5b88-42f7-8316-af64a2c96c8f', '晦日重宴', '晦日重宴', 'bb5a959c-02f6-4811-84fa-fb174b97cc85', '唐', '["春華歸柳樹，俯景落蓂枝。","置驛銅街右，開筵玉浦陲。","林煙含障密，竹雨帶珠危。","興闌巾倒戴，山公下習池。"]', '["春华归柳樹，俯景落蓂枝。","置驛銅街右，开筵玉浦陲。","林煙含障密，竹雨带珠危。","兴闌巾倒戴，山公下習池。"]', '诗', 'shi', '', NULL, '晦日重宴 周彥暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da41a40c-8b63-4731-b03c-558d7cd45a96', '晦日宴高氏林亭', '晦日宴高氏林亭', 'af504c9f-e377-49aa-b0be-f2d74e350363', '唐', '["飛觀寫春望，開宴坐汀沙。","積溜含苔色，晴空蕩日華。","歌入平陽第，舞對石崇家。","莫慮能騎馬，投轄自停車。"]', '["飞观寫春望，开宴坐汀沙。","積溜含苔色，晴空蕩日华。","歌入平陽第，舞对石崇家。","莫慮能騎马，投轄自停车。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 高嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b2953c-6047-49ee-88ee-d8d2b78aeb0c', '晦日重宴', '晦日重宴', 'af504c9f-e377-49aa-b0be-f2d74e350363', '唐', '["駕言尋鳳侶，乘歡俯雁池。","班荆逢舊識，斟桂喜深知。","紫蘭方出徑，黃鶯未囀枝。","別有陶春日，青天雲霧披。"]', '["駕言尋鳳侶，乘歡俯雁池。","班荆逢旧識，斟桂喜深知。","紫蘭方出徑，黄鶯未囀枝。","別有陶春日，青天云霧披。"]', '诗', 'shi', '', NULL, '晦日重宴 高嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f468053a-b4d5-48a8-ac27-b55ae8b8aeed', '晦日宴高氏林亭', '晦日宴高氏林亭', '2c0a5c6e-ab43-427b-aa71-917550de7724', '唐', '["春來日漸賒，琴酒逐年華。","欲向文通逕，先遊武子家。","池碧新流滿，巖紅落照斜。","興闌情未盡，步步惜風花。"]', '["春来日漸賒，琴酒逐年华。","欲向文通逕，先游武子家。","池碧新流满，巖紅落照斜。","兴闌情未尽，步步惜风花。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 劉友賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('058bf120-30d8-44e1-9524-b4a78b2355f4', '晦日宴高氏林亭', '晦日宴高氏林亭', '24b0b39b-a293-4c41-aad8-41fb69a96c2d', '唐', '["早春驚柳穟，初晦掩蓂華。","騎出平陽里，筵開衞尉家。","竹影含雲密，池紋帶雨斜。","重惜林亭晚，上路滿煙霞。"]', '["早春驚柳穟，初晦掩蓂华。","騎出平陽里，筵开衞尉家。","竹影含云密，池紋带雨斜。","重惜林亭晚，上路满煙霞。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 周思鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0cf16d-fcb1-4492-bb0a-cc771db42415', '晦日重宴', '晦日重宴', '24b0b39b-a293-4c41-aad8-41fb69a96c2d', '唐', '["綺筵乘晦景，高宴下陽池。","濯雨梅香散，含風柳色移。","輕塵依扇落，流水入弦危。","勿顧林亭晚，方歡雲霧披。"]', '["綺筵乘晦景，高宴下陽池。","濯雨梅香散，含风柳色移。","轻塵依扇落，流水入弦危。","勿顧林亭晚，方歡云霧披。"]', '诗', 'shi', '', NULL, '晦日重宴 周思鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0924990-7f5e-4384-ad61-acae007f72f3', '祭汾陰樂章', '祭汾陰乐章', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["禮物斯具，樂章乃陳。","誰其作主，皇考聖真。","對越在天，聖明佐神。","窅然汾上，厚澤如春。"]', '["禮物斯具，乐章乃陳。","誰其作主，皇考聖真。","对越在天，聖明佐神。","窅然汾上，厚澤如春。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ab168e-cf2f-4972-a5c6-70c8d5bca0e0', '奉和聖製行次成皐途經先聖擒建德之所感而成詩應制', '奉和聖製行次成皐途經先聖擒建德之所感而成诗應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["漢東不執象，河朔方鬬龍。","夏滅漸寧亂，唐興終奮庸。","皇威正赫赫，兵氣何匈匈。","用武三川震，歸淳六代醲。","成臯覩王業，天下致人雍。","即此巡於岱，曾孫受命封。"]', '["漢东不執象，河朔方鬬龙。","夏滅漸寧亂，唐兴終奮庸。","皇威正赫赫，兵氣何匈匈。","用武三川震，归淳六代醲。","成臯覩王業，天下致人雍。","即此巡於岱，曾孫受命封。"]', '诗', 'shi', '', NULL, '奉和聖製行次成皐途經先聖擒建德之所感而成詩應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a63ad8c-148a-46c0-8e0d-b52c32ca5b0c', '奉和聖製登蒲州逍遙樓應制', '奉和聖製登蒲州逍遙楼應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["在昔堯舜禹，遺塵成典謨。","聖皇東巡狩，況乃經此都。","樓觀紛迤邐，河山幾縈紆。","緬懷祖宗業，相繼文武圖。","尚德既無險，觀風諒有孚。","豈如汾水上，簫鼓事遊娛。"]', '["在昔堯舜禹，遺塵成典謨。","聖皇东巡狩，況乃經此都。","楼观紛迤邐，河山幾縈紆。","緬懷祖宗業，相繼文武圖。","尚德既無險，观风諒有孚。","豈如汾水上，簫鼓事游娛。"]', '诗', 'shi', '', NULL, '奉和聖製登蒲州逍遙樓應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b0ef70c-ced6-49e9-a88e-4aef0f574f43', '奉和聖製過晉陽宮應制', '奉和聖製過晉陽宮應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["隋運與天絕，生靈厭氛昏。","聖期在寧亂，士馬興太原。","立極萬邦推，登庸四海尊。","慶膺神武帝，業付皇曾孫。","緬慕封唐道，追惟歸沛魂。","詔書感先義，典禮巡舊藩。","高殿綵雲合，春旗祥風翻。","率西見汾水，奔北空塞垣。","款曲童兒佐，依遲故老言。","里頒慈惠賞，家受復除恩。","下輦崇三教，建碑當九門。","孝思敦至美，億載奉開元。"]', '["隋運與天絕，生靈厭氛昏。","聖期在寧亂，士马兴太原。","立極万邦推，登庸四海尊。","慶膺神武帝，業付皇曾孫。","緬慕封唐道，追惟归沛魂。","詔书感先義，典禮巡旧藩。","高殿綵云合，春旗祥风翻。","率西见汾水，奔北空塞垣。","款曲童兒佐，依遲故老言。","里頒慈惠賞，家受复除恩。","下輦崇三教，建碑當九门。","孝思敦至美，億載奉开元。"]', '诗', 'shi', '', NULL, '奉和聖製過晉陽宮應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2ccf48-722e-4c48-8ac0-f3c9a4662f00', '奉和姚令公溫湯舊館永懷故人盧公之作', '奉和姚令公溫湯旧館永懷故人盧公之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["樹德豈孤邁，降神良竝出。","偉茲廊廟楨，調彼鹽梅實。","正悅虞垂舉，翻悲鄭僑卒。","同心不可忘，交臂何爲失。","清路荷前幸，明時稱右弼。","曾聯野外遊，尚記帷中密。","新慟情莫遣，舊遊詞更述。","空令還辱和，長歎知音日。"]', '["樹德豈孤邁，降神良竝出。","偉茲廊廟楨，調彼鹽梅實。","正悅虞垂舉，翻悲鄭僑卒。","同心不可忘，交臂何爲失。","清路荷前幸，明时稱右弼。","曾聯野外游，尚記帷中密。","新慟情莫遣，旧游词更述。","空令還辱和，长歎知音日。"]', '诗', 'shi', '', NULL, '奉和姚令公溫湯舊館永懷故人盧公之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6cdc6ae-2328-4240-a0ea-4ea0812a7f2c', '和杜主簿春日有所思', '和杜主簿春日有所思', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["朝上高樓上，俯見洛陽陌。","搖蕩吹花風，落英紛已積。","美人不共此，芳好空所惜。","攬鏡塵網滋，當窗苔蘚碧。","緬懷在雲漢，良願暌枕席。","翻似無見時，如何久爲客。"]', '["朝上高楼上，俯见洛陽陌。","搖蕩吹花风，落英紛已積。","美人不共此，芳好空所惜。","攬镜塵網滋，當窗苔蘚碧。","緬懷在云漢，良願暌枕席。","翻似無见时，如何久爲客。"]', '诗', 'shi', '', NULL, '和杜主簿春日有所思 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c61854-cba7-4a56-969f-26c728cf5e60', '餞郢州李使君', '餞郢州李使君', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["楚有章華臺，遙遙雲夢澤。","復聞擁符傳，及是收圖籍。","佳政在離人，能聲寄侯伯。","離懷朔風起，試望秋陰積。","中路悽以寒，羣山靄將夕。","傷心聊把袂，怊悵麒麟客。"]', '["楚有章华台，遙遙云梦澤。","复闻擁符傳，及是收圖籍。","佳政在離人，能声寄侯伯。","離懷朔风起，試望秋陰積。","中路悽以寒，羣山靄將夕。","傷心聊把袂，怊悵麒麟客。"]', '诗', 'shi', '', NULL, '餞郢州李使君 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2f1f6f-6683-4d66-832f-ce7ec626d142', '餞唐州高使君赴任', '餞唐州高使君赴任', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["永日奏文時，東風搖蕩夕。","浩然思樂事，翻復餞征客。","淮水春流清，楚山暮雲白。","勿言行路遠，所貴專城伯。"]', '["永日奏文时，东风搖蕩夕。","浩然思乐事，翻复餞征客。","淮水春流清，楚山暮云白。","勿言行路远，所貴專城伯。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee39294-5e69-4fbd-a697-f9c046f35808', '曉濟膠川南入密界', '晓濟膠川南入密界', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["飲馬膠川上，傍膠南趣密。","林遙飛鳥遲，雲去晴山出。","落暉隱桑柘，秋原被花實。","慘然遊子寒，風露將蕭瑟。"]', '["饮马膠川上，傍膠南趣密。","林遙飞鸟遲，云去晴山出。","落暉隐桑柘，秋原被花實。","慘然游子寒，风露將蕭瑟。"]', '诗', 'shi', '', NULL, '曉濟膠川南入密界 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1eeb16-6997-4a02-a38f-afaa462312dd', '夜發三泉即事', '夜發三泉即事', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["暗發三泉山，窮秋聽騷屑。","北林夜鳴雨，南望曉成雪。","祗詠北風涼，詎知南土熱。","沙溪忽沸渭，石道乍明滅。","宛若銀磧橫，復如瑤臺結。","指程賦所戀，遇虞不遑歇。","重纊濡莫解，懸旌凍猶揭。","下奔泥棧榰，上覯雲梯設。","[搏]頰羸馬頓，回眸惴人跌。","憧憧往復還，心注思逾切。","冉冉年將病，力困衰怠竭。","天彭信方隅，地勢誠斗絕。","忝曳尚書履，叨兼使臣節。","京坻有歲饒，亭障無邊孽。","歸奏丹墀左，騫能俟來哲。"]', '["暗發三泉山，窮秋听騷屑。","北林夜鳴雨，南望晓成雪。","祗詠北风涼，詎知南土熱。","沙溪忽沸渭，石道乍明滅。","宛若銀磧橫，复如瑤台結。","指程賦所戀，遇虞不遑歇。","重纊濡莫解，懸旌凍猶揭。","下奔泥棧榰，上覯云梯設。","[搏]頰羸马頓，回眸惴人跌。","憧憧往复還，心注思逾切。","冉冉年將病，力困衰怠竭。","天彭信方隅，地勢誠斗絕。","忝曳尚书履，叨兼使臣節。","京坻有歲饒，亭障無邊孽。","归奏丹墀左，騫能俟来哲。"]', '诗', 'shi', '', NULL, '夜發三泉即事 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79262d57-0081-46bb-891c-dd702fe98ba8', '小園納涼即事', '小园納涼即事', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["煩暑避蒸鬱，居閑習高明。","長風自遠來，層閣有餘清。","散灑納涼氣，蕭條遺世情。","奈何誇大隱，終日繫塵纓。"]', '["煩暑避蒸鬱，居闲習高明。","长风自远来，層閣有餘清。","散灑納涼氣，蕭條遺世情。","奈何誇大隐，終日繫塵纓。"]', '诗', 'shi', '', NULL, '小園納涼即事 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc1017d-f8f9-43f8-b9a5-a5e3b52b0351', '昆明池晏坐答王兵部珣三韻見示', '昆明池晏坐答王兵部珣三韻见示', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["畫舸疾如飛，遙遙汎夕暉。","石黥吹浪隱，玉女步塵歸。","獨有銜恩處，明珠在釣磯。"]', '["畫舸疾如飞，遙遙汎夕暉。","石黥吹浪隐，玉女步塵归。","独有銜恩处，明珠在釣磯。"]', '诗', 'shi', '', NULL, '昆明池晏坐答王兵部珣三韻見示 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d609c55-0dae-4244-9c55-b52b32d3bd1a', '奉和聖製春臺望應制', '奉和聖製春台望應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["壯麗天之府，神明王者宅。","大君乘飛龍，登彼復懷昔。","圓闕朱光燄，橫山翠微積。","河汧流作表，縣聚開成陌。","即舊在皇家，維新具物華。","雲連所上居恆屬，日更時中望不斜。","三月滄池搖積水，萬年青樹綴新花。","暴嬴國此嘗圖霸，霸業後仁先以詐。","東破諸侯西入秦，咸陽北阪南渭津。","詩書焚爇散學士，高閣奢踰嬌美人。","事往覆輈經遠喻，春還按蹕憑高賦。","戎觀愛力深惟省，越厭陳方何足務。","清吹遙遙發帝臺，宸文耿耿照天迴。","伯夷位事愚臣忝，喜奏聲成鳳鳥來。"]', '["壯丽天之府，神明王者宅。","大君乘飞龙，登彼复懷昔。","圓闕朱光燄，橫山翠微積。","河汧流作表，縣聚开成陌。","即旧在皇家，維新具物华。","云連所上居恆屬，日更时中望不斜。","三月滄池搖積水，万年青樹綴新花。","暴嬴国此嘗圖霸，霸業後仁先以詐。","东破諸侯西入秦，咸陽北阪南渭津。","诗书焚爇散学士，高閣奢踰嬌美人。","事往覆輈經远喻，春還按蹕憑高賦。","戎观愛力深惟省，越厭陳方何足務。","清吹遙遙發帝台，宸文耿耿照天迴。","伯夷位事愚臣忝，喜奏声成鳳鸟来。"]', '诗', 'shi', '', NULL, '奉和聖製春臺望應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3fa087-f937-4e13-a715-e3fa86225bd5', '長相思', '长相思', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["君不見天津橋下東流水，南望龍門北朝市。","楊柳青青宛地垂，桃紅李白花參差。","花參差，柳堪結，此時憶君心斷絕。"]', '["君不见天津橋下东流水，南望龙门北朝市。","楊柳青青宛地垂，桃紅李白花參差。","花參差，柳堪結，此时憶君心斷絕。"]', '诗', 'shi', '', NULL, '長相思 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519c3ae7-5ffa-41f9-b2a6-001e7d2b6dfb', '蜀城哭台州樂安少府', '蜀城哭台州乐安少府', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["遠遊躋劒閣，長想屬天台。","萬里隔三載，此邦余重來。","音容曠不覩，夢寐殊悠哉。","邊郡饒藉藉，晚庭正回回。","喜傳上都封，因促傍吏開。","向悟海鹽客，已而梁木摧。","變衣寢門外，揮涕少城隈。","却記分明得，猶持委曲猜。","師儒昔訓獎，仲季時童孩。","服義題書篋，邀歡汎酒杯。","蹔令風雨散，仍迫歲時迴。","其道惟正直，其人信美偲。","白頭還作尉，黃綬固非才。","可歎懸蛇疾，先貽問鵩災。","故鄉閉窮壤，宿草生寒荄。","零落九原去，蹉跎四序催。","曩期冬贈橘，今哭夏成梅。","執禮誰爲賵，居常不徇財。","北登嵔𡻱坂，東望姑蘇臺。","天路本懸絕，江波復泝洄。","念孤心易斷，追往恨艱裁。","不遂卿將伯，孰云陳與雷。","吾衰亦如此，夫子復何哀。"]', '["远游躋劒閣，长想屬天台。","万里隔三載，此邦余重来。","音容曠不覩，梦寐殊悠哉。","邊郡饒藉藉，晚庭正回回。","喜傳上都封，因促傍吏开。","向悟海鹽客，已而梁木摧。","变衣寢门外，揮涕少城隈。","却記分明得，猶持委曲猜。","師儒昔訓獎，仲季时童孩。","服義題书篋，邀歡汎酒杯。","蹔令风雨散，仍迫歲时迴。","其道惟正直，其人信美偲。","白头還作尉，黄綬固非才。","可歎懸蛇疾，先貽问鵩災。","故乡閉窮壤，宿草生寒荄。","零落九原去，蹉跎四序催。","曩期冬贈橘，今哭夏成梅。","執禮誰爲賵，居常不徇財。","北登嵔𡻱坂，东望姑蘇台。","天路本懸絕，江波复泝洄。","念孤心易斷，追往恨艱裁。","不遂卿將伯，孰云陳與雷。","吾衰亦如此，夫子复何哀。"]', '诗', 'shi', '', NULL, '蜀城哭台州樂安少府 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa0c22b-a7a2-4bed-aed2-b436bd5daf78', '立春日侍宴內出剪綵花應制', '立春日侍宴內出剪綵花應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["曉入宜春苑，穠芳吐禁中。","剪刀因裂素，妝粉爲開紅。","彩異驚流雪，香饒點便風。","裁成識天意，萬物與花同。"]', '["晓入宜春苑，穠芳吐禁中。","剪刀因裂素，妝粉爲开紅。","彩異驚流雪，香饒点便风。","裁成識天意，万物與花同。"]', '诗', 'shi', '', NULL, '立春日侍宴內出剪綵花應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61479e50-d043-4087-9210-ba372edd74e0', '春日芙蓉園侍宴應制', '春日芙蓉园侍宴應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["御道紅旗出，芳園翠輦遊。","繞花開水殿，架竹起山樓。","荷芰輕薰幄，魚龍出負舟。","寧知穆天子，空賦白雲秋。"]', '["御道紅旗出，芳园翠輦游。","繞花开水殿，架竹起山楼。","荷芰轻薰幄，鱼龙出負舟。","寧知穆天子，空賦白云秋。"]', '诗', 'shi', '', NULL, '春日芙蓉園侍宴應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ad7ac00-3e4f-4c29-ace7-aff39377ea36', '奉和聖製人日清暉閣宴羣臣遇雪應制', '奉和聖製人日清暉閣宴羣臣遇雪應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["樓觀空煙裏，初年瑞雪過。","苑花齊玉樹，池水作銀河。","七日祥圖啓，千春御賞多。","輕飛傳綵勝，天上奉薰歌。"]', '["楼观空煙裏，初年瑞雪過。","苑花齊玉樹，池水作銀河。","七日祥圖啓，千春御賞多。","轻飞傳綵勝，天上奉薰歌。"]', '诗', 'shi', '', NULL, '奉和聖製人日清暉閣宴羣臣遇雪應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d724ea-f6dc-4f4b-8343-39e155f5b21a', '奉和七夕宴兩儀殿應制', '奉和七夕宴兩儀殿應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["靈媛乘秋發，仙裝警夜催。","月光窺欲渡，河色辨應來。","機石天文寫，針樓御賞開。","竊觀棲鳥至，疑向鵲橋迴。"]', '["靈媛乘秋發，仙裝警夜催。","月光窺欲渡，河色辨應来。","機石天文寫，針楼御賞开。","竊观棲鸟至，疑向鵲橋迴。"]', '诗', 'shi', '', NULL, '奉和七夕宴兩儀殿應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8827ebc-e47d-455a-8613-c3ea71f88fa7', '奉和九日幸臨渭亭登高應制得時字', '奉和九日幸臨渭亭登高應制得时字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["嘉會宜長日，高筵順動時。","曉光雲外洗，晴色雨餘滋。","降鶴因韶德，吹花入御詞。","願陪陽數節，億萬九秋期。"]', '["嘉會宜长日，高筵順动时。","晓光云外洗，晴色雨餘滋。","降鹤因韶德，吹花入御词。","願陪陽數節，億万九秋期。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得時字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a277a9-3b82-4b7a-838a-c4aa26155c8f', '游禁苑幸臨渭亭遇雪應制', '游禁苑幸臨渭亭遇雪應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["平明敞帝居，霰雪下凌虛。","寫月含珠綴，從風薄綺疏。","年驚花絮早，春夜管弦初。","已屬雲天外，欣承霈澤餘。"]', '["平明敞帝居，霰雪下凌虛。","寫月含珠綴，從风薄綺疏。","年驚花絮早，春夜管弦初。","已屬云天外，欣承霈澤餘。"]', '诗', 'shi', '', NULL, '游禁苑幸臨渭亭遇雪應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0915a3d1-5af4-403b-a2c1-1872e5e40edd', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["帝女出天津，和戎轉罽輪。","川經斷腸望，地與析支鄰。","奏曲風嘶馬，銜悲月伴人。","旋知偃兵革，長是漢家親。"]', '["帝女出天津，和戎轉罽輪。","川經斷腸望，地與析支鄰。","奏曲风嘶马，銜悲月伴人。","旋知偃兵革，长是漢家親。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c8f4bd-ab2e-4eff-89a2-f576e3f07c21', '奉和聖製登驪山高頂寓目應制', '奉和聖製登驪山高頂寓目應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["仙蹕御層氛，高高積翠分。","巖聲中谷應，天語半空聞。","豐樹連黃葉，函關入紫雲。","聖圖恢宇縣，歌賦小橫汾。"]', '["仙蹕御層氛，高高積翠分。","巖声中谷應，天語半空闻。","豐樹連黄葉，函关入紫云。","聖圖恢宇縣，歌賦小橫汾。"]', '诗', 'shi', '', NULL, '奉和聖製登驪山高頂寓目應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e842aba-99c4-453a-9f01-57ebd48b37fe', '幸白鹿觀應制', '幸白鹿观應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["碧虛清吹下，藹藹入仙宮。","松磴攀雲絕，花源接澗空。","受符邀羽使，傳訣注香童。","詎似閑居日，徒聞有順風。"]', '["碧虛清吹下，藹藹入仙宮。","松磴攀云絕，花源接澗空。","受符邀羽使，傳訣注香童。","詎似闲居日，徒闻有順风。"]', '诗', 'shi', '', NULL, '幸白鹿觀應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94da5d2e-2dfb-4c37-b301-6fd888c2b46a', '題壽安王主簿池館', '題壽安王主簿池館', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["洛邑通馳道，韓郊在屬城。","館將花雨映，潭與竹聲清。","賢俊鸞棲棘，賓遊馬佩衡。","願言隨狎鳥，從此濯吾纓。"]', '["洛邑通驰道，韓郊在屬城。","館將花雨映，潭與竹声清。","賢俊鸾棲棘，賓游马佩衡。","願言隨狎鸟，從此濯吾纓。"]', '诗', 'shi', '', NULL, '題壽安王主簿池館 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807b1a6b-4135-4f2d-8ab8-dd59e4cd8a88', '扈從溫泉奉和姚令公喜雪', '扈從溫泉奉和姚令公喜雪', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["清道豐人望，乘時漢主遊。","恩暉隨霰下，慶澤與雲浮。","泉暖驚銀磧，花寒愛玉樓。","鼎臣今有問，河伯且應留。"]', '["清道豐人望，乘时漢主游。","恩暉隨霰下，慶澤與云浮。","泉暖驚銀磧，花寒愛玉楼。","鼎臣今有问，河伯且應留。"]', '诗', 'shi', '', NULL, '扈從溫泉奉和姚令公喜雪 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d051f373-5d3a-4e30-8251-f2075e7be21f', '秋社日崇讓園宴得新字', '秋社日崇讓园宴得新字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["鳴爵三農稔，勾龍百代神。","運昌叨輔弼，時泰喜黎民。","樹缺池光近，雲開日影新。","生全應有地，長願樂交親。"]', '["鳴爵三農稔，勾龙百代神。","運昌叨輔弼，时泰喜黎民。","樹缺池光近，云开日影新。","生全應有地，长願乐交親。"]', '诗', 'shi', '', NULL, '秋社日崇讓園宴得新字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb85f47a-eeb7-4050-86c2-406673a49f9d', '奉和魏僕射秋日還鄉有懷之作', '奉和魏僕射秋日還乡有懷之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["南宮夙拜罷，東道晝遊初。","飲餞傾冠蓋，傳呼問里閭。","樹悲懸劒所，溪想釣璜餘。","明發輝光至，增榮駟馬車。"]', '["南宮夙拜罷，东道晝游初。","饮餞傾冠蓋，傳呼问里閭。","樹悲懸劒所，溪想釣璜餘。","明發輝光至，增榮駟马车。"]', '诗', 'shi', '', NULL, '奉和魏僕射秋日還鄉有懷之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab0986c-763c-491e-bea2-a886fd7734ce', '武[擔]山寺', '武[擔]山寺', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["武[擔]獨蒼然，墳山下玉泉。","鱉靈時共盡，龍女事同遷。","松柏銜哀處，幡花種福田。","詎知留鏡石，長與法輪圓。"]', '["武[擔]独蒼然，墳山下玉泉。","鱉靈时共尽，龙女事同遷。","松柏銜哀处，幡花種福田。","詎知留镜石，长與法輪圓。"]', '诗', 'shi', '', NULL, '武[擔]山寺 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b86918e-abf0-4054-8971-7f20c434843f', '餞潞州陸長史再守汾州', '餞潞州陸长史再守汾州', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["河尹政成期，爲汾昔所推。","不榮三入地，還美再臨時。","擁傳雲初合，聞鶯日正遲。","道傍多出餞，別有吏民思。"]', '["河尹政成期，爲汾昔所推。","不榮三入地，還美再臨时。","擁傳云初合，闻鶯日正遲。","道傍多出餞，別有吏民思。"]', '诗', 'shi', '', NULL, '餞潞州陸長史再守汾州 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbdf15f-8b26-4b45-a853-1808fd830a70', '餞荆州崔司馬', '餞荆州崔司马', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["茂禮雕龍昔，香名展驥初。","水連南海漲，星拱北辰居。","稍發仙人履，將題別駕輿。","明年徵拜入，荆玉不藏諸。"]', '["茂禮雕龙昔，香名展驥初。","水連南海漲，星拱北辰居。","稍發仙人履，將題別駕輿。","明年徵拜入，荆玉不藏諸。"]', '诗', 'shi', '', NULL, '餞荆州崔司馬 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5a747e-f805-4a32-936f-f41b11e561b0', '送吏部李侍郎東歸得歸字', '送吏部李侍郎东归得归字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["陌上有光輝，披雲向洛畿。","賞來榮扈從，別至惜分飛。","泉溜含風急，山煙帶日微。","茂曹今去矣，人物喜東歸。"]', '["陌上有光輝，披云向洛畿。","賞来榮扈從，別至惜分飞。","泉溜含风急，山煙带日微。","茂曹今去矣，人物喜东归。"]', '诗', 'shi', '', NULL, '送吏部李侍郎東歸得歸字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b3dd1c8-9fe6-4f21-aeab-435e432ac5bd', '送光祿姚卿還都', '送光祿姚卿還都', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["漢室有英台，荀家寵俊才。","九卿朝已入，三子暮同來。","不授綸爲草，還司鼎用梅。","兩京王者宅，駟馬日應迴。"]', '["漢室有英台，荀家寵俊才。","九卿朝已入，三子暮同来。","不授綸爲草，還司鼎用梅。","兩京王者宅，駟马日應迴。"]', '诗', 'shi', '', NULL, '送光祿姚卿還都 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e534536-557a-4e3d-a0b0-67b23141b312', '春晚送瑕丘田少府還任因寄洛中鏡上人', '春晚送瑕丘田少府還任因寄洛中镜上人', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["聞道還沂上，因聲寄洛濱。","別時花欲盡，歸處酒應春。","聚散同行客，悲歡屬故人。","少年追樂地，遙贈一霑巾。"]', '["闻道還沂上，因声寄洛濱。","別时花欲尽，归处酒應春。","聚散同行客，悲歡屬故人。","少年追乐地，遙贈一霑巾。"]', '诗', 'shi', '', NULL, '春晚送瑕丘田少府還任因寄洛中鏡上人 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03f7eb5-f9e6-4298-8a54-f5cf9f65d477', '送賈起居奉使入洛取圖書因便拜覲', '送賈起居奉使入洛取圖书因便拜覲', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["舊國才因地，當朝史命官。","遺文徵闕簡，還思采芳蘭。","傳發關門候，觴稱邑里歡。","早持京副入，旋佇洛書刊。"]', '["旧国才因地，當朝史命官。","遺文徵闕簡，還思采芳蘭。","傳發关门候，觴稱邑里歡。","早持京副入，旋佇洛书刊。"]', '诗', 'shi', '', NULL, '送賈起居奉使入洛取圖書因便拜覲 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0648fc4-6617-4e82-94d7-2390a914685a', '送常侍舒公歸覲', '送常侍舒公归覲', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["朝聞講藝餘，晨省拜恩初。","訓胄尊庠序，榮親耀里閭。","朱丹華轂送，斑白綺筵舒。","江上春流滿，還應薦躍魚。"]', '["朝闻講藝餘，晨省拜恩初。","訓胄尊庠序，榮親耀里閭。","朱丹华轂送，斑白綺筵舒。","江上春流满，還應薦躍鱼。"]', '诗', 'shi', '', NULL, '送常侍舒公歸覲 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f282ed-ccad-4b94-9c7a-f8e4045148b5', '興州出行', '兴州出行', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["危途曉未分，驅馬傍江濆。","滴滴泣花露，微微出岫雲。","松梢半吐月，蘿翳漸移曛。","旅客腸應斷，吟猿更使聞。"]', '["危途晓未分，驱马傍江濆。","滴滴泣花露，微微出岫云。","松梢半吐月，蘿翳漸移曛。","旅客腸應斷，吟猿更使闻。"]', '诗', 'shi', '', NULL, '興州出行 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af75693d-cb7b-4e74-8e41-a66cb930fd94', '邊秋薄暮', '邊秋薄暮', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["海外秋鷹擊，霜前旅雁歸。","邊風思鞞鼓，落日慘旌麾。","浦暗漁舟入，川長獵騎稀。","客悲逢薄暮，況乃事戎機。"]', '["海外秋鷹擊，霜前旅雁归。","邊风思鞞鼓，落日慘旌麾。","浦暗漁舟入，川长獵騎稀。","客悲逢薄暮，況乃事戎機。"]', '诗', 'shi', '', NULL, '邊秋薄暮 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b419a2f7-bcdc-4387-8973-84546a1f62b0', '曉發方騫驛', '晓發方騫驛', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["傳置遠山蹊，龍鍾蹴澗泥。","片陰常作雨，微照已生霓。","鬢髪愁氛換，心情險路迷。","方知向蜀者，偏識子規啼。"]', '["傳置远山蹊，龙鍾蹴澗泥。","片陰常作雨，微照已生霓。","鬢髪愁氛換，心情險路迷。","方知向蜀者，偏識子規啼。"]', '诗', 'shi', '', NULL, '曉發方騫驛 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f094723-d83a-4c36-a327-dcfd96594b9e', '經三泉路作', '經三泉路作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["三月松作花，春行日漸賒。","竹障山鳥路，藤蔓野人家。","透石飛梁下，尋雲絕磴斜。","此中誰與樂，揮涕語年華。"]', '["三月松作花，春行日漸賒。","竹障山鸟路，藤蔓野人家。","透石飞梁下，尋云絕磴斜。","此中誰與乐，揮涕語年华。"]', '诗', 'shi', '', NULL, '經三泉路作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31bcf3f-9b75-4500-a914-bde28efb10b2', '故高安大長公主挽詞', '故高安大长公主挽词', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["彤管承師訓，青圭備禮容。","孟孫家代寵，元女國朝封。","柔軌題貞順，閑規賦肅雍。","寧知落照盡，霜吹入悲松。"]', '["彤管承師訓，青圭備禮容。","孟孫家代寵，元女国朝封。","柔軌題貞順，闲規賦肅雍。","寧知落照尽，霜吹入悲松。"]', '诗', 'shi', '', NULL, '故高安大長公主挽詞 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e7d553-f748-43f2-9589-d01507371bb2', '贈司徒豆盧府君挽詞', '贈司徒豆盧府君挽词', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["寵贈追胡廣，親臨比賀循。","幾聞投劒客，多會服緦人。","草閉墳將古，松陰地不春。","二陵猶可望，存歿有忠臣。"]', '["寵贈追胡廣，親臨比賀循。","幾闻投劒客，多會服緦人。","草閉墳將古，松陰地不春。","二陵猶可望，存歿有忠臣。"]', '诗', 'shi', '', NULL, '贈司徒豆盧府君挽詞 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e0da1f-558e-4632-a50d-74c4cad68f4b', '故右散騎常侍舒國公褚公挽詞', '故右散騎常侍舒国公褚公挽词', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["陽翟疏豐構，臨平演慶源。","學筵尊授几，儒服寵乘軒。","審諭留中密，開陳與上言。","徂暉一不借，空有賜東園。"]', '["陽翟疏豐構，臨平演慶源。","学筵尊授几，儒服寵乘軒。","審諭留中密，开陳與上言。","徂暉一不借，空有賜东园。"]', '诗', 'shi', '', NULL, '故右散騎常侍舒國公褚公挽詞 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93baa0bf-4a69-4c0e-9431-c0b06e4d490c', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["主第山門起灞川，宸遊風景入初年。","鳳皇樓下交天仗，烏鵲橋頭敞御筵。","往往花間逢綵石，時時竹裏見紅泉。","今朝扈蹕平陽館，不羨乘槎雲漢邊。"]', '["主第山门起灞川，宸游风景入初年。","鳳皇楼下交天仗，烏鵲橋头敞御筵。","往往花间逢綵石，时时竹裏见紅泉。","今朝扈蹕平陽館，不羨乘槎云漢邊。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5e2fdc-3d12-4e3e-b73a-89b9c4393459', '奉和春日幸望春宮應制', '奉和春日幸望春宮應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["東望望春春可憐，更逢晴日柳含煙。","宮中下見南山盡，城上平臨北斗懸。","細草徧承回輦處，輕花微落奉觴前。","宸遊對此歡無極，鳥哢聲聲入管絃。"]', '["东望望春春可怜，更逢晴日柳含煙。","宮中下见南山尽，城上平臨北斗懸。","細草徧承回輦处，轻花微落奉觴前。","宸游对此歡無極，鸟哢声声入管絃。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d15bf8-930d-4f71-93dc-dc0c4fd3febb', '人日重宴大明宮恩賜綵縷人勝應制', '人日重宴大明宮恩賜綵縷人勝應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["疏龍磴道切昭回，建鳳旗門繞帝臺。","七葉仙蓂依月吐，千株御柳拂煙開。","初年競貼宜春勝，長命先浮獻壽杯。","是日皇靈知竊幸，羣心就捧大明來。"]', '["疏龙磴道切昭回，建鳳旗门繞帝台。","七葉仙蓂依月吐，千株御柳拂煙开。","初年競貼宜春勝，长命先浮獻壽杯。","是日皇靈知竊幸，羣心就捧大明来。"]', '诗', 'shi', '', NULL, '人日重宴大明宮恩賜綵縷人勝應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6bbaa2-2896-4921-a8de-ba8a965682b4', '侍宴安樂公主山莊應制', '侍宴安乐公主山莊應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["駸駸羽騎歷城池，帝女樓臺向晚披。","霧灑旌旗雲外出，風回巖岫雨中移。","當軒半落天河水，繞徑全低月樹枝。","簫鼓宸遊陪宴日，和鳴雙鳳喜來儀。"]', '["駸駸羽騎歷城池，帝女楼台向晚披。","霧灑旌旗云外出，风回巖岫雨中移。","當軒半落天河水，繞徑全低月樹枝。","簫鼓宸游陪宴日，和鳴雙鳳喜来儀。"]', '诗', 'shi', '', NULL, '侍宴安樂公主山莊應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55580d53-8836-4f3c-bcfd-d8f96c576727', '興慶池侍宴應制', '兴慶池侍宴應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["降鶴池前回步輦，棲鸞樹杪出行宮。","山光積翠遙疑逼，水態含青近若空。","直視天河垂象外，俯窺京室畫圖中。","皇歡未使恩波極，日暮樓船更起風。"]', '["降鹤池前回步輦，棲鸾樹杪出行宮。","山光積翠遙疑逼，水態含青近若空。","直視天河垂象外，俯窺京室畫圖中。","皇歡未使恩波極，日暮楼船更起风。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb753059-30e7-4c32-8c89-88fe16a45eda', '廣達樓下夜侍酺宴應制', '廣達楼下夜侍酺宴應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["東嶽封廻宴洛京，西墉通晚會公卿。","樓臺絕勝宜春苑，燈火還同不夜城。","正覩人間朝市樂，忽聞天上管弦聲。","酺來萬舞羣臣醉，喜戴千年聖主明。"]', '["东嶽封廻宴洛京，西墉通晚會公卿。","楼台絕勝宜春苑，灯火還同不夜城。","正覩人间朝市乐，忽闻天上管弦声。","酺来万舞羣臣醉，喜戴千年聖主明。"]', '诗', 'shi', '', NULL, '廣達樓下夜侍酺宴應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4313e81d-cd01-467a-a3ef-9fa52d77517c', '龍池樂章', '龙池乐章', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["西京鳳邸躍龍泉，佳氣休光鎮在天。","軒后霧圖今已得，秦王水劒昔常傳。","恩魚不入昆明釣，瑞鶴長如太液仙。","願侍巡遊同舊里，更聞簫鼓濟樓船。"]', '["西京鳳邸躍龙泉，佳氣休光鎮在天。","軒后霧圖今已得，秦王水劒昔常傳。","恩鱼不入昆明釣，瑞鹤长如太液仙。","願侍巡游同旧里，更闻簫鼓濟楼船。"]', '诗', 'shi', '', NULL, '龍池樂章 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('365b7d0d-905e-4ea9-ac8e-2ed7f8fd8198', '扈從鄠杜間奉呈刑部尚書舅崔黃門馬常侍', '扈從鄠杜间奉呈刑部尚书舅崔黄门马常侍', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["翠輦紅旗出帝京，長楊鄠杜昔知名。","雲山一一看皆美，竹樹蕭蕭畫不成。","羽騎將過持袂拂，香車欲度捲簾行。","漢家曾草巡遊賦，何似今來應聖明。"]', '["翠輦紅旗出帝京，长楊鄠杜昔知名。","云山一一看皆美，竹樹蕭蕭畫不成。","羽騎將過持袂拂，香车欲度捲簾行。","漢家曾草巡游賦，何似今来應聖明。"]', '诗', 'shi', '', NULL, '扈從鄠杜間奉呈刑部尚書舅崔黃門馬常侍 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54aa2552-b98a-4db2-81b0-108ae32fa263', '景龍觀送裴士曹', '景龙观送裴士曹', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["昔日嘗聞公主第，今時變作列仙家。","池傍坐客穿叢篠，樹下遊人掃落花。","雨雪長疑向函谷，山泉直似到流沙。","君還洛邑分明記，此處同來閱歲華。"]', '["昔日嘗闻公主第，今时变作列仙家。","池傍坐客穿叢篠，樹下游人掃落花。","雨雪长疑向函谷，山泉直似到流沙。","君還洛邑分明記，此处同来閱歲华。"]', '诗', 'shi', '', NULL, '景龍觀送裴士曹 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f11dba11-b96d-45d6-9b7f-b02014f9e204', '春晚紫微省直寄內', '春晚紫微省直寄內', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["直省清華接建章，向來無事日猶長。","花間燕子棲鳷鵲，竹下鵷雛繞鳳皇。","內史通宵承紫誥，中人落晚愛紅妝。","別離不慣無窮憶，莫誤卿卿學太常。"]', '["直省清华接建章，向来無事日猶长。","花间燕子棲鳷鵲，竹下鵷雛繞鳳皇。","內史通宵承紫誥，中人落晚愛紅妝。","別離不慣無窮憶，莫誤卿卿学太常。"]', '诗', 'shi', '', NULL, '春晚紫微省直寄內 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56711abb-01e3-4d70-9029-039eff2d7cf7', '贈彭州權別駕', '贈彭州權別駕', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["雙流脈脈錦城開，追餞年年往復廻。","秪道歌謠迎半刺，徒聞禮數揖中台。","黃鶯急囀春風盡，斑馬長嘶落景催。","莫愴分飛岐路別，還當奏最掖垣來。"]', '["雙流脈脈錦城开，追餞年年往复廻。","秪道歌謠迎半刺，徒闻禮數揖中台。","黄鶯急囀春风尽，斑马长嘶落景催。","莫愴分飞岐路別，還當奏最掖垣来。"]', '诗', 'shi', '', NULL, '贈彭州權別駕 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b7ee52d-3960-438f-9bbd-256316f881ed', '寒食宴于中舍別駕兄弟宅', '寒食宴于中舍別駕兄弟宅', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["子推山上歌龍罷，定國門前結駟來。","始覩元昆鏘玉至，旋聞季子佩刀廻。","晴花處處因風起，御柳條條向日開。","自有長筵歡不極，還將綵服詠南陔。"]', '["子推山上歌龙罷，定国门前結駟来。","始覩元昆鏘玉至，旋闻季子佩刀廻。","晴花处处因风起，御柳條條向日开。","自有长筵歡不極，還將綵服詠南陔。"]', '诗', 'shi', '', NULL, '寒食宴于中舍別駕兄弟宅 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9fe5006-1e41-43ae-9e89-87af8b4a8e72', '九月九日望蜀臺', '九月九日望蜀台', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["蜀王望蜀舊臺前，九日分明見一川。","北料鄉關方自此，南辭城郭復依然。","青松繫馬攢巖畔，黃菊留人籍道邊。","自昔登臨湮滅盡，獨聞忠孝兩能傳。"]', '["蜀王望蜀旧台前，九日分明见一川。","北料乡关方自此，南辞城郭复依然。","青松繫马攢巖畔，黄菊留人籍道邊。","自昔登臨湮滅尽，独闻忠孝兩能傳。"]', '诗', 'shi', '', NULL, '九月九日望蜀臺 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59b1912-b88d-452b-8bf5-7b3a95b0acae', '奉和晦日幸昆明池應制', '奉和晦日幸昆明池應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["炎曆事邊陲，昆明始鑿池。","豫遊光後聖，征戰罷前規。","霽色清珍宇，年芳入錦陂。","御杯蘭薦葉，仙仗柳交枝。","二石分河瀉，雙珠代月移。","微臣比翔泳，恩廣自無涯。"]', '["炎曆事邊陲，昆明始鑿池。","豫游光後聖，征戰罷前規。","霽色清珍宇，年芳入錦陂。","御杯蘭薦葉，仙仗柳交枝。","二石分河瀉，雙珠代月移。","微臣比翔泳，恩廣自無涯。"]', '诗', 'shi', '', NULL, '奉和晦日幸昆明池應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2b4199-42cb-4eee-b932-10415d968fc8', '奉和聖製幸禮部尚書竇希玠宅應制', '奉和聖製幸禮部尚书竇希玠宅應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["尚書列侯第，外戚近臣家。","飛棟臨青綺，迴輿轉翠華。","日交當戶樹，泉漾滿池花。","圓頂圖嵩石，方流擁魏沙。","豫遊今聽履，侍從昔鳴笳。","自有天文降，無勞訪海槎。"]', '["尚书列侯第，外戚近臣家。","飞棟臨青綺，迴輿轉翠华。","日交當戶樹，泉漾满池花。","圓頂圖嵩石，方流擁魏沙。","豫游今听履，侍從昔鳴笳。","自有天文降，無勞訪海槎。"]', '诗', 'shi', '', NULL, '奉和聖製幸禮部尚書竇希玠宅應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd5d5a6-1ada-4373-ab13-591df02ce060', '奉和幸韋嗣立山莊應制', '奉和幸韋嗣立山莊應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["摐金寒野霽，步玉曉山幽。","帝幄期松子，臣廬訪葛侯。","百工徵往夢，七聖扈來遊。","斗柄乘時轉，臺階捧日留。","樹重巖籟合，泉迸水光浮。","石徑喧朝履，璜溪擁釣舟。","恩如犯星夜，歡擬濟河秋。","不學堯年隱，空令傲許由。"]', '["摐金寒野霽，步玉晓山幽。","帝幄期松子，臣廬訪葛侯。","百工徵往梦，七聖扈来游。","斗柄乘时轉，台階捧日留。","樹重巖籟合，泉迸水光浮。","石徑喧朝履，璜溪擁釣舟。","恩如犯星夜，歡擬濟河秋。","不学堯年隐，空令傲許由。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad745180-13c0-4169-8cda-0ced3fbc997f', '奉和聖製送張說上集賢學士賜宴得茲字', '奉和聖製送張说上集賢学士賜宴得茲字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["肅肅金殿裏，招賢固在茲。","鏘鏘石渠內，序拜亦同時。","宴錫歡談道，文成貴說詩。","用儒今作相，敦學舊爲師。","下際天光近，中來帝渥滋。","國朝良史載，能事日論思。"]', '["肅肅金殿裏，招賢固在茲。","鏘鏘石渠內，序拜亦同时。","宴錫歡談道，文成貴说诗。","用儒今作相，敦学旧爲師。","下際天光近，中来帝渥滋。","国朝良史載，能事日論思。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴得茲字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e492e2c4-7708-4cef-bf2f-dfea76a4b675', '奉和聖製途經華嶽應制', '奉和聖製途經华嶽應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["朝望蓮華嶽，神心就日來。","晴觀五千仞，仙掌拓山開。","受命金符叶，過祥玉瑞陪。","霧披乘鹿見，雲起馭龍廻。","偃樹枝封雪，殘碑石冐苔。","聖皇惟道契，文字勒巖隈。"]', '["朝望蓮华嶽，神心就日来。","晴观五千仞，仙掌拓山开。","受命金符叶，過祥玉瑞陪。","霧披乘鹿见，云起馭龙廻。","偃樹枝封雪，殘碑石冐苔。","聖皇惟道契，文字勒巖隈。"]', '诗', 'shi', '', NULL, '奉和聖製途經華嶽應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3bde44-ca15-4ad2-a27f-6b17e90a8503', '奉和聖製經河上公廟應制', '奉和聖製經河上公廟應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["河流無日夜，河上有神仙。","輦路曾經此，壇場即宛然。","下疑成洞穴，高若在空煙。","善物遺方外，和光繞道邊。","事因周史得，言與漢王傳。","喜屬膺期聖，邦家業又玄。"]', '["河流無日夜，河上有神仙。","輦路曾經此，壇場即宛然。","下疑成洞穴，高若在空煙。","善物遺方外，和光繞道邊。","事因周史得，言與漢王傳。","喜屬膺期聖，邦家業又玄。"]', '诗', 'shi', '', NULL, '奉和聖製經河上公廟應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5200f73a-f7ce-46d6-a3ab-d0c8d4c3e27b', '奉和聖製答張說出雀鼠谷', '奉和聖製答張说出雀鼠谷', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["雨施巡方罷，雲從訓俗廻。","密途汾水衞，清蹕晉郊陪。","寒著山邊盡，春當日下來。","御祠玄鳥應，仙仗綠楊開。","作頌音傳雅，觀文色動台。","更知西向樂，宸藻協鹽梅。"]', '["雨施巡方罷，云從訓俗廻。","密途汾水衞，清蹕晉郊陪。","寒著山邊尽，春當日下来。","御祠玄鸟應，仙仗綠楊开。","作頌音傳雅，观文色动台。","更知西向乐，宸藻協鹽梅。"]', '诗', 'shi', '', NULL, '奉和聖製答張說出雀鼠谷 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af16bdfe-2ca4-411d-ad24-a7ac357266eb', '奉和恩賜樂遊園宴應制', '奉和恩賜乐游园宴應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["樂遊光地選，酺飲慶天從。","座密千官盛，場開百戲容。","綠塍際山盡，緹幕倚雲重。","下上花齊發，周廻柳遍濃。","奪晴紛劒履，喧聽雜歌鐘。","日晚銜恩散，堯人倂可封。"]', '["乐游光地選，酺饮慶天從。","座密千官盛，場开百戲容。","綠塍際山尽，緹幕倚云重。","下上花齊發，周廻柳遍濃。","奪晴紛劒履，喧听杂歌鐘。","日晚銜恩散，堯人倂可封。"]', '诗', 'shi', '', NULL, '奉和恩賜樂遊園宴應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c880c6d-5286-4bf3-a293-ed05633bbfde', '恩制尚書省僚宴昆明池同用堯字', '恩制尚书省僚宴昆明池同用堯字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["露渥灑雲霄，天官次斗杓。","昆明四十里，空水極晴朝。","雁似銜紅葉，鯨疑噴海潮。","翠山來徹底，白日去廻標。","泳廣漁杈溢，浮深妓舫搖。","飽恩皆醉止，合舞共歌堯。"]', '["露渥灑云霄，天官次斗杓。","昆明四十里，空水極晴朝。","雁似銜紅葉，鯨疑噴海潮。","翠山来徹底，白日去廻標。","泳廣漁杈溢，浮深妓舫搖。","飽恩皆醉止，合舞共歌堯。"]', '诗', 'shi', '', NULL, '恩制尚書省僚宴昆明池同用堯字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e011e4f-6575-4716-8175-2ebf164df6c1', '奉和聖製幸望春宮送[朔方]大總管張仁亶', '奉和聖製幸望春宮送[朔方]大總管張仁亶', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["北風吹早雁，日夕渡河飛。","氣冷膠應折，霜明草正腓。","老臣帷幄筭，元宰廟堂機。","餞飲廻仙蹕，臨戎解御衣。","軍裝乘曉發，師律候春歸。","方佇勳庸盛，天詞降紫微。"]', '["北风吹早雁，日夕渡河飞。","氣冷膠應折，霜明草正腓。","老臣帷幄筭，元宰廟堂機。","餞饮廻仙蹕，臨戎解御衣。","軍裝乘晓發，師律候春归。","方佇勳庸盛，天词降紫微。"]', '诗', 'shi', '', NULL, '奉和聖製幸望春宮送[朔方]大總管張仁亶 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('272d85a9-94b0-4804-9198-41d061854210', '奉和聖製登太行山中言志應制', '奉和聖製登太行山中言志應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["北山東入海，馳道上連天。","順動三光柱，登臨萬象懸。","俛觀河內邑，平指洛陽川。","按蹕夷關險，張旗亙井泉。","曉巖中警柝，春事下蒐田。","德重周王問，歌輕漢后傳。","宸遊鋪令典，睿思起芳年。","願以封書奏，廻鑾禪肅然。"]', '["北山东入海，驰道上連天。","順动三光柱，登臨万象懸。","俛观河內邑，平指洛陽川。","按蹕夷关險，張旗亙井泉。","晓巖中警柝，春事下蒐田。","德重周王问，歌轻漢后傳。","宸游鋪令典，睿思起芳年。","願以封书奏，廻鑾禪肅然。"]', '诗', 'shi', '', NULL, '奉和聖製登太行山中言志應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6c933e-4db0-45b9-baba-6994d97cd657', '奉和聖製漕橋東送新除岳牧', '奉和聖製漕橋东送新除岳牧', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["寶賢不遺俊，臺閣盡鵷鸞。","未若調人切，其如簡帝難。","上才膺出典，中旨念分官。","特以專城貴，深惟列郡安。","政行思務本，風靡屬勝殘。","有令田知急，無分獄在寬。","至言題睿札，殊渥灑仙翰。","詔餞三台降，朝榮萬國歡。","舉杯臨水發，張樂擁橋觀。","式佇東封會，鏘鏘檢玉壇。"]', '["寶賢不遺俊，台閣尽鵷鸾。","未若調人切，其如簡帝难。","上才膺出典，中旨念分官。","特以專城貴，深惟列郡安。","政行思務本，风靡屬勝殘。","有令田知急，無分獄在寬。","至言題睿札，殊渥灑仙翰。","詔餞三台降，朝榮万国歡。","舉杯臨水發，張乐擁橋观。","式佇东封會，鏘鏘檢玉壇。"]', '诗', 'shi', '', NULL, '奉和聖製漕橋東送新除岳牧 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93d311bc-2861-4a45-81ed-85d07b55236d', '奉和聖製途次舊居應制', '奉和聖製途次旧居應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["潞國臨淄邸，天王別駕輿。","出潛離隱際，小往大來初。","東陸行春典，南陽即舊居。","約川星罕駐，扶道日旂舒。","雲覆連行在，風廻助掃除。","木行城邑望，臯落土田疏。","昔試邦興后，今過俗徯予。","示威寧校獵，崇讓不陳魚。","府吏趨宸扆，鄉耆捧帝車。","帳傾三飲處，閑整六飛餘。","盛業銘汾鼎，昌期應洛書。","願陪歌賦末，留比蜀相如。"]', '["潞国臨淄邸，天王別駕輿。","出潛離隐際，小往大来初。","东陸行春典，南陽即旧居。","約川星罕駐，扶道日旂舒。","云覆連行在，风廻助掃除。","木行城邑望，臯落土田疏。","昔試邦兴后，今過俗徯予。","示威寧校獵，崇讓不陳鱼。","府吏趨宸扆，乡耆捧帝车。","帳傾三饮处，闲整六飞餘。","盛業銘汾鼎，昌期應洛书。","願陪歌賦末，留比蜀相如。"]', '诗', 'shi', '', NULL, '奉和聖製途次舊居應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a4d85b-8ed4-4c17-b919-da5f41bbd8b5', '奉和聖製至長春宮登樓望稼穡之作', '奉和聖製至长春宮登楼望稼穡之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["帝迹奚其遠，皇符之所崇。","敬時堯務作，盡力禹稱功。","赫赫惟元后，經營自左馮。","變蕪秔稻實，流惡水泉通。","國阜猶前豹，人疲詎昔熊。","黃圖巡沃野，清吹入離宮。","是閱京坻富，仍觀都邑雄。","憑軒一何綺，積溜寫晴空。","禮節家安外，和平俗在中。","見龍垂渭北，辭雁指河東。","睿思方居鎬，宸遊若飲豐。","寧誇子雲從，秪爲獵扶風。"]', '["帝迹奚其远，皇符之所崇。","敬时堯務作，尽力禹稱功。","赫赫惟元后，經營自左馮。","变蕪秔稻實，流惡水泉通。","国阜猶前豹，人疲詎昔熊。","黄圖巡沃野，清吹入離宮。","是閱京坻富，仍观都邑雄。","憑軒一何綺，積溜寫晴空。","禮節家安外，和平俗在中。","见龙垂渭北，辞雁指河东。","睿思方居鎬，宸游若饮豐。","寧誇子云從，秪爲獵扶风。"]', '诗', 'shi', '', NULL, '奉和聖製至長春宮登樓望稼穡之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('724a9d0c-014d-4994-81df-aea98fa83af3', '利州北佛龕前重于去歲題處作', '利州北佛龕前重于去歲題处作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["重巖載看美，分塔起層標。","蜀守經塗處，巴人作禮朝。","地疑三界出，空是六塵銷。","臥石鋪蒼蘚，行塍覆綠條。","歲年書有記，非爲學題橋。"]', '["重巖載看美，分塔起層標。","蜀守經塗处，巴人作禮朝。","地疑三界出，空是六塵銷。","臥石鋪蒼蘚，行塍覆綠條。","歲年书有記，非爲学題橋。"]', '诗', 'shi', '', NULL, '利州北佛龕前重于去歲題處作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099ec5b8-1b41-4c45-81f1-c673e9ce9e22', '閑園即事寄韋侍郎', '闲园即事寄韋侍郎', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["結廬東城下，直望江南山。","青靄遠相接，白雲來復還。","拂筵紅蘚上，開幔綠條間。","物應春偏好，情忘趣轉閑。","憲臣饒美度，聯事惜徂顏。","有酒空盈酌，高車不可攀。"]', '["結廬东城下，直望江南山。","青靄远相接，白云来复還。","拂筵紅蘚上，开幔綠條间。","物應春偏好，情忘趣轉闲。","憲臣饒美度，聯事惜徂顏。","有酒空盈酌，高车不可攀。"]', '诗', 'shi', '', NULL, '閑園即事寄韋侍郎 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75e85c5-a231-4575-a312-6b170f3fa3ad', '扈從溫泉同紫微黃門羣公汎渭川得齊字', '扈從溫泉同紫微黄门羣公汎渭川得齊字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["虹旗映綠荑，春仗漢豐西。","侍蹕浮清渭，揚舲降紫泥。","近臨鈞石地，遙指釣璜溪。","岸轉帆飛疾，川平棹舉齊。","傅舟來是用，軒馭往應迷。","興闋菱歌動，沙洲亂夕鷖。"]', '["虹旗映綠荑，春仗漢豐西。","侍蹕浮清渭，揚舲降紫泥。","近臨鈞石地，遙指釣璜溪。","岸轉帆飞疾，川平棹舉齊。","傅舟来是用，軒馭往應迷。","兴闋菱歌动，沙洲亂夕鷖。"]', '诗', 'shi', '', NULL, '扈從溫泉同紫微黃門羣公汎渭川得齊字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da2e839-9417-462d-9c76-41208552f0a3', '餞趙尚書攝御史大夫赴朔方軍', '餞趙尚书攝御史大夫赴朔方軍', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["勁虜欲南窺，揚兵護朔陲。","趙堯寧易印，鄧禹即分麾。","野餞廻三傑，軍謀用六奇。","雲邊愁出塞，日下愴臨岐。","拔劒行人舞，揮戈戰馬馳。","明年麟閣上，充國畫於斯。"]', '["勁虜欲南窺，揚兵護朔陲。","趙堯寧易印，鄧禹即分麾。","野餞廻三傑，軍謀用六奇。","云邊愁出塞，日下愴臨岐。","拔劒行人舞，揮戈戰马驰。","明年麟閣上，充国畫於斯。"]', '诗', 'shi', '', NULL, '餞趙尚書攝御史大夫赴朔方軍 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a91f7e21-a29e-4858-a43f-fe2b6599d29b', '曉發興州入陳平路', '晓發兴州入陳平路', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["旌節指巴岷，年年行且巡。","暮來青嶂宿，朝去綠江春。","魚貫梁緣馬，猿奔樹息人。","邑祠猶是漢，溪道即名陳。","舊史饒遷謫，恆情厭苦辛。","寧知報恩者，天子一忠臣。"]', '["旌節指巴岷，年年行且巡。","暮来青嶂宿，朝去綠江春。","鱼貫梁緣马，猿奔樹息人。","邑祠猶是漢，溪道即名陳。","旧史饒遷謫，恆情厭苦辛。","寧知報恩者，天子一忠臣。"]', '诗', 'shi', '', NULL, '曉發興州入陳平路 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f178e58c-a5f5-4d73-bd2f-d98d41204804', '同餞陽將軍兼源州都督御史中丞', '同餞陽將軍兼源州都督御史中丞', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["右地接龜沙，中朝任虎牙。","然明方改俗，去病不爲家。","將禮登壇盛，軍容出塞華。","朔風搖漢鼓，邊馬思胡笳。","旗合無邀正，冠危有觸邪。","當看勞還日，及此御溝花。"]', '["右地接龟沙，中朝任虎牙。","然明方改俗，去病不爲家。","將禮登壇盛，軍容出塞华。","朔风搖漢鼓，邊马思胡笳。","旗合無邀正，冠危有觸邪。","當看勞還日，及此御溝花。"]', '诗', 'shi', '', NULL, '同餞陽將軍兼源州都督御史中丞 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f759c4-6146-4875-b3c1-95d266ca4c0b', '扈從鳳泉和崔黃門喜恩旨解嚴罷圍之作', '扈從鳳泉和崔黄门喜恩旨解嚴罷圍之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["輦路岐山曲，儲胥渭水湄。","教成提將鼓，禮備植虞旗。","不取從畋樂，先流去殺慈。","舜韶同舞日，湯祝盡飛時。","物應陽和施，人知雨露私。","何如穆天子，七萃幾勞師。"]', '["輦路岐山曲，儲胥渭水湄。","教成提將鼓，禮備植虞旗。","不取從畋乐，先流去殺慈。","舜韶同舞日，湯祝尽飞时。","物應陽和施，人知雨露私。","何如穆天子，七萃幾勞師。"]', '诗', 'shi', '', NULL, '扈從鳳泉和崔黃門喜恩旨解嚴罷圍之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480b2056-f256-430e-abd4-80a36e93da35', '秋夜寓直中書呈黃門舅', '秋夜寓直中书呈黄门舅', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["簾櫳上夜鉤，清列聽更籌。","忽共雞枝老，還如騎省秋。","循庭喜三入，對渚憶雙遊。","紫紱名初拜，黃縑迹尚留。","月舒當北幌，雲賦直東樓。","恩渥迷天施，童蒙慰我求。","遲君台鼎節，聞義一承流。"]', '["簾櫳上夜鉤，清列听更籌。","忽共雞枝老，還如騎省秋。","循庭喜三入，对渚憶雙游。","紫紱名初拜，黄縑迹尚留。","月舒當北幌，云賦直东楼。","恩渥迷天施，童蒙慰我求。","遲君台鼎節，闻義一承流。"]', '诗', 'shi', '', NULL, '秋夜寓直中書呈黃門舅 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1487f6ef-f90d-400f-9ad0-8a9d88da3d64', '先是新昌小園期京兆尹一訪兼郎官數子自頃沈痾年復一年茲願不果率然成章', '先是新昌小园期京兆尹一訪兼郎官數子自頃沈痾年复一年茲願不果率然成章', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["獨好中林隱，先期上月春。","閑花傍戶落，喧鳥逼檐馴。","寂寞東坡叟，傳呼北里人。","在山琴易調，開甕酒歸醇。","佇望應三接，彌留忽幾旬。","不疑丹火變，空負綠條新。","鬬蟻聞常日，歌龍值此辰。","其如衆君子，嘉會阻清塵。"]', '["独好中林隐，先期上月春。","闲花傍戶落，喧鸟逼檐馴。","寂寞东坡叟，傳呼北里人。","在山琴易調，开甕酒归醇。","佇望應三接，彌留忽幾旬。","不疑丹火变，空負綠條新。","鬬蟻闻常日，歌龙值此辰。","其如衆君子，嘉會阻清塵。"]', '诗', 'shi', '', NULL, '先是新昌小園期京兆尹一訪兼郎官數子自頃沈痾年復一年茲願不果率然成章 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a165caa5-f3fe-4b51-accf-1f7db97acaef', '奉和馬常侍寺中之作', '奉和马常侍寺中之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["怨暑時云謝，愆陽澤暫偏。","鼎陳從祀日，鑰動問刑年。","絳服龍雩寢，玄冠馬使旋。","作霖期傅說，爲旱聽周宣。","河嶽陰符啓，星辰暗檄傳。","浮涼吹景氣，飛動灑空煙。","颯颯將秋近，沈沈與暝連。","分湍涇水石，合穎雍州田。","德施超三五，文雄賦十千。","及斯何以樂，明主敬人天。"]', '["怨暑时云謝，愆陽澤暫偏。","鼎陳從祀日，鑰动问刑年。","絳服龙雩寢，玄冠马使旋。","作霖期傅说，爲旱听周宣。","河嶽陰符啓，星辰暗檄傳。","浮涼吹景氣，飞动灑空煙。","颯颯將秋近，沈沈與暝連。","分湍涇水石，合穎雍州田。","德施超三五，文雄賦十千。","及斯何以乐，明主敬人天。"]', '诗', 'shi', '', NULL, '奉和馬常侍寺中之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c343cd-8de3-4ad3-af44-daf643332804', '慈恩寺二月半寓言', '慈恩寺二月半寓言', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["二月韶春半，三空霽景初。","獻來應有受，滅盡竟無餘。","化迹傳官寺，歸誠謁梵居。","殿堂花覆席，觀閣柳垂疏。","共命枝間鳥，長生水上魚。","問津窺彼岸，迷路得真車。","行密幽關靜，談精俗態祛。","稻麻欣所遇，蓬籜愴焉如。","不駐秦京陌，還題蜀郡輿。","愛離方自此，廻望獨躊躇。"]', '["二月韶春半，三空霽景初。","獻来應有受，滅尽竟無餘。","化迹傳官寺，归誠謁梵居。","殿堂花覆席，观閣柳垂疏。","共命枝间鸟，长生水上鱼。","问津窺彼岸，迷路得真车。","行密幽关静，談精俗態祛。","稻麻欣所遇，蓬籜愴焉如。","不駐秦京陌，還題蜀郡輿。","愛離方自此，廻望独躊躇。"]', '诗', 'shi', '', NULL, '慈恩寺二月半寓言 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0433bf7-1dbe-4210-806a-756115c8d7b8', '餞澤州盧使君赴任', '餞澤州盧使君赴任', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["聞道降綸書，爲邦建綵旟。","政憑循吏往，才以貴卿除。","詞賦良無敵，聲華藹有餘。","榮承四岳後，請絕五天初。","關路通秦壁，城池接晉墟。","撰期行子賦，分典列侯居。","別望喧追餞，離言繫慘舒。","平蕪寒蛬亂，喬木夜蟬疎。","寥泬秋先起，推移月向諸。","舊交何以贈，客至待烹魚。"]', '["闻道降綸书，爲邦建綵旟。","政憑循吏往，才以貴卿除。","词賦良無敵，声华藹有餘。","榮承四岳後，請絕五天初。","关路通秦壁，城池接晉墟。","撰期行子賦，分典列侯居。","別望喧追餞，離言繫慘舒。","平蕪寒蛬亂，喬木夜蟬疎。","寥泬秋先起，推移月向諸。","旧交何以贈，客至待烹鱼。"]', '诗', 'shi', '', NULL, '餞澤州盧使君赴任 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47d71c5-8702-4005-89aa-c9d0d59d22a2', '陳倉別隴州司戶李維深', '陳倉別隴州司戶李維深', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["京國自攜手，同途欣解頤。","情言正的的，春物宛遲遲。","忽背雕戎役，旋瞻獲寶祠。","蜀城余出守，吳岳爾歸思。","歡愜更傷此，眷殷殊念茲。","揚麾北林徑，跂石南澗湄。","中作壺觴餞，回添道路悲。","數花臨磴日，百草覆田時。","有美同人意，無爲行子辭。","酣歌拔劒起，毋是答恩私。"]', '["京国自携手，同途欣解頤。","情言正的的，春物宛遲遲。","忽背雕戎役，旋瞻獲寶祠。","蜀城余出守，吳岳爾归思。","歡愜更傷此，眷殷殊念茲。","揚麾北林徑，跂石南澗湄。","中作壺觴餞，回添道路悲。","數花臨磴日，百草覆田时。","有美同人意，無爲行子辞。","酣歌拔劒起，毋是答恩私。"]', '诗', 'shi', '', NULL, '陳倉別隴州司戶李維深 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4590f29-ee39-4a77-8a9a-ee7b2d5a93e4', '奉和崔尚書贈大理陸卿鴻臚劉卿見示之作', '奉和崔尚书贈大理陸卿鴻臚劉卿见示之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["戲藻嘉魚樂，棲梧見鳳飛。","類從皆有召，聲應乃無違。","美價逢時出，奇才選衆稀。","避堂貽後政，掃第發前幾。","出曳仙人履，還熏侍女衣。","省中何赫奕，庭際滿芳菲。","吏部端清鑒，丞郎肅紫機。","會心歌詠是，廻迹宴言非。","北寺鄰玄闕，南城寫翠微。","參差交隱見，髣髴接光輝。","賓序嘗柔德，刑孚已霽威。","巨源林下契，不速自同歸。"]', '["戲藻嘉鱼乐，棲梧见鳳飞。","類從皆有召，声應乃無違。","美價逢时出，奇才選衆稀。","避堂貽後政，掃第發前幾。","出曳仙人履，還熏侍女衣。","省中何赫奕，庭際满芳菲。","吏部端清鑒，丞郎肅紫機。","會心歌詠是，廻迹宴言非。","北寺鄰玄闕，南城寫翠微。","參差交隐见，髣髴接光輝。","賓序嘗柔德，刑孚已霽威。","巨源林下契，不速自同归。"]', '诗', 'shi', '', NULL, '奉和崔尚書贈大理陸卿鴻臚劉卿見示之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f7d463-77d1-4621-99de-0bb7d75c04ad', '敬和崔尚書大明朝堂雨後望終南山見示之作', '敬和崔尚书大明朝堂雨後望終南山见示之作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["奕奕輕車至，清晨朝未央。","未央在霄極，中路視咸陽。","委曲漢京近，周廻秦塞長。","日華動涇渭，天翠合岐梁。","五丈旌旗色，百層枌橑光。","東連歸馬地，南指鬬雞場。","晴壑照金戺，秋雲含璧璫。","由余窺霸國，蕭相奉興王。","功役隱不見，頌聲存復揚。","權宜珍構絕，聖作寶圖昌。","在德期巢燧，居安法禹湯。","冢卿才順美，多士賦成章。","價重三臺俊，名超百郡良。","焉知掖垣下，陳力自迷方。"]', '["奕奕轻车至，清晨朝未央。","未央在霄極，中路視咸陽。","委曲漢京近，周廻秦塞长。","日华动涇渭，天翠合岐梁。","五丈旌旗色，百層枌橑光。","东連归马地，南指鬬雞場。","晴壑照金戺，秋云含璧璫。","由余窺霸国，蕭相奉兴王。","功役隐不见，頌声存复揚。","權宜珍構絕，聖作寶圖昌。","在德期巢燧，居安法禹湯。","冢卿才順美，多士賦成章。","價重三台俊，名超百郡良。","焉知掖垣下，陳力自迷方。"]', '诗', 'shi', '', NULL, '敬和崔尚書大明朝堂雨後望終南山見示之作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e16cfd7-779f-499d-8981-4c18bcb2f103', '夜聞故梓州韋使君明當引紼感而成章', '夜闻故梓州韋使君明當引紼感而成章', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["惻矣南鄰問，冥然東岱幽。","里閈寧相杵，朝歎忽遷舟。","君心惟伯仲，吾人復款遊。","對連時亦早，交喜歲纔周。","序發扶陽贈，文因司寇酬。","詎期危露盡，相續逝川流。","臥疾無三弔，居閑有百憂。","振風吟鼓夕，明月照帷秋。","蘚駁題詩館，楊疎奏伎樓。","共將歌笑歎，轉爲弟兄留。","感物存如夢，觀生去若浮。","余非忘情者，雪涕報林丘。"]', '["惻矣南鄰问，冥然东岱幽。","里閈寧相杵，朝歎忽遷舟。","君心惟伯仲，吾人复款游。","对連时亦早，交喜歲纔周。","序發扶陽贈，文因司寇酬。","詎期危露尽，相續逝川流。","臥疾無三弔，居闲有百憂。","振风吟鼓夕，明月照帷秋。","蘚駁題诗館，楊疎奏伎楼。","共將歌笑歎，轉爲弟兄留。","感物存如梦，观生去若浮。","余非忘情者，雪涕報林丘。"]', '诗', 'shi', '', NULL, '夜聞故梓州韋使君明當引紼感而成章 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cafb9d75-dac5-44e1-8cab-378fadc05fe0', '御箭連中雙兔', '御箭連中雙兔', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["宸遊經上苑，羽獵向閑田。","狡兔初迷窟，纖驪詎著鞭。","三驅仍百步，一發遂雙連。","影射含霜草，魂消向月弦。","歡聲動寒木，喜氣滿晴天。","那似陳王意，空隨樂府篇。"]', '["宸游經上苑，羽獵向闲田。","狡兔初迷窟，纖驪詎著鞭。","三驱仍百步，一發遂雙連。","影射含霜草，魂消向月弦。","歡声动寒木，喜氣满晴天。","那似陳王意，空隨乐府篇。"]', '诗', 'shi', '', NULL, '御箭連中雙兔 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82534a1-6ce6-4bc3-95d0-1dae1fd46926', '奉和聖製過潼津關', '奉和聖製過潼津关', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["在德何夷險，觀風復往還。","自能同善閉，中路可無關。"]', '["在德何夷險，观风复往還。","自能同善閉，中路可無关。"]', '诗', 'shi', '', NULL, '奉和聖製過潼津關 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('073133f4-f34c-44ec-acb2-660756d928a1', '山鷓鴣詞二首 一', '山鷓鴣词二首 一', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["玉關征戍久，空閨人獨愁。","寒露濕青苔，別來蓬鬢秋。"]', '["玉关征戍久，空閨人独愁。","寒露濕青苔，別来蓬鬢秋。"]', '诗', 'shi', '', NULL, '山鷓鴣詞二首 一 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f70a3e-e6da-4a66-b6b9-bb42a35b51ed', '山鷓鴣詞二首 二', '山鷓鴣词二首 二', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["人坐青樓晚，鶯語百花時。","愁多人易老，斷腸君不知。"]', '["人坐青楼晚，鶯語百花时。","愁多人易老，斷腸君不知。"]', '诗', 'shi', '', NULL, '山鷓鴣詞二首 二 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1ba6888-e597-44f5-bd3d-bff5269c01ef', '汾上驚秋', '汾上驚秋', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["北風吹白雲，萬里渡河汾。","心緒逢搖落，秋聲不可聞。"]', '["北风吹白云，万里渡河汾。","心緒逢搖落，秋声不可闻。"]', '诗', 'shi', '', NULL, '汾上驚秋 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d64caa29-2d76-4651-a114-b97b4c9b4653', '山驛閑臥即事', '山驛闲臥即事', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["息燕歸檐靜，飛花落院閑。","不愁愁自著，誰道憶鄉關。"]', '["息燕归檐静，飞花落院闲。","不愁愁自著，誰道憶乡关。"]', '诗', 'shi', '', NULL, '山驛閑臥即事 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af472b91-a1ce-4f19-8805-abb0874944b7', '將赴益州題小園壁', '將赴益州題小园壁', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["歲窮惟益老，春至却辭家。","可惜東園樹，無人也作花。"]', '["歲窮惟益老，春至却辞家。","可惜东园樹，無人也作花。"]', '诗', 'shi', '', NULL, '將赴益州題小園壁 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3332e9-634d-45e6-a849-faf191b1b666', '詠禮部尚書廳後鵲', '詠禮部尚书廳後鵲', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["懷印喜將歸，窺巢戀且依。","自知棲不定，還欲向南飛。"]', '["懷印喜將归，窺巢戀且依。","自知棲不定，還欲向南飞。"]', '诗', 'shi', '', NULL, '詠禮部尚書廳後鵲 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4e4695-e506-4cda-8fbb-b9bdf36e37c4', '詠死兔', '詠死兔', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["兔子死蘭彈，持來挂竹竿。","試將明鏡照，何異月中看。"]', '["兔子死蘭彈，持来挂竹竿。","試將明镜照，何異月中看。"]', '诗', 'shi', '', NULL, '詠死兔 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c189fa3a-1dba-46dc-a331-5b3858244833', '夜宴安樂公主新宅', '夜宴安乐公主新宅', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["車如流水馬如龍，仙使高臺十二重。","天上初移衡漢匹，可憐歌舞夜相從。"]', '["车如流水马如龙，仙使高台十二重。","天上初移衡漢匹，可怜歌舞夜相從。"]', '诗', 'shi', '', NULL, '夜宴安樂公主新宅 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b08a0438-59c1-465f-8726-137def260b0a', '侍宴桃花園詠桃花應制', '侍宴桃花园詠桃花應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["桃花灼灼有光輝，無數成蹊點更飛。","爲見芳林含笑待，遂同溫樹不言歸。"]', '["桃花灼灼有光輝，無數成蹊点更飞。","爲见芳林含笑待，遂同溫樹不言归。"]', '诗', 'shi', '', NULL, '侍宴桃花園詠桃花應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e90122-c223-4ddd-aeca-44a4738a23e7', '奉和聖製幸韋嗣立莊應制', '奉和聖製幸韋嗣立莊應制', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["樹色參差隱翠微，泉流百尺向空飛。","傳聞此處投竿住，遂使茲辰扈蹕歸。"]', '["樹色參差隐翠微，泉流百尺向空飞。","傳闻此处投竿住，遂使茲辰扈蹕归。"]', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立莊應制 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bcf6a35-c030-4300-8456-c73468bed27b', '重送舒公', '重送舒公', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["散騎金貂服綵衣，松花水上逐春歸。","懸知邑里遙相望，事主榮親代所稀。"]', '["散騎金貂服綵衣，松花水上逐春归。","懸知邑里遙相望，事主榮親代所稀。"]', '诗', 'shi', '', NULL, '重送舒公 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960b0f7c-d350-46a9-a562-6f9c11924001', '句', '句', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["飛埃結紅霧，遊蓋飄青雲。","指如十挺墨，耳似兩張匙。","丑雖有足，甲不全身。","見君無口，知伊少人。"]', '["飞埃結紅霧，游蓋飄青云。","指如十挺墨，耳似兩張匙。","丑雖有足，甲不全身。","见君無口，知伊少人。"]', '诗', 'shi', '', NULL, '句 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1968045e-1a76-4187-b179-c5d9f91e862a', '龍池篇', '龙池篇', '45fee343-dafe-43fa-81fa-78f3aa5a597b', '唐', '["靈沼縈廻邸第前，浴日涵春寫曙天。","始見龍臺昇鳳闕，應如霄漢起神泉。","石匱渚傍還啓聖，桃李初生更有仙。","欲化帝圖從此受，正同河變一千年。"]', '["靈沼縈廻邸第前，浴日涵春寫曙天。","始见龙台昇鳳闕，應如霄漢起神泉。","石匱渚傍還啓聖，桃李初生更有仙。","欲化帝圖從此受，正同河变一千年。"]', '诗', 'shi', '', NULL, '龍池篇 姜晞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0f58f9-78ac-4a46-960e-e062279aae09', '龍池篇', '龙池篇', '8d472220-48a8-47cb-8921-181c3be51277', '唐', '["龍池初出此龍山，常經此地謁龍顏。","日日芙蓉生夏水，年年楊柳變春灣。","堯壇寶匣餘煙霧，舜海漁舟尚往還。","願似飄颻五雲影，從來從去九天關。"]', '["龙池初出此龙山，常經此地謁龙顏。","日日芙蓉生夏水，年年楊柳变春灣。","堯壇寶匣餘煙霧，舜海漁舟尚往還。","願似飄颻五云影，從来從去九天关。"]', '诗', 'shi', '', NULL, '龍池篇 姜皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c07ae22d-3b74-4882-9ff9-2192cffa7cb8', '奉和聖製龍池篇', '奉和聖製龙池篇', '41885324-7aab-40d5-9f60-d2d3a49f5ea3', '唐', '["帝宅王家大道邊，神馬潛龍湧聖泉。","昔日昔時經此地，看來看去漸成川。","歌臺舞榭宜正月，柳岸梅洲勝往年。","莫疑波上春雲少，祗爲從龍直上天。"]', '["帝宅王家大道邊，神马潛龙湧聖泉。","昔日昔时經此地，看来看去漸成川。","歌台舞榭宜正月，柳岸梅洲勝往年。","莫疑波上春云少，祗爲從龙直上天。"]', '诗', 'shi', '', NULL, '奉和聖製龍池篇 蔡孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6e774be-f813-4612-a0b9-fe0f06ce52df', '打毬篇', '打毬篇', '41885324-7aab-40d5-9f60-d2d3a49f5ea3', '唐', '["德陽宮北苑東頭，雲作高臺月作樓。","金鎚玉鎣千金地，寶杖琱文七寶毬。","竇融一家三尚主，梁翼頻封萬戶侯。","容色由來荷恩顧，意氣平生事俠游。","共道用兵如斷蔗，俱能走馬入長楸。","紅鬣錦鬃風騄驥，黃絡青絲電紫騮。","奔星亂下花場裏，初月飛來畫杖頭。","自有長鳴須決勝，能馳迅走滿先籌。","薄暮漢宮愉樂罷，還歸堯室曉垂旒。"]', '["德陽宮北苑东头，云作高台月作楼。","金鎚玉鎣千金地，寶杖琱文七寶毬。","竇融一家三尚主，梁翼頻封万戶侯。","容色由来荷恩顧，意氣平生事俠游。","共道用兵如斷蔗，俱能走马入长楸。","紅鬣錦鬃风騄驥，黄絡青絲電紫騮。","奔星亂下花場裏，初月飞来畫杖头。","自有长鳴須決勝，能驰迅走满先籌。","薄暮漢宮愉乐罷，還归堯室晓垂旒。"]', '诗', 'shi', '', NULL, '打毬篇 蔡孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4cbfbef-0ae9-4323-be18-1c0d2d6b1765', '阮公體', '阮公體', '20c0c5c9-4f85-4ccf-9138-74d05f493c92', '唐', '["秦王按劒怒，發卒戍龍沙。","雄圖尚未畢，海內已紛拏。","黃塵暗天起，白日斂精華。","唯見長城外，僵屍如亂麻。"]', '["秦王按劒怒，發卒戍龙沙。","雄圖尚未畢，海內已紛拏。","黄塵暗天起，白日斂精华。","唯见长城外，僵屍如亂麻。"]', '诗', 'shi', '', NULL, '阮公體 徐晶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ffe32aa-74ce-4b31-88c0-d968a9c25868', '同蔡孚五亭詠', '同蔡孚五亭詠', '20c0c5c9-4f85-4ccf-9138-74d05f493c92', '唐', '["章奏中京罷，雲泉別業歸。","拂琴鋪野席，牽柳挂朝衣。","翡翠巢書幌，鴛鴦立釣磯。","幽栖可憐處，春事滿林扉。"]', '["章奏中京罷，云泉別業归。","拂琴鋪野席，牽柳挂朝衣。","翡翠巢书幌，鴛鴦立釣磯。","幽栖可怜处，春事满林扉。"]', '诗', 'shi', '', NULL, '同蔡孚五亭詠 徐晶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf5474c-9599-4d70-a33e-d6b3762a8a92', '蔡起居山亭', '蔡起居山亭', '20c0c5c9-4f85-4ccf-9138-74d05f493c92', '唐', '["文史歸休日，棲閑臥草亭。","薔薇一架紫，石竹數重青。","垂露和仙藥，燒香誦道經。","莫將山水弄，持與世人聽。"]', '["文史归休日，棲闲臥草亭。","薔薇一架紫，石竹數重青。","垂露和仙藥，燒香誦道經。","莫將山水弄，持與世人听。"]', '诗', 'shi', '', NULL, '蔡起居山亭 徐晶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a786eb7-31b2-40aa-aa3f-e3b4f413d20d', '送友人尉蜀中', '送友人尉蜀中', '20c0c5c9-4f85-4ccf-9138-74d05f493c92', '唐', '["故友漢中尉，請爲西蜀吟。","人家多種橘，風土愛彈琴。","水向昆明闊，山連大夏深。","理閑無別事，時寄一登臨。"]', '["故友漢中尉，請爲西蜀吟。","人家多種橘，风土愛彈琴。","水向昆明闊，山連大夏深。","理闲無別事，时寄一登臨。"]', '诗', 'shi', '', NULL, '送友人尉蜀中 徐晶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2af7241-0327-4b95-8a7d-8b8ff273c259', '贈溫駙馬汝陽王', '贈溫駙马汝陽王', '20c0c5c9-4f85-4ccf-9138-74d05f493c92', '唐', '["疇昔承餘論，文章幸濫推。","夜陪銀漢賞，朝奉桂山詞。","梁邸調歌日，秦樓按舞時。","登高頻作賦，體物屢爲詩。","連騎長楸下，浮觴曲水湄。","北堂留上客，南陌送佳期。","憶昨陪臨泛，于今阻宴私。","再看冬雪滿，三見夏花滋。","都尉朝青閣，淮王侍紫墀。","寧知倦遊者，華髪老京師。"]', '["疇昔承餘論，文章幸濫推。","夜陪銀漢賞，朝奉桂山词。","梁邸調歌日，秦楼按舞时。","登高頻作賦，體物屢爲诗。","連騎长楸下，浮觴曲水湄。","北堂留上客，南陌送佳期。","憶昨陪臨泛，于今阻宴私。","再看冬雪满，三见夏花滋。","都尉朝青閣，淮王侍紫墀。","寧知倦游者，华髪老京師。"]', '诗', 'shi', '', NULL, '贈溫駙馬汝陽王 徐晶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7019fd63-f6fd-4cd5-a2e5-671078b50111', '邊詞', '邊词', '60996138-e4e3-4185-8985-98d3b0f8ff26', '唐', '["五原春色舊來遲，二月垂楊未挂絲。","即今河畔冰開日，正是長安花落時。"]', '["五原春色旧来遲，二月垂楊未挂絲。","即今河畔冰开日，正是长安花落时。"]', '诗', 'shi', '', NULL, '邊詞 張敬忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92b10870-5311-40de-9320-deff9ca2990e', '戲詠', '戲詠', '60996138-e4e3-4185-8985-98d3b0f8ff26', '唐', '["有意嫌兵部，專心望考功。","誰知脚蹭蹬，幾落省牆東。"]', '["有意嫌兵部，專心望考功。","誰知脚蹭蹬，幾落省牆东。"]', '诗', 'shi', '', NULL, '戲詠 張敬忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21471a45-63f0-4f96-8ba7-3b9ac2a162a5', '題巴州光福寺楠木', '題巴州光福寺楠木', '5b701055-33e8-4e80-9483-dab920f1f117', '唐', '["近郭城南山寺深，亭亭奇樹出禪林。","結根幽壑不知歲，聳幹摩天凡幾尋。","翠色晚將嵐氣合，月光時有夜猨吟。","經行綠葉望成蓋，宴坐黃花長滿襟。","此木嘗聞生豫章，今朝獨秀在巴鄉。","凌霜不肯讓松柏，作宇由來稱棟梁。","會待良工時一眄，應歸法水作慈航。"]', '["近郭城南山寺深，亭亭奇樹出禪林。","結根幽壑不知歲，聳幹摩天凡幾尋。","翠色晚將嵐氣合，月光时有夜猨吟。","經行綠葉望成蓋，宴坐黄花长满襟。","此木嘗闻生豫章，今朝独秀在巴乡。","凌霜不肯讓松柏，作宇由来稱棟梁。","會待良工时一眄，應归法水作慈航。"]', '诗', 'shi', '', NULL, '題巴州光福寺楠木 史俊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d13adc-024e-48c2-9a96-ebaf0bd5f1af', '儀坤廟樂章 永和', '儀坤廟乐章 永和', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["猗若清廟，肅肅熒熒。","國薦嚴祀，坤興淑靈。","有几在室，有樂在庭。","臨茲孝享，百祿惟寧。"]', '["猗若清廟，肅肅熒熒。","国薦嚴祀，坤兴淑靈。","有几在室，有乐在庭。","臨茲孝享，百祿惟寧。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 永和 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f91dcc-2a26-4bc4-93ca-aa2d0811fe47', '儀坤廟樂章 金奏', '儀坤廟乐章 金奏', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["陰靈效祉，軒曜降精。","祥符淑氣，慶集柔明。","瑤俎既列，雕桐發聲。","徽猷永遠，比德皇英。"]', '["陰靈效祉，軒曜降精。","祥符淑氣，慶集柔明。","瑤俎既列，雕桐發声。","徽猷永远，比德皇英。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 金奏 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07392d27-cd64-4ece-81c2-bff93cec802f', '擬古三首 一', '擬古三首 一', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["遙裔煙嶼鴻，雙影旦夕同。","交翰倚沙月，和鳴弄江風。","𦶜若茂芳序，君子從遠戎。","雲生陰海沒，花落春潭空。","紅淚掩促柱，錦衾羅薰籠。","自傷瓊草綠，詎惜鉛粉紅。","裂帛附雙燕，爲予向遼東。"]', '["遙裔煙嶼鴻，雙影旦夕同。","交翰倚沙月，和鳴弄江风。","𦶜若茂芳序，君子從远戎。","云生陰海沒，花落春潭空。","紅泪掩促柱，錦衾羅薰籠。","自傷瓊草綠，詎惜鉛粉紅。","裂帛附雙燕，爲予向遼东。"]', '诗', 'shi', '', NULL, '擬古三首 一 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6cf477-56b1-4cae-98c1-6767f931f43c', '擬古三首 二', '擬古三首 二', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["讀書三十載，馳騖周六經。","儒衣干時主，忠策獻闕廷。","一朝奉休盼，從容廁羣英。","束身趨建禮，秉筆坐承明。","廨署相填噎，僚吏紛縱橫。","五日休澣時，屠蘇繞玉屏。","橘花覆北沼，桂樹交西榮。","樹棲兩鴛鴦，含春向我鳴。","皎潔綺羅豔，便娟絲管清。","擾擾天地間，出處各有情。","何必巖石下，枯槁閑此生。"]', '["读书三十載，驰騖周六經。","儒衣干时主，忠策獻闕廷。","一朝奉休盼，從容廁羣英。","束身趨建禮，秉笔坐承明。","廨署相填噎，僚吏紛縱橫。","五日休澣时，屠蘇繞玉屏。","橘花覆北沼，桂樹交西榮。","樹棲兩鴛鴦，含春向我鳴。","皎潔綺羅豔，便娟絲管清。","擾擾天地间，出处各有情。","何必巖石下，枯槁闲此生。"]', '诗', 'shi', '', NULL, '擬古三首 二 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb153ef-db2d-4222-b72e-f762b9f6ef6d', '擬古三首 三', '擬古三首 三', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["頽光無淹晷，逝水有迅流。","綠苔紛易歇，紅顏不再求。","歌笑當及春，無令壯志秋。","弱年仕關輔，簃門豁御溝。","敷愉東城際，婉孌南陌頭。","荷花嬌綠水，楊葉暖青樓。","中有綺羅人，可憐名莫愁。","畫屏繞金膝，珠簾懸玉鉤。","纖指調寶琴，泠泠哀且柔。","贈君鴛鴦帶，因以鷫鸘裘。","窗曉吟日坐，閨夕秉燭遊。","無作北門客，咄咄懷百憂。"]', '["頽光無淹晷，逝水有迅流。","綠苔紛易歇，紅顏不再求。","歌笑當及春，無令壯志秋。","弱年仕关輔，簃门豁御溝。","敷愉东城際，婉孌南陌头。","荷花嬌綠水，楊葉暖青楼。","中有綺羅人，可怜名莫愁。","畫屏繞金膝，珠簾懸玉鉤。","纖指調寶琴，泠泠哀且柔。","贈君鴛鴦带，因以鷫鸘裘。","窗晓吟日坐，閨夕秉燭游。","無作北门客，咄咄懷百憂。"]', '诗', 'shi', '', NULL, '擬古三首 三 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66bce47c-a620-4325-a2d2-15d8f9029a65', '贈劉舍人古意', '贈劉舍人古意', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["女牀閟靈鳥，文章世所希。","巢君碧梧樹，舞君青瑣闈。","或言鳳池樂，撫翼更西飛。","鳳池環禁林，仙閣靄沈沈。","璇題激流日，珠綴緜清陰。","郁穆絲言重，熒煌台座深。","風張丹戺翮，月弄紫庭音。","衆綵結不散，孤英跂莫尋。","浩歌在西省，經傳恣潛心。"]', '["女牀閟靈鸟，文章世所希。","巢君碧梧樹，舞君青瑣闈。","或言鳳池乐，撫翼更西飞。","鳳池环禁林，仙閣靄沈沈。","璇題激流日，珠綴緜清陰。","郁穆絲言重，熒煌台座深。","风張丹戺翮，月弄紫庭音。","衆綵結不散，孤英跂莫尋。","浩歌在西省，經傳恣潛心。"]', '诗', 'shi', '', NULL, '贈劉舍人古意 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23adc9b6-feae-46b8-bed7-dc3ff8cee505', '和李適荅宋十一入崖口五渡見贈', '和李適荅宋十一入崖口五渡见贈', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["聞有獨往客，拂衣捐世心。","結欣薄枉渚，撰念縈舊林。","經亙去崖合，冥緜歸壑深。","琪樹環碧彩，金潭生翠陰。","沿洄弄沙榜，詭仄眺明岑。","夕聞桂裏猿，曉玩松上禽。","雜佩蘊孤袖，瓊敷綴雙襟。","我懷滄州想，懿爾白雲吟。","秉願理方協，存期跡易尋。","茲言庶不負，爲報巖中琴。"]', '["闻有独往客，拂衣捐世心。","結欣薄枉渚，撰念縈旧林。","經亙去崖合，冥緜归壑深。","琪樹环碧彩，金潭生翠陰。","沿洄弄沙榜，詭仄眺明岑。","夕闻桂裏猿，晓玩松上禽。","杂佩蘊孤袖，瓊敷綴雙襟。","我懷滄州想，懿爾白云吟。","秉願理方協，存期跡易尋。","茲言庶不負，爲報巖中琴。"]', '诗', 'shi', '', NULL, '和李適荅宋十一入崖口五渡見贈 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a522ec36-b5d3-451d-9915-aa2aa033611e', '雪', '雪', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["雪暗窮海雲，灑空紛似露。","朔風吹故里，宛轉玉階樹。","孤妾調玉瑟，早寒生錦衿。","況君張羅幕，愁坐北庭陰。"]', '["雪暗窮海云，灑空紛似露。","朔风吹故里，宛轉玉階樹。","孤妾調玉瑟，早寒生錦衿。","況君張羅幕，愁坐北庭陰。"]', '诗', 'shi', '', NULL, '雪 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d35693-84ca-4c7c-bf03-14c690229114', '比干墓', '比干墓', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["大位天下寶，維賢國之鎮。","殷道微而在，受辛纂頹胤。","山鳴鬼又哭，地裂川亦震。","媟黷皆佞諛，虔劉盡英雋。","孤卿帝叔父，特進貞而順。","玉牀逾皜潔，銅柱方歊焮。","奉國歷三朝，觀竅明一瞬。","季代猖狂主，蓄怒提白刃。","之子彌忠讜，憤然更勇進。","撫膺誓隕越，知死故不恡。","已矣竟剖心，哲婦亦同殉。","驪龍暴雙骨，太嶽摧孤仞。","周發次商郊，冤骸悲莫殣。","鋒劒剿遺孽，報復一何迅。","駐罕歌淑靈，命徒對旅櫬。","自爾銜幽酷，于嗟流景駿。","丘墳被宿莽，壇戺緣飛燐。","貞觀戒北征，維皇念忠信。","荒墳護草木，刻桷吹煨燼。","代遠恩更崇，身頹名益振。","帝詞書樂石，國饌羅芳衅。","偉哉烈士圖，奇英千古徇。"]', '["大位天下寶，維賢国之鎮。","殷道微而在，受辛纂頹胤。","山鳴鬼又哭，地裂川亦震。","媟黷皆佞諛，虔劉尽英雋。","孤卿帝叔父，特進貞而順。","玉牀逾皜潔，銅柱方歊焮。","奉国歷三朝，观竅明一瞬。","季代猖狂主，蓄怒提白刃。","之子彌忠讜，憤然更勇進。","撫膺誓隕越，知死故不恡。","已矣竟剖心，哲婦亦同殉。","驪龙暴雙骨，太嶽摧孤仞。","周發次商郊，冤骸悲莫殣。","鋒劒剿遺孽，報复一何迅。","駐罕歌淑靈，命徒对旅櫬。","自爾銜幽酷，于嗟流景駿。","丘墳被宿莽，壇戺緣飞燐。","貞观戒北征，維皇念忠信。","荒墳護草木，刻桷吹煨燼。","代远恩更崇，身頹名益振。","帝词书乐石，国饌羅芳衅。","偉哉烈士圖，奇英千古徇。"]', '诗', 'shi', '', NULL, '比干墓 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a49db0-2593-4970-8c06-575793339ef5', '題東山子李適碑陰二首 一', '題东山子李適碑陰二首 一', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["隴嶂縈紫氣，金光赫氛氳。","美人含遙靄，桃李芳自薰。","圖高黃鶴羽，寶奪驪龍羣。","忽驚薤露曲，掩噎東山雲。"]', '["隴嶂縈紫氣，金光赫氛氳。","美人含遙靄，桃李芳自薰。","圖高黄鹤羽，寶奪驪龙羣。","忽驚薤露曲，掩噎东山云。"]', '诗', 'shi', '', NULL, '題東山子李適碑陰二首 一 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c506501a-0db9-4711-af71-ff9a4c843ab0', '題東山子李適碑陰二首 二', '題东山子李適碑陰二首 二', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["回也寔夭折，賈生亦脆促。","今復哀若人，危光迅風燭。","夜臺淪清鏡，窮塵埋結綠。","何以贈下泉，生芻唯一束。"]', '["回也寔夭折，賈生亦脆促。","今复哀若人，危光迅风燭。","夜台淪清镜，窮塵埋結綠。","何以贈下泉，生芻唯一束。"]', '诗', 'shi', '', NULL, '題東山子李適碑陰二首 二 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d3d7e2a-a3e2-49a1-8715-885be099d975', '淮亭吟', '淮亭吟', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["貞寂慮兮淮山幽，憐芳若兮{臨/手}中洲。","崩湍委咽日夜流，孤客危坐心自愁。","矧鶴唳兮風曉，復猿鳴兮霜秋。","熠耀飛兮蟋蟀吟，倚清瑟兮橫涼琴。","擷瑤芳兮弔楚水，弄琪樹兮歌越岑。","山碕礒兮隈曲，水涓漣兮洞汩。","金光延起兮驟興沒，青苔竟兮綠蘋歇。","綠蘋歇兮凋朱顏，美人寂歷兮何時閑。","君不見可憐桐柏上，丰茸桂樹花滿山。"]', '["貞寂慮兮淮山幽，怜芳若兮{臨/手}中洲。","崩湍委咽日夜流，孤客危坐心自愁。","矧鹤唳兮风晓，复猿鳴兮霜秋。","熠耀飞兮蟋蟀吟，倚清瑟兮橫涼琴。","擷瑤芳兮弔楚水，弄琪樹兮歌越岑。","山碕礒兮隈曲，水涓漣兮洞汩。","金光延起兮驟兴沒，青苔竟兮綠蘋歇。","綠蘋歇兮凋朱顏，美人寂歷兮何时闲。","君不见可怜桐柏上，丰茸桂樹花满山。"]', '诗', 'shi', '', NULL, '淮亭吟 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55378635-c0b2-4981-8ebd-984f701254f3', '芳樹', '芳樹', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["玉花珍簟上，金縷畫屏開。","曉月憐箏柱，春風憶鏡臺。","箏柱春風吹曉月，芳樹落花朝暝歇。","藁砧刀頭未有期，攀條拭淚坐相思。"]', '["玉花珍簟上，金縷畫屏开。","晓月怜箏柱，春风憶镜台。","箏柱春风吹晓月，芳樹落花朝暝歇。","藁砧刀头未有期，攀條拭泪坐相思。"]', '诗', 'shi', '', NULL, '芳樹 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d55004-2190-445a-ae0d-93019399814c', '遊禁苑幸臨渭亭遇雪應制', '游禁苑幸臨渭亭遇雪應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["玉律藏冰候，彤階飛雪時。","日寒消不盡，風定舞還遲。","瓊樹留宸矚，璇花入睿詞。","懸知穆天子，黃竹謾言詩。"]', '["玉律藏冰候，彤階飞雪时。","日寒消不尽，风定舞還遲。","瓊樹留宸矚，璇花入睿词。","懸知穆天子，黄竹謾言诗。"]', '诗', 'shi', '', NULL, '遊禁苑幸臨渭亭遇雪應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639e344f-ab9d-4e52-9636-522c1a2ab6c7', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["鳳扆憐簫曲，鸞閨念掌珍。","羗庭遙築館，廟策重和親。","星轉銀河夕，花移玉樹春。","聖心悽送遠，留蹕望征塵。"]', '["鳳扆怜簫曲，鸾閨念掌珍。","羗庭遙築館，廟策重和親。","星轉銀河夕，花移玉樹春。","聖心悽送远，留蹕望征塵。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75f8ca4-73ec-42d4-946c-70114adf3cec', '幸白鹿觀應制', '幸白鹿观應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["鳳輿乘八景，龜籙向三仙。","日月移平地，雲霞綴小天。","金童擎紫藥，玉女獻青蓮。","花洞留宸賞，還旗繞夕煙。"]', '["鳳輿乘八景，龟籙向三仙。","日月移平地，云霞綴小天。","金童擎紫藥，玉女獻青蓮。","花洞留宸賞，還旗繞夕煙。"]', '诗', 'shi', '', NULL, '幸白鹿觀應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d12488-6e3c-448a-8265-405aad907a9e', '胡無人行', '胡無人行', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["十月繁霜下，征人遠鑿空。","雲搖錦車節，海照角端弓。","暗磧埋沙樹，衝飆卷塞蓬。","方隨膜拜入，歌舞玉門中。"]', '["十月繁霜下，征人远鑿空。","云搖錦车節，海照角端弓。","暗磧埋沙樹，衝飆卷塞蓬。","方隨膜拜入，歌舞玉门中。"]', '诗', 'shi', '', NULL, '胡無人行 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a49d9ba0-a3ca-44d1-84ae-0126e317b860', '倢伃', '倢伃', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["君恩忽斷絕，妾思終未央。","巾櫛不可見，枕席空餘香。","窗暗網羅白，階秋苔蘚黃。","應門寂已閉，流涕向昭陽。"]', '["君恩忽斷絕，妾思終未央。","巾櫛不可见，枕席空餘香。","窗暗網羅白，階秋苔蘚黄。","應门寂已閉，流涕向昭陽。"]', '诗', 'shi', '', NULL, '倢伃 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a679494b-8d44-46b1-a877-343aeeee8690', '採蓮曲', '採蓮曲', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["妾家越水邊，搖艇入江煙。","既覓同心侶，復采同心蓮。","折藕絲能脆，開花葉正圓。","春歌弄明月，歸櫂落花前。"]', '["妾家越水邊，搖艇入江煙。","既覓同心侶，复采同心蓮。","折藕絲能脆，开花葉正圓。","春歌弄明月，归櫂落花前。"]', '诗', 'shi', '', NULL, '採蓮曲 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48449de7-a3f4-4bb8-8b50-3351b010728c', '孤燭歎', '孤燭歎', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["切切夜閨冷，微微孤燭然。","玉盤紅淚滴，金燼彩光圓。","煖手縫輕素，嚬蛾續斷弦。","相思咽不語，回向錦屏眠。"]', '["切切夜閨冷，微微孤燭然。","玉盤紅泪滴，金燼彩光圓。","煖手縫轻素，嚬蛾續斷弦。","相思咽不語，回向錦屏眠。"]', '诗', 'shi', '', NULL, '孤燭歎 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b17fa571-dc81-44c9-8dea-bf533a313f1f', '閨怨', '閨怨', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["征客戍金微，愁閨獨掩扉。","塵埃生半榻，花絮落殘機。","褪暖蠶初臥，巢昏燕欲歸。","春風日向盡，銜涕作征衣。"]', '["征客戍金微，愁閨独掩扉。","塵埃生半榻，花絮落殘機。","褪暖蠶初臥，巢昏燕欲归。","春风日向尽，銜涕作征衣。"]', '诗', 'shi', '', NULL, '閨怨 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e140b170-2321-45b7-bc93-32fc6940583f', '餞唐州高使君赴任', '餞唐州高使君赴任', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["香萼媚紅滋，垂條縈綠絲。","情人拂瑤袂，共惜此芳時。","驌驦已躑躅，鳥隼方葳蕤。","跂予望太守，流潤及京師。"]', '["香萼媚紅滋，垂條縈綠絲。","情人拂瑤袂，共惜此芳时。","驌驦已躑躅，鸟隼方葳蕤。","跂予望太守，流潤及京師。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28b4557-dc2e-4479-b5f0-c1c5918ac1ab', '奉和幸新豐溫泉宮應制', '奉和幸新豐溫泉宮應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["姬典歌時邁，虞篇記省方。","何如黑帝月，玄覽白雲鄉。","翠仗縈船岸，明斾應萯陽。","風搖花眊彩，雪豔寶戈芒。","御陌開函次，離宮夾樹行。","桂枝籠騕褭，松葉覆堂皇。","仙石含珠液，溫池孕璧房。","湧疑神瀵溢，澄若帝臺漿。","獨沸流常熱，潛蒸氣轉香。","青壇環玉甃，紅礎鑠金光。","藻曜凝芳潔，葳蕤獻淑祥。","五龍歸寶算，九鳸叶時康。","同預華封老，中衢祝聖皇。"]', '["姬典歌时邁，虞篇記省方。","何如黑帝月，玄覽白云乡。","翠仗縈船岸，明斾應萯陽。","风搖花眊彩，雪豔寶戈芒。","御陌开函次，離宮夾樹行。","桂枝籠騕褭，松葉覆堂皇。","仙石含珠液，溫池孕璧房。","湧疑神瀵溢，澄若帝台漿。","独沸流常熱，潛蒸氣轉香。","青壇环玉甃，紅礎鑠金光。","藻曜凝芳潔，葳蕤獻淑祥。","五龙归寶算，九鳸叶时康。","同預华封老，中衢祝聖皇。"]', '诗', 'shi', '', NULL, '奉和幸新豐溫泉宮應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6ae174-8f7a-46cc-acdf-b70ae2699fa9', '同韋舍人元旦早朝', '同韋舍人元旦早朝', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["夕轉清壺漏，晨驚長樂鐘。","逶迤綸禁客，假寐守銅龍。","予亦趨三殿，肩隨謁九重。","繁珂接曙響，華劒比春容。","相問韶光歇，彌憐芳意濃。","願言乘日旰，攜手即雲峰。"]', '["夕轉清壺漏，晨驚长乐鐘。","逶迤綸禁客，假寐守銅龙。","予亦趨三殿，肩隨謁九重。","繁珂接曙响，华劒比春容。","相问韶光歇，彌怜芳意濃。","願言乘日旰，携手即云峰。"]', '诗', 'shi', '', NULL, '同韋舍人元旦早朝 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9219812-4991-4b67-bf28-6c03c5bc994f', '侍宴韋嗣立山莊應制', '侍宴韋嗣立山莊應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["鼎臣休澣隙，方外結遙心。","別業青霞境，孤潭碧樹林。","每馳東墅策，遙弄北溪琴。","帝眷紓時豫，台園賞歲陰。","移鑾明月沼，張組白雲岑。","御酒瑤觴落，仙壇竹徑深。","三光懸聖藻，五等冠朝簪。","自昔皇恩感，咸言獨自今。"]', '["鼎臣休澣隙，方外結遙心。","別業青霞境，孤潭碧樹林。","每驰东墅策，遙弄北溪琴。","帝眷紓时豫，台园賞歲陰。","移鑾明月沼，張組白云岑。","御酒瑤觴落，仙壇竹徑深。","三光懸聖藻，五等冠朝簪。","自昔皇恩感，咸言独自今。"]', '诗', 'shi', '', NULL, '侍宴韋嗣立山莊應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db82ea8-264d-4ae4-b437-ae9e05f2a5d7', '送特進李嶠入都祔廟', '送特進李嶠入都祔廟', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["特進三公下，台臣百揆先。","孝圖開寢石，祠主卜牲筵。","恩級青綸賜，徂裝紫橐懸。","綢繆金鼎席，宴餞玉潢川。","北斗分征路，東山起贈篇。","樂池歌綠藻，梁苑藉紅荃。","騎轉商巖日，旌搖關塞煙。","廟堂須鯁議，錦節佇來旋。"]', '["特進三公下，台臣百揆先。","孝圖开寢石，祠主卜牲筵。","恩級青綸賜，徂裝紫橐懸。","綢繆金鼎席，宴餞玉潢川。","北斗分征路，东山起贈篇。","乐池歌綠藻，梁苑藉紅荃。","騎轉商巖日，旌搖关塞煙。","廟堂須鯁議，錦節佇来旋。"]', '诗', 'shi', '', NULL, '送特進李嶠入都祔廟 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18a2a2d-2c0d-4a00-b5b8-4945581158d8', '春閨', '春閨', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["戍客戍清波，幽閨幽思多。","暗梁聞語燕，夜燭見飛蛾。","寶鴨藏脂粉，金屏綴綺羅。","裁衣卷紋素，織錦度鳴梭。","有使通西極，緘書寄北河。","年光只恐盡，征戰莫蹉跎。"]', '["戍客戍清波，幽閨幽思多。","暗梁闻語燕，夜燭见飞蛾。","寶鴨藏脂粉，金屏綴綺羅。","裁衣卷紋素，织錦度鳴梭。","有使通西極，緘书寄北河。","年光只恐尽，征戰莫蹉跎。"]', '诗', 'shi', '', NULL, '春閨 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc42e3d-3286-4aec-b555-83ba0533e4f6', '奉和興慶池戲競渡應制', '奉和兴慶池戲競渡應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["夾道傳呼翊翠虬，天回日轉御芳洲。","青潭曉靄籠仙蹕，紅嶼晴花隔綵旒。","香溢金杯環廣坐，聲傳妓舸匝中流。","羣臣相慶嘉魚樂，共哂橫汾歌吹秋。"]', '["夾道傳呼翊翠虬，天回日轉御芳洲。","青潭晓靄籠仙蹕，紅嶼晴花隔綵旒。","香溢金杯环廣坐，声傳妓舸匝中流。","羣臣相慶嘉鱼乐，共哂橫汾歌吹秋。"]', '诗', 'shi', '', NULL, '奉和興慶池戲競渡應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec16ab9a-b715-4c53-91c9-35ac727bc649', '苑中遇雪應制', '苑中遇雪應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["千鍾聖酒御筵披，六出祥英亂繞枝。","即此神仙對瓊圃，何煩轍迹向瑤池。"]', '["千鍾聖酒御筵披，六出祥英亂繞枝。","即此神仙对瓊圃，何煩轍迹向瑤池。"]', '诗', 'shi', '', NULL, '苑中遇雪應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc7e5a6-52ee-4d5d-a195-9241bfdfd7ed', '上巳日祓禊渭濱應制', '上巳日祓禊渭濱應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["晴風麗日滿芳洲，柳色春筵祓錦流。","皆言侍蹕橫汾宴，暫似乘槎天漢遊。"]', '["晴风丽日满芳洲，柳色春筵祓錦流。","皆言侍蹕橫汾宴，暫似乘槎天漢游。"]', '诗', 'shi', '', NULL, '上巳日祓禊渭濱應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d51239-1f23-455b-bdbc-93f2d6112f4f', '夜宴安樂公主新宅應制', '夜宴安乐公主新宅應制', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["鳳樓開闔引明光，花酎連添醉益香。","欲知帝女薰天貴，金柯玉柱夜成行。"]', '["鳳楼开闔引明光，花酎連添醉益香。","欲知帝女薰天貴，金柯玉柱夜成行。"]', '诗', 'shi', '', NULL, '夜宴安樂公主新宅應制 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ed863d-583e-48d0-9b65-d8fc9c142109', '餞唐永昌', '餞唐永昌', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["金溪碧水玉潭沙，鳧舄翩翩弄日華。","鬬雞香陌行春倦，爲摘東園桃李花。"]', '["金溪碧水玉潭沙，鳧舄翩翩弄日华。","鬬雞香陌行春倦，爲摘东园桃李花。"]', '诗', 'shi', '', NULL, '餞唐永昌 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7eeddb-acc8-4780-a3bb-384d09656150', '侍宴桃花園', '侍宴桃花园', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["源水叢花無數開，丹跗紅萼間青梅。","從今結子三千歲，預喜仙遊復摘來。"]', '["源水叢花無數开，丹跗紅萼间青梅。","從今結子三千歲，預喜仙游复摘来。"]', '诗', 'shi', '', NULL, '侍宴桃花園 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c2a9eb-2e80-433b-8b23-60b6269dc0ee', '石淙', '石淙', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["碧淀紅涔崿嶂間，淙嵌洑岨洊成灣。","琪樹琁娟花未落，銀芝窋䆛露初還。","八風行殿開仙牓，七景飛輿下石關。","張蔦席雲平圃讌，焜煌金記蘊名山。"]', '["碧淀紅涔崿嶂间，淙嵌洑岨洊成灣。","琪樹琁娟花未落，銀芝窋䆛露初還。","八风行殿开仙牓，七景飞輿下石关。","張蔦席云平圃讌，焜煌金記蘊名山。"]', '诗', 'shi', '', NULL, '石淙 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcfb061b-4209-4925-9ef1-65722bb56781', '夏日遊德州贈高四', '夏日游德州贈高四', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["日觀鄰全趙，星臨俯舊吳。","鬲津開巨浸，稽阜鎮名都。","紫雲浮劍匣，青山孕寶符。","封疆恢霸道，問鼎競雄圖。","神光包四大，皇威震八區。","風煙通地軸，星象正天樞。","天樞限南北，地軸殊鄉國。","闢門通舜賓，比屋封堯德。","言謝垂鉤隱，來參負鼎職。","天子不見知，羣公詎相識。","未展從東駿，空戢圖南翼。","時命欲何言，撫膺長嘆息。","嘆息將如何，遊人意氣多。","白雪梁山曲，寒風易水歌。","泣魏傷吳起，思趙切廉頗。","淒斷韓王劍，生死翟公羅。","羅悲翟公意，劍負韓王氣。","驕餌去易論，忌途良可畏。","夙昔懷江海，平生混涇渭。","千載契風雲，一言忘賤貴。","去去訪林泉，空谷有遺賢。","言投爵里刺，來泛野人船。","締交君贈縞，投分我忘筌。","成風郢匠斲，流水伯牙弦。","牙弦忘道術，漳濱恣閑逸。","聊安張蔚廬，詎掃陳蕃室。","虛室狎招尋，敬愛混浮沈。","一諾黃金信，三復白珪心。","霜松貞雅節，月桂朗沖襟。","靈臺萬頃濬，學府九流深。","談玄明毀璧，拾紫陋籝金。","鷺濤開碧海，鳳彩綴詞林。","林虛星華映，水澈霞光淨。","霞水兩分紅，川源四望通。","霧卷天山靜，煙銷太史空。","鳥聲流向薄，蝶影亂芳叢。","柳陰低槧水，荷氣上薰風。","風月芳菲節，物華紛可悅。","將歡促席賞，遽爾又歸別。","積水帶吳門，通波連禹穴。","贈言雖欲盡，機心庶應絕。","潘岳本自閑，梁鴻不因熱。","一瓢欣狎道，三月聊棲拙。","棲拙隱金華，狎道訪仙查。","放曠愚公谷，消散野人家。","一頃南山豆，五色東陵瓜。","野衣裁薜葉，山酒酌藤花。","白雲離望遠，青谿隱路賒。","儻憶幽巖桂，猶冀折疎麻。"]', '["日观鄰全趙，星臨俯旧吳。","鬲津开巨浸，稽阜鎮名都。","紫云浮劍匣，青山孕寶符。","封疆恢霸道，问鼎競雄圖。","神光包四大，皇威震八區。","风煙通地軸，星象正天樞。","天樞限南北，地軸殊乡国。","闢门通舜賓，比屋封堯德。","言謝垂鉤隐，来參負鼎職。","天子不见知，羣公詎相識。","未展從东駿，空戢圖南翼。","时命欲何言，撫膺长嘆息。","嘆息將如何，游人意氣多。","白雪梁山曲，寒风易水歌。","泣魏傷吳起，思趙切廉頗。","淒斷韓王劍，生死翟公羅。","羅悲翟公意，劍負韓王氣。","驕餌去易論，忌途良可畏。","夙昔懷江海，平生混涇渭。","千載契风云，一言忘賤貴。","去去訪林泉，空谷有遺賢。","言投爵里刺，来泛野人船。","締交君贈縞，投分我忘筌。","成风郢匠斲，流水伯牙弦。","牙弦忘道術，漳濱恣闲逸。","聊安張蔚廬，詎掃陳蕃室。","虛室狎招尋，敬愛混浮沈。","一諾黄金信，三复白珪心。","霜松貞雅節，月桂朗沖襟。","靈台万頃濬，学府九流深。","談玄明毀璧，拾紫陋籝金。","鷺濤开碧海，鳳彩綴词林。","林虛星华映，水澈霞光淨。","霞水兩分紅，川源四望通。","霧卷天山静，煙銷太史空。","鸟声流向薄，蝶影亂芳叢。","柳陰低槧水，荷氣上薰风。","风月芳菲節，物华紛可悅。","將歡促席賞，遽爾又归別。","積水带吳门，通波連禹穴。","贈言雖欲尽，機心庶應絕。","潘岳本自闲，梁鴻不因熱。","一瓢欣狎道，三月聊棲拙。","棲拙隐金华，狎道訪仙查。","放曠愚公谷，消散野人家。","一頃南山豆，五色东陵瓜。","野衣裁薜葉，山酒酌藤花。","白云離望远，青谿隐路賒。","儻憶幽巖桂，猶冀折疎麻。"]', '诗', 'shi', '', NULL, '夏日遊德州贈高四 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55784a0-189c-4dc1-b2b2-a38c7dfa3368', '在江南贈宋五之問', '在江南贈宋五之问', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["井絡雙源濬，潯陽九派長。","淪波通地穴，輸委下歸塘。","別島籠朝蜃，連洲擁夕漲。","韞珠澄積潤，讓璧動浮光。","浮光凝折水，積潤疎圓沚。","玉輪涵地開，劍閣連星起。","風煙標迥秀，英靈信多美。","懷德踐遺芳，端操慙謀己。","謀己謬觀光，牽迹強悽惶。","揆拙迷三省，勞生昧兩忘。","彈隨空被笑，獻楚自多傷。","一朝殊默語，千里易炎涼。","炎涼幾遷貿，川陸疲臻湊。","積水架吳濤，連山橫楚岫。","風月雖殊昔，星河猶是舊。","姑蘇望南浦，邯鄲通北走。","北走平生親，南浦別離津。","瀟湘一超忽，洞庭多苦辛。","秋江無綠芷，寒汀有白蘋。","采之將何遺，故人漳水濱。","漳濱已遼遠，江潭未旋返。","爲聽短歌行，當想長洲苑。","露金熏菊岸，風佩搖蘭坂。","蟬鳴稻葉秋，雁起蘆花晚。","晚秋雲日明，亭臯風霧清。","獨負平生氣，重牽搖落情。","占星非聚德，夢月詎懸名。","寂寥傷楚奏，淒斷泣秦聲。","秦聲懷舊里，楚奏悲無已。","郢路少知音，叢臺富奇士。","溫輝凌愛日，壯氣驚寒水。","一顧重風雲，三冬足文史。","文史盛紛綸，京洛多風塵。","猶輕五車富，未重一囊貧。","李仙非易託，蘇鬼尚難因。","不惜勞歌盡，誰爲聽陽春。"]', '["井絡雙源濬，潯陽九派长。","淪波通地穴，輸委下归塘。","別島籠朝蜃，連洲擁夕漲。","韞珠澄積潤，讓璧动浮光。","浮光凝折水，積潤疎圓沚。","玉輪涵地开，劍閣連星起。","风煙標迥秀，英靈信多美。","懷德踐遺芳，端操慙謀己。","謀己謬观光，牽迹強悽惶。","揆拙迷三省，勞生昧兩忘。","彈隨空被笑，獻楚自多傷。","一朝殊默語，千里易炎涼。","炎涼幾遷貿，川陸疲臻湊。","積水架吳濤，連山橫楚岫。","风月雖殊昔，星河猶是旧。","姑蘇望南浦，邯鄲通北走。","北走平生親，南浦別離津。","瀟湘一超忽，洞庭多苦辛。","秋江無綠芷，寒汀有白蘋。","采之將何遺，故人漳水濱。","漳濱已遼远，江潭未旋返。","爲听短歌行，當想长洲苑。","露金熏菊岸，风佩搖蘭坂。","蟬鳴稻葉秋，雁起蘆花晚。","晚秋云日明，亭臯风霧清。","独負平生氣，重牽搖落情。","占星非聚德，梦月詎懸名。","寂寥傷楚奏，淒斷泣秦声。","秦声懷旧里，楚奏悲無已。","郢路少知音，叢台富奇士。","溫輝凌愛日，壯氣驚寒水。","一顧重风云，三冬足文史。","文史盛紛綸，京洛多风塵。","猶轻五车富，未重一囊貧。","李仙非易託，蘇鬼尚难因。","不惜勞歌尽，誰爲听陽春。"]', '诗', 'shi', '', NULL, '在江南贈宋五之問 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62834bab-7430-41b0-a6b9-1070182b62d6', '晚憩田家', '晚憩田家', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["轉蓬勞遠役，披薜下田家。","山形類九折，水勢急三巴。","懸梁接斷岸，澀路擁崩查。","霧巖淪曉魄，風漵漲寒沙。","心迹一朝舛，關山萬里賒。","龍章徒表越，閩俗本殊華。","旅行悲泛梗，離贈折疎麻。","唯有寒潭菊，獨似故園花。"]', '["轉蓬勞远役，披薜下田家。","山形類九折，水勢急三巴。","懸梁接斷岸，澀路擁崩查。","霧巖淪晓魄，风漵漲寒沙。","心迹一朝舛，关山万里賒。","龙章徒表越，閩俗本殊华。","旅行悲泛梗，離贈折疎麻。","唯有寒潭菊，独似故园花。"]', '诗', 'shi', '', NULL, '晚憩田家 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff47213a-4434-48cf-bce5-69b4fd8bd179', '出石門', '出石门', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["層巖遠接天，絕嶺上棲烟。","松低輕蓋偃，藤細弱絲懸。","石明如挂鏡，苔分似列錢。"]', '["層巖远接天，絕嶺上棲烟。","松低轻蓋偃，藤細弱絲懸。","石明如挂镜，苔分似列錢。"]', '诗', 'shi', '', NULL, '出石門 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841d4cbd-d032-459e-b133-0c86e92682e1', '至分陝', '至分陝', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["陝西開勝壤，召南分沃疇。","列樹巢維鵲，平渚下雎鳩。","憩棠疑勿剪，曳葛似攀樛。","至今王化美，非獨在隆周。"]', '["陝西开勝壤，召南分沃疇。","列樹巢維鵲，平渚下雎鳩。","憩棠疑勿剪，曳葛似攀樛。","至今王化美，非独在隆周。"]', '诗', 'shi', '', NULL, '至分陝 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6611b2-fd72-4f3f-bc20-48f71b7995e5', '寓居洛濱對雪憶謝二', '寓居洛濱对雪憶謝二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["旅思眇難裁，衝飆恨易哀。","曠望洛川晚，飄颻瑞雪來。","積彩明書幌，流韻繞琴臺。","色奪迎仙羽，花避犯霜梅。","謝庭賞方逸，袁扉掩未開。","高人儻有訪，興盡詎須回。"]', '["旅思眇难裁，衝飆恨易哀。","曠望洛川晚，飄颻瑞雪来。","積彩明书幌，流韻繞琴台。","色奪迎仙羽，花避犯霜梅。","謝庭賞方逸，袁扉掩未开。","高人儻有訪，兴尽詎須回。"]', '诗', 'shi', '', NULL, '寓居洛濱對雪憶謝二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3e827d-061c-425a-8f3f-dba2fbb7af96', '北眺舂陵', '北眺舂陵', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["攬轡疲宵邁，驅馬倦晨興。","既出封泥谷，還過避雨陵。","山行明照上，谿宿密雲蒸。","登高徒欲賦，詞殫獨撫膺。"]', '["攬轡疲宵邁，驱马倦晨兴。","既出封泥谷，還過避雨陵。","山行明照上，谿宿密云蒸。","登高徒欲賦，词殫独撫膺。"]', '诗', 'shi', '', NULL, '北眺舂陵 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b627e8f-713c-479e-83ad-06dab7c3b064', '夏日遊目聊作', '夏日游目聊作', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["暫屏囂塵累，言尋物外情。","致逸心逾默，神幽體自輕。","浦夏荷香滿，田秋麥氣清。","詎假滄浪上，將濯楚臣纓。"]', '["暫屏囂塵累，言尋物外情。","致逸心逾默，神幽體自轻。","浦夏荷香满，田秋麦氣清。","詎假滄浪上，將濯楚臣纓。"]', '诗', 'shi', '', NULL, '夏日遊目聊作 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a0622c-0b94-4a23-9b6b-6ebe9e1bb573', '同崔駙馬曉初登樓思京', '同崔駙马晓初登楼思京', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["麗譙通四望，繁憂起萬端。","綺疏低晚魄，鏤檻肅初寒。","白雲鄉思遠，黃圖歸路難。","唯餘西向笑，暫似當長安。"]', '["丽譙通四望，繁憂起万端。","綺疏低晚魄，鏤檻肅初寒。","白云乡思远，黄圖归路难。","唯餘西向笑，暫似當长安。"]', '诗', 'shi', '', NULL, '同崔駙馬曉初登樓思京 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b62a42-8c52-4769-938d-158861184f1f', '月夜有懷簡諸同病', '月夜有懷簡諸同病', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["閑庭落景盡，疎簾夜月通。","山靈響似應，水淨望如空。","棲枝猶繞鵲，遵渚未來鴻。","可歎高樓婦，悲思杳難終。"]', '["闲庭落景尽，疎簾夜月通。","山靈响似應，水淨望如空。","棲枝猶繞鵲，遵渚未来鴻。","可歎高楼婦，悲思杳难終。"]', '诗', 'shi', '', NULL, '月夜有懷簡諸同病 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ab4c8c-c363-4e55-9ab5-9d1dcdde1789', '敘寄員半千', '敘寄員半千', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["薄宦三河道，自負十餘年。","不應驚若厲，秪爲直如弦。","坐歷山川險，吁嗟陵谷遷。","長吟空抱膝，短翮詎沖天。","魂歸滄海上，望斷白雲前。","釣名勞拾紫，隱迹自談玄。","不學多能聖，徒思鴻寶仙。","斯志良難已，此道豈徒然。","嗟爲刀筆吏，恥從繩墨牽。","岐路情雖狎，人倫地本偏。","長揖謝時事，獨往訪林泉。","寄言二三子，生死不來旋。"]', '["薄宦三河道，自負十餘年。","不應驚若厲，秪爲直如弦。","坐歷山川險，吁嗟陵谷遷。","长吟空抱膝，短翮詎沖天。","魂归滄海上，望斷白云前。","釣名勞拾紫，隐迹自談玄。","不学多能聖，徒思鴻寶仙。","斯志良难已，此道豈徒然。","嗟爲刀笔吏，恥從繩墨牽。","岐路情雖狎，人倫地本偏。","长揖謝时事，独往訪林泉。","寄言二三子，生死不来旋。"]', '诗', 'shi', '', NULL, '敘寄員半千 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2517adb9-f684-4ffb-a2f4-5fc261f7fe4c', '詠懷古意上裴侍郎', '詠懷古意上裴侍郎', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["三十二餘罷，鬢是潘安仁。","四十九仍入，年非朱買臣。","縱橫愁繫越，坎壈倦遊秦。","出籠窮短翮，委轍涸枯鱗。","窮經不霑用，彈鋏欲誰申。","天子未驅策，歲月幾沈淪。","輕生長慷慨，效死獨殷勤。","徒歌易水客，空老渭川人。","一得視邊塞，萬里何苦辛。","劍匣胡霜影，弓開漢月輪。","金刀動秋色，鐵騎想風塵。","爲國堅誠款，捐軀忘賤貧。","勒功思比憲，決略暗欺陳。","若不犯霜雪，虛擲玉京春。"]', '["三十二餘罷，鬢是潘安仁。","四十九仍入，年非朱買臣。","縱橫愁繫越，坎壈倦游秦。","出籠窮短翮，委轍涸枯鱗。","窮經不霑用，彈鋏欲誰申。","天子未驱策，歲月幾沈淪。","轻生长慷慨，效死独殷勤。","徒歌易水客，空老渭川人。","一得視邊塞，万里何苦辛。","劍匣胡霜影，弓开漢月輪。","金刀动秋色，鐵騎想风塵。","爲国堅誠款，捐軀忘賤貧。","勒功思比憲，決略暗欺陳。","若不犯霜雪，虛擲玉京春。"]', '诗', 'shi', '', NULL, '詠懷古意上裴侍郎 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c03343-3f55-457d-9f4d-d554f9c689b6', '春夜韋明府宅宴得春字', '春夜韋明府宅宴得春字', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["酌桂陶芳夜，披薜嘯幽人。","雅琴馴魯雉，清歌落范塵。","宿雲低迥蓋，殘月上虛輪。","幸此承恩洽，聊當故鄉春。"]', '["酌桂陶芳夜，披薜嘯幽人。","雅琴馴魯雉，清歌落范塵。","宿云低迥蓋，殘月上虛輪。","幸此承恩洽，聊當故乡春。"]', '诗', 'shi', '', NULL, '春夜韋明府宅宴得春字 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476087fe-881e-47af-a337-e324da7f2e4c', '過張平子墓', '過張平子墓', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["西鄂該通理，南陽擅德音。","玉巵浮藻麗，銅渾積思深。","忽懷今日昔，非復昔時今。","日落豐碑暗，風來古木吟。","惟歎窮泉下，終鬱羨魚心。"]', '["西鄂該通理，南陽擅德音。","玉巵浮藻丽，銅渾積思深。","忽懷今日昔，非复昔时今。","日落豐碑暗，风来古木吟。","惟歎窮泉下，終鬱羨鱼心。"]', '诗', 'shi', '', NULL, '過張平子墓 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6537b9c-e947-4b5b-b906-372aa3e8b973', '從軍中行路難二首 一', '從軍中行路难二首 一', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["君不見封狐雄虺自成羣，馮深負固結妖氛。","玉璽分兵徵惡少，金壇受律動將軍。","將軍擁旄宣廟略，戰士橫行靜夷落。","長驅一息背銅梁，直指三巴登劍閣。","閣道岧嶤起戍樓，劍門遙裔俯靈丘。","邛關九折無平路，江水雙源有急流。","征役無期返，他鄉歲華晚。","杳杳丘陵出，蒼蒼林薄遠。","途危紫蓋峰，路澀青泥坂。","去去指哀牢，行行入不毛。","絕壁千里險，連山四望高。","中外分區宇，夷夏殊風土。","交趾枕南荒，昆彌臨北戶。","川原繞毒霧，溪谷多淫雨。","行潦四時流，崩查千歲古。","漂梗飛蓬不自安，捫藤引葛度危巒。","昔時聞道從軍樂，今日方知行路難。","滄江綠水東流駛，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻煙波。","三春邊地風光少，五月瀘中瘴癘多。","朝驅疲斥候，夕息倦樵歌。","向月彎繁弱，連星轉太阿。","重義輕生懷一顧，東伐西征凡幾度。","夜夜朝朝斑鬢新，年年歲歲戎衣故。","灞城隅，滇池水。","天雅望轉積，地際行無已。","徒覺炎涼節物非，不知關山千萬里。","棄置勿重陳，征行多苦辛。","且悅清笳楊柳曲，詎憶芳園桃李人。","絳節朱旗分白羽，丹心白刃酬明主。","但令一被君王知，誰憚三邊征戰苦。","行路難，幾千端。","無復歸雲憑短翰，空餘望日想長安。"]', '["君不见封狐雄虺自成羣，馮深負固結妖氛。","玉璽分兵徵惡少，金壇受律动將軍。","將軍擁旄宣廟略，戰士橫行静夷落。","长驱一息背銅梁，直指三巴登劍閣。","閣道岧嶤起戍楼，劍门遙裔俯靈丘。","邛关九折無平路，江水雙源有急流。","征役無期返，他乡歲华晚。","杳杳丘陵出，蒼蒼林薄远。","途危紫蓋峰，路澀青泥坂。","去去指哀牢，行行入不毛。","絕壁千里險，連山四望高。","中外分區宇，夷夏殊风土。","交趾枕南荒，昆彌臨北戶。","川原繞毒霧，溪谷多淫雨。","行潦四时流，崩查千歲古。","漂梗飞蓬不自安，捫藤引葛度危巒。","昔时闻道從軍乐，今日方知行路难。","滄江綠水东流駛，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻煙波。","三春邊地风光少，五月瀘中瘴癘多。","朝驱疲斥候，夕息倦樵歌。","向月彎繁弱，連星轉太阿。","重義轻生懷一顧，东伐西征凡幾度。","夜夜朝朝斑鬢新，年年歲歲戎衣故。","灞城隅，滇池水。","天雅望轉積，地際行無已。","徒覺炎涼節物非，不知关山千万里。","棄置勿重陳，征行多苦辛。","且悅清笳楊柳曲，詎憶芳园桃李人。","絳節朱旗分白羽，丹心白刃酬明主。","但令一被君王知，誰憚三邊征戰苦。","行路难，幾千端。","無复归云憑短翰，空餘望日想长安。"]', '诗', 'shi', '', NULL, '從軍中行路難二首 一 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a4dc5e-9d1c-4ed8-8357-605d76f92f34', '從軍中行路難二首 二', '從軍中行路难二首 二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["君不見玉關塵色暗邊庭，銅鞮雜虜寇長城。","天子按劍徵餘勇，將軍受脤事橫行。","七德龍韜開玉帳，千里鼉鼓壘金鉦。","陰山苦霧埋高壘，交河孤月照連營。","連營去去無窮極，擁斾遙遙過絕國。","陣雲朝結晦天山，寒沙夕漲迷疎勒。","龍鱗水上開魚貫，馬首山前振雕翼。","長驅萬里讋祈連，分麾三命武功宣。","百發烏號遙碎柳，七尺龍文迥照蓮。","春來秋去移灰琯，蘭閨柳市芳塵斷。","雁門迢遞尺書稀，鴛被相思雙帶緩。","行路難，行路難，誓令氛祲靜臯蘭。","但使封侯龍頟貴，詎隨中婦鳳樓寒。"]', '["君不见玉关塵色暗邊庭，銅鞮杂虜寇长城。","天子按劍徵餘勇，將軍受脤事橫行。","七德龙韜开玉帳，千里鼉鼓壘金鉦。","陰山苦霧埋高壘，交河孤月照連營。","連營去去無窮極，擁斾遙遙過絕国。","陣云朝結晦天山，寒沙夕漲迷疎勒。","龙鱗水上开鱼貫，马首山前振雕翼。","长驱万里讋祈連，分麾三命武功宣。","百發烏號遙碎柳，七尺龙文迥照蓮。","春来秋去移灰琯，蘭閨柳市芳塵斷。","雁门迢遞尺书稀，鴛被相思雙带緩。","行路难，行路难，誓令氛祲静臯蘭。","但使封侯龙頟貴，詎隨中婦鳳楼寒。"]', '诗', 'shi', '', NULL, '從軍中行路難二首 二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1073d277-650a-4736-a248-952252e4e342', '帝京篇', '帝京篇', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["山河千里國，城闕九重門。","不覩皇居壯，安知天子尊。","皇居帝里崤函谷，鶉野龍山侯甸服。","五緯連影集星躔，八水分流橫地軸。","秦塞重關一百二，漢家離宮三十六。","桂殿嶔岑對玉樓，椒房窈窕連金屋。","三條九陌麗城隈，萬戶千門平旦開。","複道斜通鳷鵲觀，交衢直指鳳皇臺。","劍履南宮入，簪纓北闕來。","聲名冠寰宇，文物象昭回。","鉤陳肅蘭戺，璧沼浮槐市。","銅羽應風回，金莖承露起。","校文天祿閣，習戰昆明水。","朱邸抗平臺，黃扉通戚里。","平臺戚里帶崇墉，炊金饌玉待鳴鐘。","小堂綺帳三千戶，大道青樓十二重。","寶蓋雕鞍金絡馬，蘭窗繡柱玉盤龍。","繡柱璇題粉壁映，鏘金鳴玉王侯盛。","王侯貴人多近臣，朝遊北里暮南鄰。","陸賈分金將讌喜，陳遵投轄正留賓。","趙李經過密，蕭朱交結親。","丹鳳朱城白日暮，青牛紺幰紅塵度。","俠客珠彈垂楊道，倡婦銀鉤采桑路。","倡家桃李自芳菲，京華遊俠盛輕肥。","延年女弟雙鳳入，羅敷使君千騎歸。","同心結縷帶，連理織成衣。","春朝桂尊尊百味，秋夜蘭燈燈九微。","翠幌珠簾不獨映，清歌寶瑟自相依。","且論三萬六千是，寧知四十九年非。","古來榮利若浮雲，人生倚伏信難分。","始見田竇相移奪，俄聞衞霍有功勳。","未厭金陵氣，先開石槨文。","朱門無復張公子，灞亭誰畏李將軍。","相顧百齡皆有待，居然萬化咸應改。","桂枝芳氣已銷亡，柏梁高宴今何在？","春去春來苦自馳，爭名爭利徒爾爲。","久留郎署終難遇，空掃相門誰見知。","當時一旦擅豪華，自言千載長驕奢。","倏忽摶風生羽翼，須臾失浪委泥沙。","黃雀徒巢桂，青門遂種瓜。","黃金銷鑠素絲變，一貴一賤交情見。","紅顏宿昔白頭新，脫粟布衣輕故人。","故人有湮淪，新知無意氣。","灰死韓安國，羅傷翟廷尉。","已矣哉，歸去來。","馬卿辭蜀多文藻，揚雄仕漢乏良媒。","三冬自矜誠足用，十年不調幾邅回。","汲黯薪逾積，孫弘閣未開。","誰惜長沙傅，獨負洛陽才。"]', '["山河千里国，城闕九重门。","不覩皇居壯，安知天子尊。","皇居帝里崤函谷，鶉野龙山侯甸服。","五緯連影集星躔，八水分流橫地軸。","秦塞重关一百二，漢家離宮三十六。","桂殿嶔岑对玉楼，椒房窈窕連金屋。","三條九陌丽城隈，万戶千门平旦开。","複道斜通鳷鵲观，交衢直指鳳皇台。","劍履南宮入，簪纓北闕来。","声名冠寰宇，文物象昭回。","鉤陳肅蘭戺，璧沼浮槐市。","銅羽應风回，金莖承露起。","校文天祿閣，習戰昆明水。","朱邸抗平台，黄扉通戚里。","平台戚里带崇墉，炊金饌玉待鳴鐘。","小堂綺帳三千戶，大道青楼十二重。","寶蓋雕鞍金絡马，蘭窗繡柱玉盤龙。","繡柱璇題粉壁映，鏘金鳴玉王侯盛。","王侯貴人多近臣，朝游北里暮南鄰。","陸賈分金將讌喜，陳遵投轄正留賓。","趙李經過密，蕭朱交結親。","丹鳳朱城白日暮，青牛紺幰紅塵度。","俠客珠彈垂楊道，倡婦銀鉤采桑路。","倡家桃李自芳菲，京华游俠盛轻肥。","延年女弟雙鳳入，羅敷使君千騎归。","同心結縷带，連理织成衣。","春朝桂尊尊百味，秋夜蘭灯灯九微。","翠幌珠簾不独映，清歌寶瑟自相依。","且論三万六千是，寧知四十九年非。","古来榮利若浮云，人生倚伏信难分。","始见田竇相移奪，俄闻衞霍有功勳。","未厭金陵氣，先开石槨文。","朱门無复張公子，灞亭誰畏李將軍。","相顧百齡皆有待，居然万化咸應改。","桂枝芳氣已銷亡，柏梁高宴今何在？","春去春来苦自驰，爭名爭利徒爾爲。","久留郎署終难遇，空掃相门誰见知。","當时一旦擅豪华，自言千載长驕奢。","倏忽摶风生羽翼，須臾失浪委泥沙。","黄雀徒巢桂，青门遂種瓜。","黄金銷鑠素絲变，一貴一賤交情见。","紅顏宿昔白头新，脫粟布衣轻故人。","故人有湮淪，新知無意氣。","灰死韓安国，羅傷翟廷尉。","已矣哉，归去来。","马卿辞蜀多文藻，揚雄仕漢乏良媒。","三冬自矜誠足用，十年不調幾邅回。","汲黯薪逾積，孫弘閣未开。","誰惜长沙傅，独負洛陽才。"]', '诗', 'shi', '', NULL, '帝京篇 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7a1d13-870a-40bf-8315-9ee29123659d', '疇昔篇', '疇昔篇', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["少年重英俠，弱歲賤衣冠。","既託寰中賞，方承膝下歡。","遨遊灞水曲，風月洛城端。","且知無玉饌，誰肯逐金丸。","金丸玉饌盛繁華，自言輕侮季倫家。","五霸爭馳千里馬，三條競騖七香車。","掩映飛軒乘落照，參差步障引朝霞。","池中舊水如懸鏡，屋裏新妝不讓花。","意氣風雲倏如昨，歲月春秋屢回薄。","上苑頻經柳絮飛，中園幾見梅花落。","當時門客今何在？疇昔交朋已疎索。","莫教憔悴損容儀，會得高秋雲霧廓。","淹留坐帝鄉，無事積炎涼。","一朝披短褐，六載奉長廊。","賦文慙昔馬，執戟歎前揚。","揮戈出武帳，荷筆入文昌。","文昌隱隱皇城裏，由來奕奕多才子。","潘陸詞鋒駱驛飛，張曹翰苑縱橫起。","卿相未曾識，王侯寧見擬。","垂釣甘成白首翁，負薪何處逢知己？","判將運命賦窮通，從來奇舛任西東。","不應永棄同芻狗，且復飄颻類轉蓬。","容鬢年年異，春華歲歲同。","榮觀未盡禮，徇主欲申功。","脂車秣馬辭鄉國，縈轡西南使邛僰。","玉壘銅梁不易攀，地角天涯眇難測。","鶯囀蟬吟有悲望，鴻來雁度無音息。","陽關積霧萬里昏，劍閣連山千種色。","蜀路何悠悠，岷峯阻且修。","回腸隨九折，迸淚連雙流。","寒光千里暮，露氣二江秋。","長途看束馬，平水且沈牛。","華陽舊地標神制，石鏡蛾眉真秀麗。","諸葛才雄已號龍，公孫躍馬輕稱帝。","五丁卓犖多奇力，四士英靈富文藝。","雲氣橫開八陣形，橋形遙分七星勢。","川平煙霧開，遊戲錦城隈。","墉高龜望出，水淨雁文回。","尋姝入酒肆，訪客上琴臺。","不識金貂重，偏惜玉山頹。","他鄉冉冉消年月，帝里沈沈限城闕。","不見猿聲助客啼，唯聞旅思將花發。","我家迢遞關山裏，關山迢遞不可越。","故園梅柳尚餘春，來時勿使芳菲歇。","解鞅欲言歸，執袂愴多違。","北梁俱握手，南浦共沾衣。","別情傷去蓋，離念惜徂輝。","知音何所托，木落雁南飛。","回來望平陸，春來酒應熟。","相將菌閣臥青溪，且用藤杯泛黃菊。","十年不調爲貧賤，百日屢遷隨倚伏。","祗爲須求負郭田，使我再干州縣祿。","百年鬱鬱少騰遷，萬里遙遙入鏡川。","涘江拂潮衝白日，淮海長波接遠天。","叢竹凝朝露，孤山起暝煙。","賴有邊城月，常伴客旌懸。","東南美箭稱吳會，名都隱軫三江外。","塗山執玉應昌期，曲水開襟重文會。","仙鏑流音鳴鶴嶺，寶劍分輝落蛟瀨。","未看白馬對蘆芻，且覺浮雲似車蓋。","江南節序多，文酒屢經過。","共踏春江曲，俱唱采菱歌。","舟移疑入鏡，棹舉若乘波。","風光無限極，歸檝礙池荷。","眺聽烟霞正流眄，即從王事歸艫轉。","芝田花月屢裴回，金谷佳期重遊衍。","登高北望嗤梁叟，憑軾西征想潘掾。","峯開華岳聳疑蓮，水激龍門急如箭。","人事謝光陰，俄遭霜露侵。","偷存七尺影，分沒九泉深。","窮途行泣玉，憤路未藏金。","茹荼空有歎，懷橘獨傷心。","年來歲去成銷鑠，懷抱心期漸寥落。","挂冠裂冕已辭榮，南畝東臯事耕鑿。","賓階客院常疏散，蓬徑柴扉終寂寞。","自有林泉堪隱棲，何必山中事丘壑。","我住青門外，家臨素滻濱。","遙瞻丹鳳闕，斜望黑龍津。","荒衢通獵騎，窮巷抵樵輪。","時有桃源客，來訪竹林人。","昨夜琴聲奏悲調，旭旦含顰不成笑。","果乘驄馬發囂書，復道郎官稟綸誥。","冶長非罪曾縲絏，長孺然灰也經溺。","高門有閱不圖封，峻筆無聞歛敷妙。","適離京兆謗，還從御史彈。","炎威資夏景，平曲況秋翰。","畫地終難入，書空自不安。","吹毛未可待，搖尾且求餐。","丈夫坎壈多愁疾，契闊迍邅盡今日。","慎罰寧憑兩造辭，嚴科直挂三章律。","鄒衍銜悲繫燕獄，李斯抱怨拘秦桎。","不應白髮頓成絲，直爲黃沙暗如漆。","紫禁終難呌，朱門不易排。","驚魂聞葉落，危魄逐輪埋。","霜威遙有厲，雪[枉]遂無階。","含冤欲誰道，飲氣獨居懷。","忽聞驛使發關東，傳道天波萬里通。","涸鱗去轍還遊海，幽禽釋網便翔空。","舜澤堯曦方有極，讒言巧佞儻無窮。","誰能跼迹依三輔，會就商山訪四翁。"]', '["少年重英俠，弱歲賤衣冠。","既託寰中賞，方承膝下歡。","遨游灞水曲，风月洛城端。","且知無玉饌，誰肯逐金丸。","金丸玉饌盛繁华，自言轻侮季倫家。","五霸爭驰千里马，三條競騖七香车。","掩映飞軒乘落照，參差步障引朝霞。","池中旧水如懸镜，屋裏新妝不讓花。","意氣风云倏如昨，歲月春秋屢回薄。","上苑頻經柳絮飞，中园幾见梅花落。","當时门客今何在？疇昔交朋已疎索。","莫教憔悴損容儀，會得高秋云霧廓。","淹留坐帝乡，無事積炎涼。","一朝披短褐，六載奉长廊。","賦文慙昔马，執戟歎前揚。","揮戈出武帳，荷笔入文昌。","文昌隐隐皇城裏，由来奕奕多才子。","潘陸词鋒駱驛飞，張曹翰苑縱橫起。","卿相未曾識，王侯寧见擬。","垂釣甘成白首翁，負薪何处逢知己？","判將運命賦窮通，從来奇舛任西东。","不應永棄同芻狗，且复飄颻類轉蓬。","容鬢年年異，春华歲歲同。","榮观未尽禮，徇主欲申功。","脂车秣马辞乡国，縈轡西南使邛僰。","玉壘銅梁不易攀，地角天涯眇难測。","鶯囀蟬吟有悲望，鴻来雁度無音息。","陽关積霧万里昏，劍閣連山千種色。","蜀路何悠悠，岷峯阻且修。","回腸隨九折，迸泪連雙流。","寒光千里暮，露氣二江秋。","长途看束马，平水且沈牛。","华陽旧地標神制，石镜蛾眉真秀丽。","諸葛才雄已號龙，公孫躍马轻稱帝。","五丁卓犖多奇力，四士英靈富文藝。","云氣橫开八陣形，橋形遙分七星勢。","川平煙霧开，游戲錦城隈。","墉高龟望出，水淨雁文回。","尋姝入酒肆，訪客上琴台。","不識金貂重，偏惜玉山頹。","他乡冉冉消年月，帝里沈沈限城闕。","不见猿声助客啼，唯闻旅思將花發。","我家迢遞关山裏，关山迢遞不可越。","故园梅柳尚餘春，来时勿使芳菲歇。","解鞅欲言归，執袂愴多違。","北梁俱握手，南浦共沾衣。","別情傷去蓋，離念惜徂輝。","知音何所托，木落雁南飞。","回来望平陸，春来酒應熟。","相將菌閣臥青溪，且用藤杯泛黄菊。","十年不調爲貧賤，百日屢遷隨倚伏。","祗爲須求負郭田，使我再干州縣祿。","百年鬱鬱少腾遷，万里遙遙入镜川。","涘江拂潮衝白日，淮海长波接远天。","叢竹凝朝露，孤山起暝煙。","賴有邊城月，常伴客旌懸。","东南美箭稱吳會，名都隐軫三江外。","塗山執玉應昌期，曲水开襟重文會。","仙鏑流音鳴鹤嶺，寶劍分輝落蛟瀨。","未看白马对蘆芻，且覺浮云似车蓋。","江南節序多，文酒屢經過。","共踏春江曲，俱唱采菱歌。","舟移疑入镜，棹舉若乘波。","风光無限極，归檝礙池荷。","眺听烟霞正流眄，即從王事归艫轉。","芝田花月屢裴回，金谷佳期重游衍。","登高北望嗤梁叟，憑軾西征想潘掾。","峯开华岳聳疑蓮，水激龙门急如箭。","人事謝光陰，俄遭霜露侵。","偷存七尺影，分沒九泉深。","窮途行泣玉，憤路未藏金。","茹荼空有歎，懷橘独傷心。","年来歲去成銷鑠，懷抱心期漸寥落。","挂冠裂冕已辞榮，南畝东臯事耕鑿。","賓階客院常疏散，蓬徑柴扉終寂寞。","自有林泉堪隐棲，何必山中事丘壑。","我住青门外，家臨素滻濱。","遙瞻丹鳳闕，斜望黑龙津。","荒衢通獵騎，窮巷抵樵輪。","时有桃源客，来訪竹林人。","昨夜琴声奏悲調，旭旦含顰不成笑。","果乘驄马發囂书，复道郎官稟綸誥。","冶长非罪曾縲絏，长孺然灰也經溺。","高门有閱不圖封，峻笔無闻歛敷妙。","適離京兆謗，還從御史彈。","炎威資夏景，平曲況秋翰。","畫地終难入，书空自不安。","吹毛未可待，搖尾且求餐。","丈夫坎壈多愁疾，契闊迍邅尽今日。","慎罰寧憑兩造辞，嚴科直挂三章律。","鄒衍銜悲繫燕獄，李斯抱怨拘秦桎。","不應白髮頓成絲，直爲黄沙暗如漆。","紫禁終难呌，朱门不易排。","驚魂闻葉落，危魄逐輪埋。","霜威遙有厲，雪[枉]遂無階。","含冤欲誰道，饮氣独居懷。","忽闻驛使發关东，傳道天波万里通。","涸鱗去轍還游海，幽禽釋網便翔空。","舜澤堯曦方有極，讒言巧佞儻無窮。","誰能跼迹依三輔，會就商山訪四翁。"]', '诗', 'shi', '', NULL, '疇昔篇 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37dcb266-35d0-4cb3-9b17-89e33e8b78e7', '豔情代郭氏荅盧照鄰', '豔情代郭氏荅盧照鄰', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["迢迢芊路望芝田，眇眇函關恨蜀川。","歸雲已落涪江外，還雁應過洛水瀍。","洛水傍連帝城側，帝宅層甍垂鳳翼。","銅駝路上柳千條，金谷園中花幾色。","柳葉園花處處新，洛陽桃李應芳春。","妾向雙流窺石鏡，君住三川守玉人。","此時離別那堪道，此日空牀對芳沼。","芳沼徒遊比目魚，幽徑還生拔心艸。","流風回雪儻便娟，驥子魚文實可憐。","擲果河陽君有分，貨酒成都妾亦然。","莫言貧賤無人重，莫言富貴應須種。","綠珠猶得石崇憐，飛燕曾經漢皇寵。","良人何處醉縱橫？直如循默守空名。","倒提新縑成慊慊，翻將故劍作平平。","離前吉夢成蘭兆，別後啼痕上竹生。","別日分明相約束，已取宜家成誡勖。","當時擬弄掌中珠，豈謂先摧庭際玉。","悲鳴五里無人問，腸斷三聲誰爲續。","思君欲上望夫臺，端居懶聽將雛曲。","沈沈落日向山低，檐前歸燕竝頭栖。","抱膝當窗看夕兔，側耳空房聽曉雞。","舞蝶臨階秪自舞，啼鳥逢人亦助啼。","獨坐傷孤枕，春來悲更甚。","峨眉山上月如眉，濯錦江中霞似錦。","錦字回文欲贈君，劍壁層峰自糾紛。","平江淼淼分清浦，長路悠悠間白雲。","也知京洛多佳麗，也知山岫遙虧蔽。","無那短封即疎索，不在長情守期契。","傳聞織女對牽牛，相望重河隔淺流。","誰分迢迢經兩歲，誰能脈脈待三秋。","情知唾井終無理，情知覆水也難收。","不復下山能借問，更向盧家字莫愁。"]', '["迢迢芊路望芝田，眇眇函关恨蜀川。","归云已落涪江外，還雁應過洛水瀍。","洛水傍連帝城側，帝宅層甍垂鳳翼。","銅駝路上柳千條，金谷园中花幾色。","柳葉园花处处新，洛陽桃李應芳春。","妾向雙流窺石镜，君住三川守玉人。","此时離別那堪道，此日空牀对芳沼。","芳沼徒游比目鱼，幽徑還生拔心艸。","流风回雪儻便娟，驥子鱼文實可怜。","擲果河陽君有分，貨酒成都妾亦然。","莫言貧賤無人重，莫言富貴應須種。","綠珠猶得石崇怜，飞燕曾經漢皇寵。","良人何处醉縱橫？直如循默守空名。","倒提新縑成慊慊，翻將故劍作平平。","離前吉梦成蘭兆，別後啼痕上竹生。","別日分明相約束，已取宜家成誡勖。","當时擬弄掌中珠，豈謂先摧庭際玉。","悲鳴五里無人问，腸斷三声誰爲續。","思君欲上望夫台，端居懶听將雛曲。","沈沈落日向山低，檐前归燕竝头栖。","抱膝當窗看夕兔，側耳空房听晓雞。","舞蝶臨階秪自舞，啼鸟逢人亦助啼。","独坐傷孤枕，春来悲更甚。","峨眉山上月如眉，濯錦江中霞似錦。","錦字回文欲贈君，劍壁層峰自糾紛。","平江淼淼分清浦，长路悠悠间白云。","也知京洛多佳丽，也知山岫遙虧蔽。","無那短封即疎索，不在长情守期契。","傳闻织女对牽牛，相望重河隔淺流。","誰分迢迢經兩歲，誰能脈脈待三秋。","情知唾井終無理，情知覆水也难收。","不复下山能借问，更向盧家字莫愁。"]', '诗', 'shi', '', NULL, '豔情代郭氏荅盧照鄰 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2aedb6a-3ea2-455f-94b5-0347dd126a21', '代女道士王靈妃贈道士李榮', '代女道士王靈妃贈道士李榮', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["玄都五府風塵絕，碧海三山波浪深。","桃實千年非易待，桑田一變已難尋。","別有仙居對三市，金闕銀宮相向起。","臺前鏡影伴仙娥，樓上簫聲隨鳳史。","鳳樓迢遞絕塵埃，鶯時物色正裴回。","靈芝紫檢參差長，仙桂丹花重疊開。","雙童綽約時遊陟，三鳥聯翩報消息。","盡言真侶出遨遊，傳道風光無限極。","輕花委砌惹裾香，殘月窺窗覘幌色。","箇時無數倂妖妍，箇裏無窮總可憐。","別有衆中稱黜帝，天上人間少流例。","洛濱仙駕啓遙源，淮浦靈津符遠筮。","自言少小慕幽玄，只言容易得神仙。","珮中邀勒經時序，簫裏尋思復幾年。","尋思許事真情變，二人容華識少選。","漫道燒丹止七飛，空傳化石曾三轉。","寄語天上弄機人，寄語河邊值查客。","乍可悤悤共百年，誰使遙遙期七夕。","想知人意自相尋，果得深心共一心。","一心一意無窮已，投漆投膠非足擬。","只將羞澀當風流，持此相憐保終始。","相憐相念倍相親，一生一代一雙人。","不把丹心比玄石，惟將濁水況清塵。","只言柱下留期信，好欲將心學松蕣。","不能京兆畫峨眉，翻向成都騁騶引。","青牛紫氣度靈關，尺素赩鱗去不還。","連苔上砌無窮綠，修竹臨壇幾處斑。","此時空牀難獨守，此日別離那可久。","梅花如雪柳如絲，年去年來不自持。","初言別在寒偏在，何悟春來春更思。","春時物色無端緒，雙枕孤眠誰分許。","分念嬌鶯一種啼，生憎燕子千般語。","朝雲旭日照青樓，遲暉麗色滿皇州。","落花泛泛浮靈沼，垂柳長長拂御溝。","御溝大道多奇賞，俠客妖容遞來往。","寶騎連花鐵作錢，香輪騖水珠爲網。","香輪寶騎競繁華，可憐今夜宿倡家。","鸚鵡杯中浮竹葉，鳳凰琴裏落梅花。","許輩多情偏送款，爲問春花幾時滿。","千回鳥信說衆諸，百過鶯啼說長短。","長短衆諸判不尋，千回百過浪關心。","何曾舉意西鄰玉，未肯留情南陌金。","南陌西鄰咸自保，還轡歸期須及早。","爲想三春狹斜路，莫辭九折邛關道。","假令白里似長安，須使青牛學劍端。","蘋風入馭來應易，竹杖成龍去不難。","龍飆去去無消息，鸞鏡朝朝減容色。","君心不記下山人，妾欲空期上林翼。","上林三月鴻欲稀，華表千年鶴未歸。","不分淹留桑路待，秪應直取桂輪飛。"]', '["玄都五府风塵絕，碧海三山波浪深。","桃實千年非易待，桑田一变已难尋。","別有仙居对三市，金闕銀宮相向起。","台前镜影伴仙娥，楼上簫声隨鳳史。","鳳楼迢遞絕塵埃，鶯时物色正裴回。","靈芝紫檢參差长，仙桂丹花重叠开。","雙童綽約时游陟，三鸟聯翩報消息。","尽言真侶出遨游，傳道风光無限極。","轻花委砌惹裾香，殘月窺窗覘幌色。","箇时無數倂妖妍，箇裏無窮總可怜。","別有衆中稱黜帝，天上人间少流例。","洛濱仙駕啓遙源，淮浦靈津符远筮。","自言少小慕幽玄，只言容易得神仙。","珮中邀勒經时序，簫裏尋思复幾年。","尋思許事真情变，二人容华識少選。","漫道燒丹止七飞，空傳化石曾三轉。","寄語天上弄機人，寄語河邊值查客。","乍可悤悤共百年，誰使遙遙期七夕。","想知人意自相尋，果得深心共一心。","一心一意無窮已，投漆投膠非足擬。","只將羞澀當风流，持此相怜保終始。","相怜相念倍相親，一生一代一雙人。","不把丹心比玄石，惟將濁水況清塵。","只言柱下留期信，好欲將心学松蕣。","不能京兆畫峨眉，翻向成都騁騶引。","青牛紫氣度靈关，尺素赩鱗去不還。","連苔上砌無窮綠，修竹臨壇幾处斑。","此时空牀难独守，此日別離那可久。","梅花如雪柳如絲，年去年来不自持。","初言別在寒偏在，何悟春来春更思。","春时物色無端緒，雙枕孤眠誰分許。","分念嬌鶯一種啼，生憎燕子千般語。","朝云旭日照青楼，遲暉丽色满皇州。","落花泛泛浮靈沼，垂柳长长拂御溝。","御溝大道多奇賞，俠客妖容遞来往。","寶騎連花鐵作錢，香輪騖水珠爲網。","香輪寶騎競繁华，可怜今夜宿倡家。","鸚鵡杯中浮竹葉，鳳凰琴裏落梅花。","許輩多情偏送款，爲问春花幾时满。","千回鸟信说衆諸，百過鶯啼说长短。","长短衆諸判不尋，千回百過浪关心。","何曾舉意西鄰玉，未肯留情南陌金。","南陌西鄰咸自保，還轡归期須及早。","爲想三春狹斜路，莫辞九折邛关道。","假令白里似长安，須使青牛学劍端。","蘋风入馭来應易，竹杖成龙去不难。","龙飆去去無消息，鸾镜朝朝減容色。","君心不記下山人，妾欲空期上林翼。","上林三月鴻欲稀，华表千年鹤未归。","不分淹留桑路待，秪應直取桂輪飞。"]', '诗', 'shi', '', NULL, '代女道士王靈妃贈道士李榮 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8469e6ef-1e50-41c1-869c-be8ca42efc7e', '從軍行', '從軍行', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["平生一顧重，意氣溢三軍。","埜日分戈影，天星合劍文。","弓弦抱漢月，馬足踐胡塵。","不求生入塞，唯當死報君。"]', '["平生一顧重，意氣溢三軍。","埜日分戈影，天星合劍文。","弓弦抱漢月，马足踐胡塵。","不求生入塞，唯當死報君。"]', '诗', 'shi', '', NULL, '從軍行 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d8a8be-11d7-4b13-8e09-6e923f6486e1', '王昭君', '王昭君', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["歛容辭豹尾，緘恨度龍鱗。","金鈿明漢月，玉筯染胡塵。","古鏡菱花暗，愁眉柳葉顰。","唯有清笳曲，時聞芳樹春。"]', '["歛容辞豹尾，緘恨度龙鱗。","金鈿明漢月，玉筯染胡塵。","古镜菱花暗，愁眉柳葉顰。","唯有清笳曲，时闻芳樹春。"]', '诗', 'shi', '', NULL, '王昭君 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227f5573-870b-4e59-88c5-3ee310ba87f6', '於紫雲觀贈道士', '於紫云观贈道士', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["碧落澄秋景，玄門啓曙關。","人疑列禦至，客似令威還。","羽蓋徒欣仰，雲車未可攀。","衹應傾玉醴，時許寄頹顏。"]', '["碧落澄秋景，玄门啓曙关。","人疑列禦至，客似令威還。","羽蓋徒欣仰，云车未可攀。","衹應傾玉醴，时許寄頹顏。"]', '诗', 'shi', '', NULL, '於紫雲觀贈道士 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48804762-1db7-43cb-b548-7fd9eb410d83', '渡瓜步江', '渡瓜步江', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["捧檄辭幽徑，鳴榔下貴洲。","驚濤疑躍馬，積氣似連牛。","月迥寒沙淨，風急夜江秋。","不學浮雲影，他鄉空滯留。"]', '["捧檄辞幽徑，鳴榔下貴洲。","驚濤疑躍马，積氣似連牛。","月迥寒沙淨，风急夜江秋。","不学浮云影，他乡空滯留。"]', '诗', 'shi', '', NULL, '渡瓜步江 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5996e4b6-e6be-400a-bff8-46efce32bac2', '途中有懷', '途中有懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["睠然懷楚奏，悵矣背秦關。","涸鱗驚照轍，墜羽怯虛彎。","素服三川化，烏裘十上還。","莫言無皓齒，時俗薄朱顏。"]', '["睠然懷楚奏，悵矣背秦关。","涸鱗驚照轍，墜羽怯虛彎。","素服三川化，烏裘十上還。","莫言無皓齒，时俗薄朱顏。"]', '诗', 'shi', '', NULL, '途中有懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd24380-2a77-4f91-8821-a66aaa76655a', '至分水戍', '至分水戍', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["行役忽離憂，復此愴分流。","濺石回湍咽，縈叢曲澗幽。","陰巖常結晦，宿莽競含秋。","況乃霜晨早，寒風入戍樓。"]', '["行役忽離憂，复此愴分流。","濺石回湍咽，縈叢曲澗幽。","陰巖常結晦，宿莽競含秋。","況乃霜晨早，寒风入戍楼。"]', '诗', 'shi', '', NULL, '至分水戍 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1e35830-cf22-47cf-b558-966d41ac08b2', '望鄉夕泛', '望乡夕泛', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["歸懷剩不安，促榜犯風瀾。","落宿含樓近，浮月帶江寒。","喜逐行前至，憂從望裏寬。","今夜南枝鵲，應無繞樹難。"]', '["归懷剩不安，促榜犯风瀾。","落宿含楼近，浮月带江寒。","喜逐行前至，憂從望裏寬。","今夜南枝鵲，應無繞樹难。"]', '诗', 'shi', '', NULL, '望鄉夕泛 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f740d8-ad52-4299-83a2-5a13f315a7f9', '久客臨海有懷', '久客臨海有懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["天涯非日觀，地屺望星樓。","練光搖亂馬，劍氣上連牛。","草濕姑蘇夕，葉下洞庭秋。","欲知悽斷意，江上涉安流。"]', '["天涯非日观，地屺望星楼。","練光搖亂马，劍氣上連牛。","草濕姑蘇夕，葉下洞庭秋。","欲知悽斷意，江上涉安流。"]', '诗', 'shi', '', NULL, '久客臨海有懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67da108e-ffff-42a1-bfef-b8e1e6ee831e', '遊兗部逢孔君自衞來欣然相遇若舊', '游兗部逢孔君自衞来欣然相遇若旧', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["遊人自衞返，背客隔淮來。","傾蓋金蘭合，忘筌玉葉開。","繁花明日柳，疎蕊落風梅。","將期重交態，時慰不然灰。"]', '["游人自衞返，背客隔淮来。","傾蓋金蘭合，忘筌玉葉开。","繁花明日柳，疎蕊落风梅。","將期重交態，时慰不然灰。"]', '诗', 'shi', '', NULL, '遊兗部逢孔君自衞來欣然相遇若舊 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff5c4d33-2b95-4ada-9b69-b04cc22a2835', '西京守歲', '西京守歲', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["閑居寡言宴，獨坐慘風塵。","忽見嚴冬盡，方知列宿春。","夜將寒色去，年共曉光新。","耿耿他鄉夕，無由展舊親。"]', '["闲居寡言宴，独坐慘风塵。","忽见嚴冬尽，方知列宿春。","夜將寒色去，年共晓光新。","耿耿他乡夕，無由展旧親。"]', '诗', 'shi', '', NULL, '西京守歲 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aee1d767-5c3a-4de7-b9c4-1b9c2958f1df', '同辛簿簡仰酬思玄上人林泉四首 一', '同辛簿簡仰酬思玄上人林泉四首 一', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["聞君招隱地，髣髴武陵春。","緝芰知還楚，披榛似避秦。","崩查年祀積，幽草歲時新。","一謝滄浪水，安知有逸人。"]', '["闻君招隐地，髣髴武陵春。","緝芰知還楚，披榛似避秦。","崩查年祀積，幽草歲时新。","一謝滄浪水，安知有逸人。"]', '诗', 'shi', '', NULL, '同辛簿簡仰酬思玄上人林泉四首 一 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7afdc3f0-ecdd-45fa-8f19-a9a918688460', '同辛簿簡仰酬思玄上人林泉四首 二', '同辛簿簡仰酬思玄上人林泉四首 二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["芳晨臨上月，幽賞狎中園。","有蝶堪成夢，無羊可觸藩。","忘懷南澗藻，蠲思北堂萱。","坐歎華滋歇，思君誰爲言。"]', '["芳晨臨上月，幽賞狎中园。","有蝶堪成梦，無羊可觸藩。","忘懷南澗藻，蠲思北堂萱。","坐歎华滋歇，思君誰爲言。"]', '诗', 'shi', '', NULL, '同辛簿簡仰酬思玄上人林泉四首 二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff002aa-1c25-4b7c-a2fa-909f2ef83bfd', '同辛簿簡仰酬思玄上人林泉四首 三', '同辛簿簡仰酬思玄上人林泉四首 三', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["林泉恣探歷，風景暫裴徊。","客有遷鶯處，人無結駟來。","聚花如薄雪，沸水若輕雷。","今日徒招隱，終知異鑿坏。"]', '["林泉恣探歷，风景暫裴徊。","客有遷鶯处，人無結駟来。","聚花如薄雪，沸水若轻雷。","今日徒招隐，終知異鑿坏。"]', '诗', 'shi', '', NULL, '同辛簿簡仰酬思玄上人林泉四首 三 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3d7d7d-478c-47bc-bf7f-8c9a4f5539c0', '同辛簿簡仰酬思玄上人林泉四首 四', '同辛簿簡仰酬思玄上人林泉四首 四', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["俗遠風塵隔，春還初服遲。","林疑中散地，人似上皇時。","芳杜湘君曲，幽蘭楚客詞。","山中有春草，長似寄相思。"]', '["俗远风塵隔，春還初服遲。","林疑中散地，人似上皇时。","芳杜湘君曲，幽蘭楚客词。","山中有春草，长似寄相思。"]', '诗', 'shi', '', NULL, '同辛簿簡仰酬思玄上人林泉四首 四 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64957b56-388c-4e61-8cf3-b5f557b6b1bc', '秋日餞陸道士陳文林', '秋日餞陸道士陳文林', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["青牛遊華嶽，赤馬走吳宮。","玉柱離鴻怨，金罍浮蟻空。","日霽崤陵雨，塵起洛陽風。","唯當玄度月，千里與君同。"]', '["青牛游华嶽，赤马走吳宮。","玉柱離鴻怨，金罍浮蟻空。","日霽崤陵雨，塵起洛陽风。","唯當玄度月，千里與君同。"]', '诗', 'shi', '', NULL, '秋日餞陸道士陳文林 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227828e3-4cf2-4248-b96e-1343c0136578', '送鄭少府入遼共賦俠客遠從戎', '送鄭少府入遼共賦俠客远從戎', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["邊烽警榆塞，俠客度桑乾。","柳葉開銀鏑，桃花照玉鞍。","滿月臨弓影，連星入劍端。","不學燕丹客，空歌易水寒。"]', '["邊烽警榆塞，俠客度桑乾。","柳葉开銀鏑，桃花照玉鞍。","满月臨弓影，連星入劍端。","不学燕丹客，空歌易水寒。"]', '诗', 'shi', '', NULL, '送鄭少府入遼共賦俠客遠從戎 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0983351-34e7-4c47-a3a2-162d47616a54', '送費六還蜀', '送費六還蜀', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["星樓望蜀道，月峽指吳門。","萬行流別淚，九折切驚魂。","雪影含花落，雲陰帶葉昏。","還愁三徑晚，獨對一清尊。"]', '["星楼望蜀道，月峽指吳门。","万行流別泪，九折切驚魂。","雪影含花落，云陰带葉昏。","還愁三徑晚，独对一清尊。"]', '诗', 'shi', '', NULL, '送費六還蜀 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195b1741-f2ae-4a66-8eb2-6c9b38412364', '秋日送侯四得彈字', '秋日送侯四得彈字', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["我留安豹隱，君去學鵬摶。","岐路分襟易，風雲促膝難。","夕漲流波急，秋山落日寒。","惟有思歸引，悽斷爲君彈。"]', '["我留安豹隐，君去学鵬摶。","岐路分襟易，风云促膝难。","夕漲流波急，秋山落日寒。","惟有思归引，悽斷爲君彈。"]', '诗', 'shi', '', NULL, '秋日送侯四得彈字 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e727d037-44cc-44bf-9909-732df0162e7a', '秋日送尹大赴京', '秋日送尹大赴京', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["挂瓢余隱舜，負鼎爾干湯。","竹葉離罇滿，桃花別路長。","低河耿秋色，落月抱寒光。","素書如可嗣，幽谷竚賓行。"]', '["挂瓢余隐舜，負鼎爾干湯。","竹葉離罇满，桃花別路长。","低河耿秋色，落月抱寒光。","素书如可嗣，幽谷竚賓行。"]', '诗', 'shi', '', NULL, '秋日送尹大赴京 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e305ee57-72fc-42f3-9421-bd88d33157d0', '秋夜送閰五還潤州', '秋夜送閰五還潤州', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["通莊抵舊里，溝水泣新知。","斷雲飄易滯，連露積難披。","素風啼迥堞，驚月繞疎枝。","無力勵短翰，輕舉送長離。"]', '["通莊抵旧里，溝水泣新知。","斷云飄易滯，連露積难披。","素风啼迥堞，驚月繞疎枝。","無力勵短翰，轻舉送长離。"]', '诗', 'shi', '', NULL, '秋夜送閰五還潤州 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4c207d-d884-4123-b01c-90dd5f012dc9', '送王明府參選賦得鶴', '送王明府參選賦得鹤', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["振衣遊紫府，飛蓋背青田。","虛心恆警露，孤影尚凌煙。","離歌悽妙曲，別操繞繁弦。","在陰如可和，輕響會聞天。"]', '["振衣游紫府，飞蓋背青田。","虛心恆警露，孤影尚凌煙。","離歌悽妙曲，別操繞繁弦。","在陰如可和，轻响會闻天。"]', '诗', 'shi', '', NULL, '送王明府參選賦得鶴 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9f4bd5f-2ecb-4a79-85b7-eaea498e7b86', '秋日送別', '秋日送別', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["寂寥心事晚，搖落歲時秋。","共此傷年髪，相看惜去留。","當歌應破涕，哀命返窮愁。","別後能相憶，東陵有故侯。"]', '["寂寥心事晚，搖落歲时秋。","共此傷年髪，相看惜去留。","當歌應破涕，哀命返窮愁。","別後能相憶，东陵有故侯。"]', '诗', 'shi', '', NULL, '秋日送別 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a907cd8f-d460-4840-8d8f-4efe8868d1c2', '別李嶠得勝字', '別李嶠得勝字', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["芳尊徒自滿，別恨轉難勝。","客似遊江岸，人疑上灞陵。","寒更承夜永，涼景向秋澄。","離心何以贈，自有玉壺冰。"]', '["芳尊徒自满，別恨轉难勝。","客似游江岸，人疑上灞陵。","寒更承夜永，涼景向秋澄。","離心何以贈，自有玉壺冰。"]', '诗', 'shi', '', NULL, '別李嶠得勝字 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d152da55-3805-4d82-99b6-62c80cfd3ff0', '在衮州餞宋五之問', '在衮州餞宋五之问', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["淮沂泗水地，梁甫汶陽東。","別路青驪遠，離尊綠蟻空。","柳寒凋密翠，棠晚落疎紅。","別後相思曲，悽斷入琴風。"]', '["淮沂泗水地，梁甫汶陽东。","別路青驪远，離尊綠蟻空。","柳寒凋密翠，棠晚落疎紅。","別後相思曲，悽斷入琴风。"]', '诗', 'shi', '', NULL, '在衮州餞宋五之問 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee99fe2b-4060-4f60-bfec-7bc5e400ef74', '遊靈公觀', '游靈公观', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["靈峰標勝境，神府枕通川。","玉殿斜連漢，金堂迥架煙。","斷風疎晚竹，流水切危弦。","別有青門外，空懷玄圃仙。"]', '["靈峰標勝境，神府枕通川。","玉殿斜連漢，金堂迥架煙。","斷风疎晚竹，流水切危弦。","別有青门外，空懷玄圃仙。"]', '诗', 'shi', '', NULL, '遊靈公觀 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9a9657-fdec-466f-874b-e784efdfbde0', '夏日遊山家同夏少府', '夏日游山家同夏少府', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["返照下層岑，物外狎招尋。","蘭徑薰幽珮，槐庭落暗金。","谷靜風聲徹，山空月色深。","一遣樊籠累，唯餘松桂心。"]', '["返照下層岑，物外狎招尋。","蘭徑薰幽珮，槐庭落暗金。","谷静风声徹，山空月色深。","一遣樊籠累，唯餘松桂心。"]', '诗', 'shi', '', NULL, '夏日遊山家同夏少府 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf317aa-b2c8-46c8-b445-2595beecbcc4', '初秋登王司馬樓宴得同字', '初秋登王司马楼宴得同字', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["展驥端居暇，登龍喜宴同。","締賞三清滿，承歡六義通。","野晦寒陰積，潭虛夕照空。","顧慙非夢鳥，濫此廁雕蟲。"]', '["展驥端居暇，登龙喜宴同。","締賞三清满，承歡六義通。","野晦寒陰積，潭虛夕照空。","顧慙非梦鸟，濫此廁雕蟲。"]', '诗', 'shi', '', NULL, '初秋登王司馬樓宴得同字 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a31f906-c8f6-43f0-919e-6f2c866ee2a1', '初秋於竇六郎宅宴', '初秋於竇六郎宅宴', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["千里風雲契，一朝心賞同。","意盡深交合，神靈俗累空。","草帶銷寒翠，花枝發夜紅。","唯將澹若水，長揖古人風。"]', '["千里风云契，一朝心賞同。","意尽深交合，神靈俗累空。","草带銷寒翠，花枝發夜紅。","唯將澹若水，长揖古人风。"]', '诗', 'shi', '', NULL, '初秋於竇六郎宅宴 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c38bac7c-df0a-4b01-bed7-e3988182cc51', '冬日宴', '冬日宴', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["二三物外友，一百杖頭錢。","賞洽袁公地，情披樂令天。","促席鸞觴滿，當爐獸炭然。","何須攀桂樹，逢此自留連。"]', '["二三物外友，一百杖头錢。","賞洽袁公地，情披乐令天。","促席鸾觴满，當爐獸炭然。","何須攀桂樹，逢此自留連。"]', '诗', 'shi', '', NULL, '冬日宴 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('748e5fe1-9d6d-4f60-ae55-9b43beff357d', '鏤雞子', '鏤雞子', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["幸遇清明節，欣逢舊練人。","刻花爭臉態，寫月競眉新。","暈罷空餘月，詩成倂道春。","誰知懷玉者，含響未吟晨。"]', '["幸遇清明節，欣逢旧練人。","刻花爭臉態，寫月競眉新。","暈罷空餘月，诗成倂道春。","誰知懷玉者，含响未吟晨。"]', '诗', 'shi', '', NULL, '鏤雞子 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8e4588-5318-4bbd-822e-366d6d2ae56a', '詠美人在天津橋', '詠美人在天津橋', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["美女出東鄰，容與上天津。","整衣香滿路，移步襪生塵。","水下看妝影，眉頭畫月新。","寄言曹子建，箇是洛川神。"]', '["美女出东鄰，容與上天津。","整衣香满路，移步襪生塵。","水下看妝影，眉头畫月新。","寄言曹子建，箇是洛川神。"]', '诗', 'shi', '', NULL, '詠美人在天津橋 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a103f7-5097-442e-8f0c-ae0f6264197e', '送宋五之問得涼字', '送宋五之问得涼字', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["願言遊泗水，支離去二漳。","道術君所篤，筌蹄余自忘。","雪威侵竹冷，秋爽帶池涼。","欲騐離襟切，岐路在他鄉。"]', '["願言游泗水，支離去二漳。","道術君所篤，筌蹄余自忘。","雪威侵竹冷，秋爽带池涼。","欲騐離襟切，岐路在他乡。"]', '诗', 'shi', '', NULL, '送宋五之問得涼字 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a83b3d1-fa75-4824-a38c-52c44c167dba', '憲臺出縶寒夜有懷', '憲台出縶寒夜有懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["獨坐懷明發，長謠苦未安。","自應迷北叟，誰肯問南冠。","生死交情異，殷憂歲序闌。","空餘朝夕鳥，相伴夜啼寒。"]', '["独坐懷明發，长謠苦未安。","自應迷北叟，誰肯问南冠。","生死交情異，殷憂歲序闌。","空餘朝夕鸟，相伴夜啼寒。"]', '诗', 'shi', '', NULL, '憲臺出縶寒夜有懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0a2038-5d84-46d5-aa5c-149260def8f5', '送郭少府探得憂字', '送郭少府探得憂字', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["開筵枕德水，輟棹艤仙舟。","貝闕桃花浪，龍門竹箭流。","當歌悽別曲，對酒泣離憂。","還望青門外，空見白雲浮。"]', '["开筵枕德水，輟棹艤仙舟。","貝闕桃花浪，龙门竹箭流。","當歌悽別曲，对酒泣離憂。","還望青门外，空见白云浮。"]', '诗', 'shi', '', NULL, '送郭少府探得憂字 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd56ed7-68df-4c22-8272-1c74fc0d83eb', '冬日過故人任處士書齋', '冬日過故人任处士书斋', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["神交尚投漆，虛室罷遊蘭。","網積窗文亂，苔深履跡殘。","雪明書帳冷，水靜墨池寒。","獨此琴臺夜，流水爲誰彈。"]', '["神交尚投漆，虛室罷游蘭。","網積窗文亂，苔深履跡殘。","雪明书帳冷，水静墨池寒。","独此琴台夜，流水爲誰彈。"]', '诗', 'shi', '', NULL, '冬日過故人任處士書齋 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0abe4244-72e1-44ed-9b5b-538eaff9f813', '送劉少府遊越州', '送劉少府游越州', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["一丘余枕石，三越爾懷鉛。","離亭分鶴蓋，別岸指龍川。","露下蟬聲斷，寒來雁影連。","如何溝水上，悽斷聽離弦。"]', '["一丘余枕石，三越爾懷鉛。","離亭分鹤蓋，別岸指龙川。","露下蟬声斷，寒来雁影連。","如何溝水上，悽斷听離弦。"]', '诗', 'shi', '', NULL, '送劉少府遊越州 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f480e7c-023b-4235-adce-365445c69b13', '賦得白雲抱幽石', '賦得白云抱幽石', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["重巖抱危石，幽澗曳輕雲。","繞鎮仙衣動，飄蓬羽蓋分。","錦色連花靜，苔光帶葉熏。","詎知吳會影，長抱穀城文。"]', '["重巖抱危石，幽澗曳轻云。","繞鎮仙衣动，飄蓬羽蓋分。","錦色連花静，苔光带葉熏。","詎知吳會影，长抱穀城文。"]', '诗', 'shi', '', NULL, '賦得白雲抱幽石 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e824450a-bcf5-46eb-b6d8-138bc17cf8a6', '賦得春雲處處生', '賦得春云处处生', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["千里年光靜，四望春雲生。","槧日祥光舉，疎雲瑞葉輕。","蓋陰籠迥樹，陣影抱危城。","非將吳會遠，飄蕩帝鄉情。"]', '["千里年光静，四望春云生。","槧日祥光舉，疎云瑞葉轻。","蓋陰籠迥樹，陣影抱危城。","非將吳會远，飄蕩帝乡情。"]', '诗', 'shi', '', NULL, '賦得春雲處處生 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c65539db-4e2b-4ce4-a22b-563b6ef3f4f1', '在嶽詠蟬', '在嶽詠蟬', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["西陸蟬聲唱，南冠客思侵。","那堪玄鬢影，來對白頭吟。","露重飛難進，風多響易沈。","無人信高潔，誰爲表予心。"]', '["西陸蟬声唱，南冠客思侵。","那堪玄鬢影，来对白头吟。","露重飞难進，风多响易沈。","無人信高潔，誰爲表予心。"]', '诗', 'shi', '', NULL, '在嶽詠蟬 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944a609b-e752-4265-af6f-816adb90ffd1', '詠水', '詠水', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["列名通地紀，疎派合天津。","波隨月色淨，態逐桃花春。","照霞如隱石，映柳似沈鱗。","終當挹上善，屬意澹交人。"]', '["列名通地紀，疎派合天津。","波隨月色淨，態逐桃花春。","照霞如隐石，映柳似沈鱗。","終當挹上善，屬意澹交人。"]', '诗', 'shi', '', NULL, '詠水 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fe26a8-8070-4284-96c7-3ff1548c62dd', '同張二詠雁', '同張二詠雁', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["唼藻滄江遠，銜盧紫塞長。","霧深迷曉景，風急斷秋行。","陣照通宵月，書封幾夜霜。","無復能鳴分，空知愧稻粱。"]', '["唼藻滄江远，銜盧紫塞长。","霧深迷晓景，风急斷秋行。","陣照通宵月，书封幾夜霜。","無复能鳴分，空知愧稻粱。"]', '诗', 'shi', '', NULL, '同張二詠雁 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be8e645a-f12f-46fc-8cc9-b98104bc61be', '詠雪', '詠雪', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["龍雲玉葉上，鶴雪瑞花新。","影亂銅烏吹，光銷玉馬津。","含輝明素篆，隱迹表祥輪。","幽蘭不可儷，徒自繞陽春。"]', '["龙云玉葉上，鹤雪瑞花新。","影亂銅烏吹，光銷玉马津。","含輝明素篆，隐迹表祥輪。","幽蘭不可儷，徒自繞陽春。"]', '诗', 'shi', '', NULL, '詠雪 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43c06f3-eab6-4d4b-af6f-77e66e3c24a9', '詠雲酒', '詠云酒', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["朔空曾紀曆，帶地舊疏泉。","色泛臨碭瑞，香流赴蜀仙。","款交欣散玉，洽友悅沈錢。","無復中山賞，空吟吳會篇。"]', '["朔空曾紀曆，带地旧疏泉。","色泛臨碭瑞，香流赴蜀仙。","款交欣散玉，洽友悅沈錢。","無复中山賞，空吟吳會篇。"]', '诗', 'shi', '', NULL, '詠雲酒 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155a4eeb-0d10-431f-8d1f-b4eaac313f61', '塵灰', '塵灰', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["洛川流雅韻，秦道擅苛威。","聽歌梁上動，應律管中飛。","光飄神女襪，影落羽人衣。","願言心未翳，終冀效輕微。"]', '["洛川流雅韻，秦道擅苛威。","听歌梁上动，應律管中飞。","光飄神女襪，影落羽人衣。","願言心未翳，終冀效轻微。"]', '诗', 'shi', '', NULL, '塵灰 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59fcea3f-abe8-4110-afe5-fd776a6a5e15', '秋晨同淄川毛司馬秋九詠 秋風', '秋晨同淄川毛司马秋九詠 秋风', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["紫陌炎氛歇，青蘋晚吹浮。","亂竹搖疎影，縈池織細流。","飄香曳舞袖，帶粉泛妝樓。","不分君恩絕，紈扇曲中秋。"]', '["紫陌炎氛歇，青蘋晚吹浮。","亂竹搖疎影，縈池织細流。","飄香曳舞袖，带粉泛妝楼。","不分君恩絕，紈扇曲中秋。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋風 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33b29f9-73ac-4ad1-9977-45e876d86d67', '秋晨同淄川毛司馬秋九詠 秋雲', '秋晨同淄川毛司马秋九詠 秋云', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["南陸銅渾改，西郊玉葉輕。","泛斗瑤光動，臨陽瑞色明。","蓋陰連鳳闕，陣影翼龍城。","詎知時不遇，空傷流滯情。"]', '["南陸銅渾改，西郊玉葉轻。","泛斗瑤光动，臨陽瑞色明。","蓋陰連鳳闕，陣影翼龙城。","詎知时不遇，空傷流滯情。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋雲 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('568f6142-ff89-49f7-bfb8-91d32a1fa7f5', '秋晨同淄川毛司馬秋九詠 秋蟬', '秋晨同淄川毛司马秋九詠 秋蟬', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["九秋行已暮，一枝聊暫安。","隱榆非諫楚，噪柳異悲潘。","分形妝薄鬢，鏤影飾危冠。","自憐疎影斷，寒林夕吹寒。"]', '["九秋行已暮，一枝聊暫安。","隐榆非諫楚，噪柳異悲潘。","分形妝薄鬢，鏤影飾危冠。","自怜疎影斷，寒林夕吹寒。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋蟬 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff128ba-2da9-4a60-8406-5845618b3b51', '秋晨同淄川毛司馬秋九詠 秋露', '秋晨同淄川毛司马秋九詠 秋露', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["玉關寒氣早，金塘秋色歸。","泛掌光逾淨，添荷滴尚微。","變霜凝曉液，承月委圓輝。","別有吳臺上，應濕楚臣衣。"]', '["玉关寒氣早，金塘秋色归。","泛掌光逾淨，添荷滴尚微。","变霜凝晓液，承月委圓輝。","別有吳台上，應濕楚臣衣。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋露 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0b81b7-cf97-49be-a00a-67a7759e9ad3', '秋晨同淄川毛司馬秋九詠 秋月', '秋晨同淄川毛司马秋九詠 秋月', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["雲披玉繩淨，月滿鏡輪圓。","裛露珠暉冷，凌霜桂影寒。","漏彩含疎薄，浮光漾急瀾。","西園徒自賞，南飛終未安。"]', '["云披玉繩淨，月满镜輪圓。","裛露珠暉冷，凌霜桂影寒。","漏彩含疎薄，浮光漾急瀾。","西园徒自賞，南飞終未安。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋月 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb82f7c9-4664-497a-8d25-242a0554db45', '秋晨同淄川毛司馬秋九詠 秋水', '秋晨同淄川毛司马秋九詠 秋水', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["貝闕寒流徹，玉輪秋浪清。","圖雲錦色淨，寫月練花明。","泛曲鵾弦動，隨軒鳳轄驚。","唯當御溝上，悽斷送歸情。"]', '["貝闕寒流徹，玉輪秋浪清。","圖云錦色淨，寫月練花明。","泛曲鵾弦动，隨軒鳳轄驚。","唯當御溝上，悽斷送归情。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋水 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3beea8-4ccb-4c00-95df-9f91dc2bf6d4', '秋晨同淄川毛司馬秋九詠 秋螢', '秋晨同淄川毛司马秋九詠 秋螢', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["玉虬分靜夜，金螢照晚涼。","含輝疑泛月，帶火怯凌霜。","散彩縈虛牖，飄花繞洞房。","下帷如不倦，當解惜餘光。"]', '["玉虬分静夜，金螢照晚涼。","含輝疑泛月，带火怯凌霜。","散彩縈虛牖，飄花繞洞房。","下帷如不倦，當解惜餘光。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋螢 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e80340-ed49-4ef7-aca0-1ad1a5e3ea09', '秋晨同淄川毛司馬秋九詠 秋菊', '秋晨同淄川毛司马秋九詠 秋菊', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["擢秀三秋晚，開芳十步中。","分黃俱笑日，含翠共搖風。","碎影涵流動，浮香隔岸通。","金翹徒可泛，玉斝竟誰同。"]', '["擢秀三秋晚，开芳十步中。","分黄俱笑日，含翠共搖风。","碎影涵流动，浮香隔岸通。","金翹徒可泛，玉斝竟誰同。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋菊 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4de1aa-8aa1-4b0a-89e7-26ec3439ba57', '秋晨同淄川毛司馬秋九詠 秋雁', '秋晨同淄川毛司马秋九詠 秋雁', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["聯翩辭海曲，遙曳指江干。","陣去金河冷，書歸玉塞寒。","帶月凌空易，迷煙逗浦難。","何當同顧影，刷羽泛清瀾。"]', '["聯翩辞海曲，遙曳指江干。","陣去金河冷，书归玉塞寒。","带月凌空易，迷煙逗浦难。","何當同顧影，刷羽泛清瀾。"]', '诗', 'shi', '', NULL, '秋晨同淄川毛司馬秋九詠 秋雁 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c0987c9-5e9a-4795-8b0d-c82c278d366e', '樂大夫挽詞五首 一', '乐大夫挽词五首 一', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["可歎浮生促，吁嗟此路難。","丘陵一起恨，言笑幾時懽。","蕭索郊埏晚，荒涼井徑寒。","誰當門下客，獨見有任安。"]', '["可歎浮生促，吁嗟此路难。","丘陵一起恨，言笑幾时懽。","蕭索郊埏晚，荒涼井徑寒。","誰當门下客，独见有任安。"]', '诗', 'shi', '', NULL, '樂大夫挽詞五首 一 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb568f8-71d7-4845-bc74-25802517f199', '樂大夫挽詞五首 二', '乐大夫挽词五首 二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["蒿里誰家地，松門何代丘。","百年三萬日，一別幾千秋。","返照寒無影，窮泉凍不流。"]', '["蒿里誰家地，松门何代丘。","百年三万日，一別幾千秋。","返照寒無影，窮泉凍不流。"]', '诗', 'shi', '', NULL, '樂大夫挽詞五首 二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5ffcfb-f1dc-499d-be47-a6fbf9a4eb70', '樂大夫挽詞五首 三', '乐大夫挽词五首 三', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["昔去梅笳發，今來薤露晞。","彤騶朝帝闕，丹旐背王畿。","城郭猶疑是，原陵稍覺非。","九原如可作，千載與誰歸。"]', '["昔去梅笳發，今来薤露晞。","彤騶朝帝闕，丹旐背王畿。","城郭猶疑是，原陵稍覺非。","九原如可作，千載與誰归。"]', '诗', 'shi', '', NULL, '樂大夫挽詞五首 三 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487c871a-a858-4d49-9916-6685d9750cb3', '樂大夫挽詞五首 四', '乐大夫挽词五首 四', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["一旦先朝菌，千秋掩夜臺。","青烏新兆去，白馬故人來。","草露當春泣，松風向暮哀。","寧知荒壠外，弔鶴自裴徊。"]', '["一旦先朝菌，千秋掩夜台。","青烏新兆去，白马故人来。","草露當春泣，松风向暮哀。","寧知荒壠外，弔鹤自裴徊。"]', '诗', 'shi', '', NULL, '樂大夫挽詞五首 四 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('836bfbf4-f0e3-4675-a896-5c597a37a54a', '樂大夫挽詞五首 五', '乐大夫挽词五首 五', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["忽見泉臺路，猶疑水鏡懸。","何如開白日，非復覩青天。","華表迎千歲，幽扃送百年。","獨嗟流水引，長掩伯牙弦。"]', '["忽见泉台路，猶疑水镜懸。","何如开白日，非复覩青天。","华表迎千歲，幽扃送百年。","独嗟流水引，长掩伯牙弦。"]', '诗', 'shi', '', NULL, '樂大夫挽詞五首 五 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf7ec3e-66a1-4f31-99a2-0419c946872f', '丹陽刺史挽詞三首 一', '丹陽刺史挽词三首 一', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["百齡嗟倏忽，一旦向山阿。","丹桂銷已盡，青松哀更多。","薰風虛聽曲，薤露反成歌。","自有藏舟處，誰憐隙駟過。"]', '["百齡嗟倏忽，一旦向山阿。","丹桂銷已尽，青松哀更多。","薰风虛听曲，薤露反成歌。","自有藏舟处，誰怜隙駟過。"]', '诗', 'shi', '', NULL, '丹陽刺史挽詞三首 一 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c9c9c6-f4f1-4aef-bf58-9ae7d10a0a8d', '丹陽刺史挽詞三首 二', '丹陽刺史挽词三首 二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["惻愴恆山羽，留連棣萼篇。","佳城非舊日，京兆即新阡。","城郭三千歲，丘陵幾萬年。","唯餘松柏壠，朝夕起寒煙。"]', '["惻愴恆山羽，留連棣萼篇。","佳城非旧日，京兆即新阡。","城郭三千歲，丘陵幾万年。","唯餘松柏壠，朝夕起寒煙。"]', '诗', 'shi', '', NULL, '丹陽刺史挽詞三首 二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28635bb6-7a75-4bb2-96f3-ea3b97a43b22', '丹陽刺史挽詞三首 三', '丹陽刺史挽词三首 三', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["短歌三獻曲，長夜九泉臺。","此室玄扃掩，何年白日開。","荒郊疎古木，寒隧積陳荄。","獨此傷心地，松聲薄暮來。"]', '["短歌三獻曲，长夜九泉台。","此室玄扃掩，何年白日开。","荒郊疎古木，寒隧積陳荄。","独此傷心地，松声薄暮来。"]', '诗', 'shi', '', NULL, '丹陽刺史挽詞三首 三 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7283c0f-95fa-4c73-95ff-9be77f0b20c6', '稱心寺', '稱心寺', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["征帆恣遠尋，逶迤過稱心。","凝滯蘅𦶜岸，沿洄樝柚林。","穿漵不厭曲，艤潭惟愛深。","爲樂凡幾許，聽取舟中琴。"]', '["征帆恣远尋，逶迤過稱心。","凝滯蘅𦶜岸，沿洄樝柚林。","穿漵不厭曲，艤潭惟愛深。","爲乐凡幾許，听取舟中琴。"]', '诗', 'shi', '', NULL, '稱心寺 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8938d82b-fdf4-46f4-8545-b3c58d4adce1', '陪潤州薛司空丹徒桂明府遊招隱寺', '陪潤州薛司空丹徒桂明府游招隐寺', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["共尋招隱寺，初識戴顒家。","還依舊泉壑，應改昔雲霞。","綠竹寒天笋，紅蕉臘月花。","金繩倘留客，爲繫日光斜。"]', '["共尋招隐寺，初識戴顒家。","還依旧泉壑，應改昔云霞。","綠竹寒天笋，紅蕉臘月花。","金繩倘留客，爲繫日光斜。"]', '诗', 'shi', '', NULL, '陪潤州薛司空丹徒桂明府遊招隱寺 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8833fcd8-564e-4ee8-bcf5-c2fb4ab94718', '棹歌行', '棹歌行', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["寫月塗黃罷，凌波拾翠通。","鏡花搖芰日，衣麝入荷風。","葉密舟難蕩，蓮疎浦易空。","鳳媒羞自托，鴛翼恨難窮。","秋帳燈華翠，倡樓粉色紅。","相思無別曲，倂在棹歌中。"]', '["寫月塗黄罷，凌波拾翠通。","镜花搖芰日，衣麝入荷风。","葉密舟难蕩，蓮疎浦易空。","鳳媒羞自托，鴛翼恨难窮。","秋帳灯华翠，倡楼粉色紅。","相思無別曲，倂在棹歌中。"]', '诗', 'shi', '', NULL, '棹歌行 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9846044-c569-4ce0-b97c-6834d55d860c', '海曲書情', '海曲书情', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["薄遊倦千里，勞生負百年。","未能槎上漢，詎肯劍遊燕。","白雲照春海，青山橫曙天。","江濤讓雙璧，渭水擲三錢。","坐惜風光晚，長歌獨塊然。"]', '["薄游倦千里，勞生負百年。","未能槎上漢，詎肯劍游燕。","白云照春海，青山橫曙天。","江濤讓雙璧，渭水擲三錢。","坐惜风光晚，长歌独塊然。"]', '诗', 'shi', '', NULL, '海曲書情 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b069ca02-e0bb-477b-aeef-5e6797c14d6e', '蓬萊鎮', '蓬萊鎮', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["旅客春心斷，邊城夜望高。","野樓疑海氣，白鷺似江濤。","結綬疲三入，承冠泣二毛。","將飛憐弱羽，欲濟乏輕舠。","賴有陽春曲，窮愁且代勞。"]', '["旅客春心斷，邊城夜望高。","野楼疑海氣，白鷺似江濤。","結綬疲三入，承冠泣二毛。","將飞怜弱羽，欲濟乏轻舠。","賴有陽春曲，窮愁且代勞。"]', '诗', 'shi', '', NULL, '蓬萊鎮 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0843e83-f257-47ba-9a06-bc667c4be00d', '和李明府', '和李明府', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["傳聞葉縣履，飛向洛陽城。","馳道臨層掖，津門對小平。","霞殘疑製錦，雲度似飄纓。","藻掞潘江澈，塵虛范甑清。","詎憐衝斗氣，猶向匣中鳴。"]', '["傳闻葉縣履，飞向洛陽城。","驰道臨層掖，津门对小平。","霞殘疑製錦，云度似飄纓。","藻掞潘江澈，塵虛范甑清。","詎怜衝斗氣，猶向匣中鳴。"]', '诗', 'shi', '', NULL, '和李明府 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17216691-40ea-465c-827a-d9170135fb87', '春晚從李長史遊開道林故山', '春晚從李长史游开道林故山', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["幽尋極幽壑，春望陟春臺。","雲光棲斷樹，靈影入仙杯。","古藤依格上，野徑約山隈。","落蘂飜風去，流鶯滿樹來。","興闌荀御動，歸路起浮埃。"]', '["幽尋極幽壑，春望陟春台。","云光棲斷樹，靈影入仙杯。","古藤依格上，野徑約山隈。","落蘂飜风去，流鶯满樹来。","兴闌荀御动，归路起浮埃。"]', '诗', 'shi', '', NULL, '春晚從李長史遊開道林故山 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67810e04-93aa-4299-a636-8d2cb6041478', '冬日野望', '冬日野望', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["故人無與晤，安步陟山椒。","野靜連雲卷，川明斷霧銷。","靈巖聞曉籟，洞浦漲秋潮。","三江歸望斷，千里故鄉遙。","勞歌徒自奏，客魂誰爲招。"]', '["故人無與晤，安步陟山椒。","野静連云卷，川明斷霧銷。","靈巖闻晓籟，洞浦漲秋潮。","三江归望斷，千里故乡遙。","勞歌徒自奏，客魂誰爲招。"]', '诗', 'shi', '', NULL, '冬日野望 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e63dcbb-c6ad-4301-bc74-6a8fef7caa13', '晚渡黃河', '晚渡黄河', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["千里尋歸路，一葦亂平源。","通波連馬頰，迸水急龍門。","照日榮光淨，驚風瑞浪翻。","棹唱臨風斷，樵謳入聽喧。","岸迥秋霞落，潭深夕霧繁。","誰堪逝川上，日暮不歸魂。"]', '["千里尋归路，一葦亂平源。","通波連马頰，迸水急龙门。","照日榮光淨，驚风瑞浪翻。","棹唱臨风斷，樵謳入听喧。","岸迥秋霞落，潭深夕霧繁。","誰堪逝川上，日暮不归魂。"]', '诗', 'shi', '', NULL, '晚渡黃河 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f4eae61-e877-4895-bb79-47537683f391', '宿山莊', '宿山莊', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["金陵一超忽，玉燭幾還周。","露積吳臺草，風入郢門楸。","林虛宿斷霧，磴險挂懸流。","拾青非漢策，化緇類秦裘。","牽迹猶多蹇，勞生未寡尤。","獨此他鄉夢，空山明月秋。"]', '["金陵一超忽，玉燭幾還周。","露積吳台草，风入郢门楸。","林虛宿斷霧，磴險挂懸流。","拾青非漢策，化緇類秦裘。","牽迹猶多蹇，勞生未寡尤。","独此他乡梦，空山明月秋。"]', '诗', 'shi', '', NULL, '宿山莊 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb23bc9b-af6c-4c70-a761-aa336ec1b5b4', '晚度天山有懷京邑', '晚度天山有懷京邑', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["忽上天山路，依然想物華。","雲疑上苑葉，雪似御溝花。","行歎戎麾遠，坐憐衣帶賒。","交河浮絕塞，弱水浸流沙。","旅思徒漂梗，歸期未及瓜。","寧知心斷絕，夜夜泣胡笳。"]', '["忽上天山路，依然想物华。","云疑上苑葉，雪似御溝花。","行歎戎麾远，坐怜衣带賒。","交河浮絕塞，弱水浸流沙。","旅思徒漂梗，归期未及瓜。","寧知心斷絕，夜夜泣胡笳。"]', '诗', 'shi', '', NULL, '晚度天山有懷京邑 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f254b2bd-8fd1-4e45-9107-321a7decdbaa', '夕次蒲類津', '夕次蒲類津', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["二庭歸望斷，萬里客心愁。","山路猶南屬，河源自北流。","晚風連朔氣，新月照邊秋。","竈火通軍壁，烽煙上戍樓。","龍庭但苦戰，燕頷會封侯。","莫作蘭山下，空令漢國羞。"]', '["二庭归望斷，万里客心愁。","山路猶南屬，河源自北流。","晚风連朔氣，新月照邊秋。","竈火通軍壁，烽煙上戍楼。","龙庭但苦戰，燕頷會封侯。","莫作蘭山下，空令漢国羞。"]', '诗', 'shi', '', NULL, '夕次蒲類津 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('598f031a-bae2-46be-af96-21159764821b', '遠使海曲春夜多懷', '远使海曲春夜多懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["長嘯三春晚，端居百慮盈。","未安胡蝶夢，遽切魯禽情。","別島連寰海，離魂斷戍城。","流星疑伴使，低月似依營。","懷祿寧期達，牽時匪狥名。","艱虞行已遠，時迹自相驚。"]', '["长嘯三春晚，端居百慮盈。","未安胡蝶梦，遽切魯禽情。","別島連寰海，離魂斷戍城。","流星疑伴使，低月似依營。","懷祿寧期達，牽时匪狥名。","艱虞行已远，时迹自相驚。"]', '诗', 'shi', '', NULL, '遠使海曲春夜多懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70bd580-e561-4407-8aa9-368b8771aeaf', '早發諸暨', '早發諸暨', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["征夫懷遠路，夙駕上危巒。","薄煙橫絕巘，輕凍澁回湍。","野霧連空暗，山風入曙寒。","帝城臨灞涘，禹穴枕江干。","橘性行應化，蓬心去不安。","獨掩窮途淚，長歌行路難。"]', '["征夫懷远路，夙駕上危巒。","薄煙橫絕巘，轻凍澁回湍。","野霧連空暗，山风入曙寒。","帝城臨灞涘，禹穴枕江干。","橘性行應化，蓬心去不安。","独掩窮途泪，长歌行路难。"]', '诗', 'shi', '', NULL, '早發諸暨 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81202d59-dad1-4a4c-917e-a9ee07931976', '望月有所思', '望月有所思', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["九秋涼風肅，千里月華開。","圓光隨露湛，碎影逐波來。","似霜明玉砌，如鏡寫珠胎。","晚色依關近，邊聲雜吹哀。","離居分照耀，怨緒共裴徊。","自繞南飛羽，空忝北堂才。"]', '["九秋涼风肅，千里月华开。","圓光隨露湛，碎影逐波来。","似霜明玉砌，如镜寫珠胎。","晚色依关近，邊声杂吹哀。","離居分照耀，怨緒共裴徊。","自繞南飞羽，空忝北堂才。"]', '诗', 'shi', '', NULL, '望月有所思 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf4b908-12be-4530-bee1-eab41765043e', '送吳七遊蜀', '送吳七游蜀', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["日觀分齊壤，星橋接蜀門。","桃花嘶別路，竹葉瀉離樽。","夏老蘭猶茂，秋深柳尚繁。","霧銷山望迥，風高野聽喧。","勞歌徒欲奏，贈別竟無言。","唯有當秋月，空照野人園。"]', '["日观分齊壤，星橋接蜀门。","桃花嘶別路，竹葉瀉離樽。","夏老蘭猶茂，秋深柳尚繁。","霧銷山望迥，风高野听喧。","勞歌徒欲奏，贈別竟無言。","唯有當秋月，空照野人园。"]', '诗', 'shi', '', NULL, '送吳七遊蜀 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a62768-402c-411a-a769-43e24dfcb171', '西行別東臺詳正學士', '西行別东台詳正学士', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["意氣坐相親，關河別故人。","客似秦川上，歌疑易水濱。","塞荒行辨玉，臺遠尚名輪。","洩井懷邊將，尋源重漢臣。","上苑梅花早，御溝楊柳新。","只應持此曲，別作邊城春。"]', '["意氣坐相親，关河別故人。","客似秦川上，歌疑易水濱。","塞荒行辨玉，台远尚名輪。","洩井懷邊將，尋源重漢臣。","上苑梅花早，御溝楊柳新。","只應持此曲，別作邊城春。"]', '诗', 'shi', '', NULL, '西行別東臺詳正學士 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3be7897-9013-4ae9-98d7-e966a95177a7', '和王記室從趙王春日遊陀山寺', '和王記室從趙王春日游陀山寺', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["鳥旟陪訪道，鷲嶺狎棲真。","四禪明靜業，三空廣勝因。","祥河疎疊澗，慧日皎重輪。","葉暗龍宮密，花明鹿苑春。","彫談筌奧旨，妙辯漱玄津。","雅曲終難和，徒自奏巴人。"]', '["鸟旟陪訪道，鷲嶺狎棲真。","四禪明静業，三空廣勝因。","祥河疎叠澗，慧日皎重輪。","葉暗龙宮密，花明鹿苑春。","彫談筌奧旨，妙辯漱玄津。","雅曲終难和，徒自奏巴人。"]', '诗', 'shi', '', NULL, '和王記室從趙王春日遊陀山寺 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3579f6bd-6a8a-45f4-b50e-250f3a516e72', '夏日夜憶張二', '夏日夜憶張二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["伏枕憂思深，擁膝獨長吟。","烹鯉無尺素，筌魚勞寸心。","疎麻空有折，芳桂湛無斟。","廣庭含夕氣，閑宇澹虛陰。","織蟲垂夜砌，驚鳥棲暝林。","驩娛百年促，羈病一生侵。","詎堪孤月夜，流水入鳴琴。"]', '["伏枕憂思深，擁膝独长吟。","烹鯉無尺素，筌鱼勞寸心。","疎麻空有折，芳桂湛無斟。","廣庭含夕氣，闲宇澹虛陰。","织蟲垂夜砌，驚鸟棲暝林。","驩娛百年促，羈病一生侵。","詎堪孤月夜，流水入鳴琴。"]', '诗', 'shi', '', NULL, '夏日夜憶張二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd39503a-7504-4ba4-98a8-ec70d3d37bfe', '寒夜獨坐遊子多懷簡知己', '寒夜独坐游子多懷簡知己', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["故鄉眇千里，離憂積萬端。","鶉服長悲碎，蝸廬未卜安。","富鉤徒有想，貧鋏爲誰彈。","柳秋風葉脆，荷曉露文團。","晚金叢岸菊，餘佩下幽蘭。","伐木傷心易，維桑歸去難。","獨有孤明月，時照客庭寒。"]', '["故乡眇千里，離憂積万端。","鶉服长悲碎，蝸廬未卜安。","富鉤徒有想，貧鋏爲誰彈。","柳秋风葉脆，荷晓露文團。","晚金叢岸菊，餘佩下幽蘭。","伐木傷心易，維桑归去难。","独有孤明月，时照客庭寒。"]', '诗', 'shi', '', NULL, '寒夜獨坐遊子多懷簡知己 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f1a311f-0c46-4957-ab49-5fa5f954205b', '在軍中贈先還知己', '在軍中贈先還知己', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["蓬轉俱行役，瓜時獨未還。","魂迷金闕路，望斷玉門關。","獻凱多慙霍，論封幾謝班。","風塵催白首，歲月損紅顏。","落雁低秋塞，驚鳧起暝灣。","胡霜如劍鍔，漢月似刀環。","別後邊庭樹，相思幾度攀。"]', '["蓬轉俱行役，瓜时独未還。","魂迷金闕路，望斷玉门关。","獻凱多慙霍，論封幾謝班。","风塵催白首，歲月損紅顏。","落雁低秋塞，驚鳧起暝灣。","胡霜如劍鍔，漢月似刀环。","別後邊庭樹，相思幾度攀。"]', '诗', 'shi', '', NULL, '在軍中贈先還知己 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60e26fb8-c279-478d-8eab-35c8227ed575', '秋日山行簡梁大官', '秋日山行簡梁大官', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["乘馬陟層阜，回首睇山川。","攢峰銜宿霧，疊巘架寒煙。","百重含翠色，一道落飛泉。","香吹分巖桂，鮮雲抱石蓮。","地偏心易遠，致默體逾玄。","得性虛遊刃，忘言已棄筌。","彈冠勞巧拙，結綬倦牽纏。","不如從四皓，丘中鳴一弦。"]', '["乘马陟層阜，回首睇山川。","攢峰銜宿霧，叠巘架寒煙。","百重含翠色，一道落飞泉。","香吹分巖桂，鲜云抱石蓮。","地偏心易远，致默體逾玄。","得性虛游刃，忘言已棄筌。","彈冠勞巧拙，結綬倦牽纏。","不如從四皓，丘中鳴一弦。"]', '诗', 'shi', '', NULL, '秋日山行簡梁大官 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57072cd6-42bf-457e-a71a-a298d2ac2ed9', '晚泊江鎮', '晚泊江鎮', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["四運移陰律，三翼泛陽侯。","荷香銷晚夏，菊氣入新秋。","夜烏喧粉堞，宿雁下蘆洲。","海霧籠邊徼，江風繞戍樓。","轉蓬驚別渚，徙橘愴離憂。","魂飛灞陵岸，淚盡洞庭流。","振影希鴻陸，逃名謝蟻丘。","還嗟帝鄉遠，空望白雲浮。"]', '["四運移陰律，三翼泛陽侯。","荷香銷晚夏，菊氣入新秋。","夜烏喧粉堞，宿雁下蘆洲。","海霧籠邊徼，江风繞戍楼。","轉蓬驚別渚，徙橘愴離憂。","魂飞灞陵岸，泪尽洞庭流。","振影希鴻陸，逃名謝蟻丘。","還嗟帝乡远，空望白云浮。"]', '诗', 'shi', '', NULL, '晚泊江鎮 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09ec75e0-b22c-4272-b810-8c9aa455086c', '浮槎', '浮槎', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["昔負千尋質，高臨九仞峰。","真心凌晚桂，勁節掩寒松。","忽值風飆折，坐爲波浪衝。","摧殘空有恨，擁腫遂無庸。","渤海三千里，泥沙幾萬重。","似舟飄不定，如梗泛何從。","仙客終難托，良工豈易逢。","徒懷萬乘器，誰爲一先容。"]', '["昔負千尋質，高臨九仞峰。","真心凌晚桂，勁節掩寒松。","忽值风飆折，坐爲波浪衝。","摧殘空有恨，擁腫遂無庸。","渤海三千里，泥沙幾万重。","似舟飄不定，如梗泛何從。","仙客終难托，良工豈易逢。","徒懷万乘器，誰爲一先容。"]', '诗', 'shi', '', NULL, '浮槎 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d88b013-98f5-4fad-809f-efbd3c464b5b', '晚泊河曲', '晚泊河曲', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["三秋倦行役，千里泛歸潮。","通波竹箭水，輕舸木蘭橈。","金隄連曲岸，貝闕影浮橋。","水淨千年近，星飛五老遙。","疊花開宿浪，浮葉下涼飆。","浦荷疎晚菂，津柳漬寒條。","恓惶勞梗泛，悽斷倦蓬飄。","仙槎不可託，河上獨長謠。"]', '["三秋倦行役，千里泛归潮。","通波竹箭水，轻舸木蘭橈。","金隄連曲岸，貝闕影浮橋。","水淨千年近，星飞五老遙。","叠花开宿浪，浮葉下涼飆。","浦荷疎晚菂，津柳漬寒條。","恓惶勞梗泛，悽斷倦蓬飄。","仙槎不可託，河上独长謠。"]', '诗', 'shi', '', NULL, '晚泊河曲 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7953f497-5684-4902-b730-6d7f312bef64', '早發淮口望盱眙', '早發淮口望盱眙', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["養蒙分四瀆，習坎奠三荆。","徙帝留餘地，封王表舊城。","岸昏涵蜃氣，潮滿應雞聲。","洲迥連沙靜，川虛積溜明。","一朝從捧檄，千里倦懸旌。","背流桐柏遠，逗浦木蘭輕。","小山迷隱路，大塊切勞生。","唯有貞心在，獨映寒潭清。"]', '["養蒙分四瀆，習坎奠三荆。","徙帝留餘地，封王表旧城。","岸昏涵蜃氣，潮满應雞声。","洲迥連沙静，川虛積溜明。","一朝從捧檄，千里倦懸旌。","背流桐柏远，逗浦木蘭轻。","小山迷隐路，大塊切勞生。","唯有貞心在，独映寒潭清。"]', '诗', 'shi', '', NULL, '早發淮口望盱眙 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874a0ca3-62ca-4c9f-976b-895b035ac3d6', '邊城落日', '邊城落日', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["紫塞流沙北，黃圖灞水東。","一朝辭俎豆，萬里逐沙蓬。","候月恆持滿，尋源屢鑿空。","野昏邊氣合，烽迥戍煙通。","膂力風塵倦，疆場歲月窮。","河流控積石，山路遠崆峒。","壯志凌蒼兕，精誠貫白虹。","君恩如可報，龍劍有雌雄。"]', '["紫塞流沙北，黄圖灞水东。","一朝辞俎豆，万里逐沙蓬。","候月恆持满，尋源屢鑿空。","野昏邊氣合，烽迥戍煙通。","膂力风塵倦，疆場歲月窮。","河流控積石，山路远崆峒。","壯志凌蒼兕，精誠貫白虹。","君恩如可報，龙劍有雌雄。"]', '诗', 'shi', '', NULL, '邊城落日 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b60d6783-9c7a-4308-949d-8169ca25898c', '宿溫城望軍營', '宿溫城望軍營', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["虜地寒膠折，邊城夜柝聞。","兵符關帝闕，天策動將軍。","塞靜胡笳徹，沙明楚練分。","風旗翻翼影，霜劍轉龍文。","白羽搖如月，青山斷若雲。","煙疎疑卷幔，塵滅似銷氛。","投筆懷班業，臨戎想顧勳。","還應雪漢恥，持此報明君。"]', '["虜地寒膠折，邊城夜柝闻。","兵符关帝闕，天策动將軍。","塞静胡笳徹，沙明楚練分。","风旗翻翼影，霜劍轉龙文。","白羽搖如月，青山斷若云。","煙疎疑卷幔，塵滅似銷氛。","投笔懷班業，臨戎想顧勳。","還應雪漢恥，持此報明君。"]', '诗', 'shi', '', NULL, '宿溫城望軍營 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc08140a-3b05-47e4-9e8f-1dd7184b1516', '過故宋', '過故宋', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["舊國千年盡，荒城四望通。","雲浮非隱帝，日舉類遊童。","綺琴朝化洽，祥石夜論空。","馬去遙奔鄭，蛇分近帶豐。","池文斂束水，竹影漏寒叢。","園兔承行月，川禽避斷風。","故宋誠難定，從梁事未工。","唯當過周客，獨愧吳臺空。"]', '["旧国千年尽，荒城四望通。","云浮非隐帝，日舉類游童。","綺琴朝化洽，祥石夜論空。","马去遙奔鄭，蛇分近带豐。","池文斂束水，竹影漏寒叢。","园兔承行月，川禽避斷风。","故宋誠难定，從梁事未工。","唯當過周客，独愧吳台空。"]', '诗', 'shi', '', NULL, '過故宋 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e0678f-343a-4b68-9904-bff58a5ca0b4', '邊夜有懷', '邊夜有懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["漢地行逾遠，燕山去不窮。","城荒猶築怨，碣毀尚銘功。","古戍煙塵滿，邊庭人事空。","夜關明隴月，秋塞急胡風。","倚伏良難定，榮枯豈易通。","旅魂勞泛梗，離恨斷征蓬。","蘇武封猶薄，崔駰宦不工。","惟餘北叟意，欲寄南飛鴻。"]', '["漢地行逾远，燕山去不窮。","城荒猶築怨，碣毀尚銘功。","古戍煙塵满，邊庭人事空。","夜关明隴月，秋塞急胡风。","倚伏良难定，榮枯豈易通。","旅魂勞泛梗，離恨斷征蓬。","蘇武封猶薄，崔駰宦不工。","惟餘北叟意，欲寄南飞鴻。"]', '诗', 'shi', '', NULL, '邊夜有懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b856ebd-84aa-46c8-9ad9-049b81cbe86b', '傷祝阿王明府', '傷祝阿王明府', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["洛川真氣上，重泉惠政融。","含章光後烈，繼武嗣前雄。","與善良難驗，生涯忽易窮。","翔鳧猶化履，狎雉尚馴童。","錢滿荒階綠，塵浮虛帳紅。","夏餘將宿草，秋近未驚蓬。","煙晦泉門閉，日盡夜臺空。","誰堪孤隴外，獨聽白楊風。"]', '["洛川真氣上，重泉惠政融。","含章光後烈，繼武嗣前雄。","與善良难驗，生涯忽易窮。","翔鳧猶化履，狎雉尚馴童。","錢满荒階綠，塵浮虛帳紅。","夏餘將宿草，秋近未驚蓬。","煙晦泉门閉，日尽夜台空。","誰堪孤隴外，独听白楊风。"]', '诗', 'shi', '', NULL, '傷祝阿王明府 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2acb69-3721-407d-a65e-63418e4008d4', '四月八日題七級', '四月八日題七級', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["化城分鳥堞，香閣俯龍川。","複棟侵黃道，重檐架紫煙。","銘書非晉代，壁畫是梁年。","霸略今何在，王宮尚巋然。","二帝曾遊聖，三卿是偶賢。","因茲遊勝侶，超彼託良緣。","我出有爲界，君登非想天。","悠悠青曠裏，蕩蕩白雲前。","今日經行處，曲音號蓋煙。"]', '["化城分鸟堞，香閣俯龙川。","複棟侵黄道，重檐架紫煙。","銘书非晉代，壁畫是梁年。","霸略今何在，王宮尚巋然。","二帝曾游聖，三卿是偶賢。","因茲游勝侶，超彼託良緣。","我出有爲界，君登非想天。","悠悠青曠裏，蕩蕩白云前。","今日經行处，曲音號蓋煙。"]', '诗', 'shi', '', NULL, '四月八日題七級 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('194b29bc-7915-4130-bcbe-c034996b93ae', '和孫長史秋日臥病', '和孫长史秋日臥病', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["霍第疏天府，潘園近帝臺。","調弦三婦至，置驛五侯來。","尚想歡娛洽，吁嗟歲月催。","金壇分上將，玉帳引瓌材。","決勝鯨波靜，騰謀鳥谷開。","白雲淮水外，紫陌灞陵隈。","節變驚衰柳，笳繁思落梅。","調神和玉燭，掞藻握珠胎。","悵矣欣懷土，居然欲死灰。","還因承雅曲，暫喜躍沈鰓。"]', '["霍第疏天府，潘园近帝台。","調弦三婦至，置驛五侯来。","尚想歡娛洽，吁嗟歲月催。","金壇分上將，玉帳引瓌材。","決勝鯨波静，腾謀鸟谷开。","白云淮水外，紫陌灞陵隈。","節变驚衰柳，笳繁思落梅。","調神和玉燭，掞藻握珠胎。","悵矣欣懷土，居然欲死灰。","還因承雅曲，暫喜躍沈鰓。"]', '诗', 'shi', '', NULL, '和孫長史秋日臥病 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf31adb3-7462-432c-a5c4-0478388ee49c', '餞鄭安陽入蜀', '餞鄭安陽入蜀', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["彭山折坂外，井絡少城隈。","地是三巴俗，人非百里材。","畏途君悵望，岐路我裴徊。","心賞風煙隔，容華歲月催。","遙遙分鳳野，去去轉龍媒。","遺錦非前邑，鳴琴即舊臺。","劍門千仞起，石路五丁開。","海客乘槎渡，仙童馭竹回。","魂將離鶴遠，思逐斷猿哀。","唯有雙鳧舄，飛去復飛來。"]', '["彭山折坂外，井絡少城隈。","地是三巴俗，人非百里材。","畏途君悵望，岐路我裴徊。","心賞风煙隔，容华歲月催。","遙遙分鳳野，去去轉龙媒。","遺錦非前邑，鳴琴即旧台。","劍门千仞起，石路五丁开。","海客乘槎渡，仙童馭竹回。","魂將離鹤远，思逐斷猿哀。","唯有雙鳧舄，飞去复飞来。"]', '诗', 'shi', '', NULL, '餞鄭安陽入蜀 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f09ced-8f0d-433f-9c5b-8c6ab2031ad1', '詠懷', '詠懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["少年識事淺，不知交道難。","一言芬若桂，四海臭如蘭。","寶劍思存楚，金鎚許報韓。","虛心徒有託，循迹諒無端。","太息關山險，吁嗟歲月闌。","忘機殊會俗，守拙異懷安。","阮籍空長嘯，劉琨獨未懽。","十步庭芳斂，三秋隴月團。","槐疎非盡意，松晚夜凌寒。","悲調弦中急，窮愁醉裏寬。","莫將流水引，空向俗人彈。"]', '["少年識事淺，不知交道难。","一言芬若桂，四海臭如蘭。","寶劍思存楚，金鎚許報韓。","虛心徒有託，循迹諒無端。","太息关山險，吁嗟歲月闌。","忘機殊會俗，守拙異懷安。","阮籍空长嘯，劉琨独未懽。","十步庭芳斂，三秋隴月團。","槐疎非尽意，松晚夜凌寒。","悲調弦中急，窮愁醉裏寬。","莫將流水引，空向俗人彈。"]', '诗', 'shi', '', NULL, '詠懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b480e85b-070f-477e-a2e0-072e207722f0', '春日離長安客中言懷', '春日離长安客中言懷', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["年華開早律，霽色蕩芳晨。","城闕千門曉，山河四望春。","御溝通太液，戚里對平津。","寶瑟調中婦，金罍引上賓。","劇談推曼倩，驚坐揖陳遵。","意氣一言合，風期萬里親。","自惟安直道，守拙忌因人。","談器非先木，圖榮異後薪。","揶揄慙路鬼，憔悴切波臣。","玄草終疲漢，烏裘幾滯秦。","生涯無歲月，岐路有風塵。","還嗟太行道，處處白頭新。"]', '["年华开早律，霽色蕩芳晨。","城闕千门晓，山河四望春。","御溝通太液，戚里对平津。","寶瑟調中婦，金罍引上賓。","劇談推曼倩，驚坐揖陳遵。","意氣一言合，风期万里親。","自惟安直道，守拙忌因人。","談器非先木，圖榮異後薪。","揶揄慙路鬼，憔悴切波臣。","玄草終疲漢，烏裘幾滯秦。","生涯無歲月，岐路有风塵。","還嗟太行道，处处白头新。"]', '诗', 'shi', '', NULL, '春日離長安客中言懷 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69c96b89-d73a-4e21-ba84-ddd2c8e17f92', '夕次舊吳', '夕次旧吳', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["維舟背楚服，振策下吳畿。","盛德弘三讓，雄圖枕九圍。","黃池通霸跡，赤壁暢戎威。","文物俄遷謝，英靈有盛衰。","行歎鴟夷沒，遽惜湛盧飛。","地古煙塵暗，年深館宇稀。","山川四望是，人事一朝非。","懸劍空留信，亡珠尚識機。","鄭風遙可託，關月眇難依。","西北雲逾滯，東南氣轉微。","徒懷伯通隱，多謝買臣歸。","唯有荒臺露，薄暮濕征衣。"]', '["維舟背楚服，振策下吳畿。","盛德弘三讓，雄圖枕九圍。","黄池通霸跡，赤壁暢戎威。","文物俄遷謝，英靈有盛衰。","行歎鴟夷沒，遽惜湛盧飞。","地古煙塵暗，年深館宇稀。","山川四望是，人事一朝非。","懸劍空留信，亡珠尚識機。","鄭风遙可託，关月眇难依。","西北云逾滯，东南氣轉微。","徒懷伯通隐，多謝買臣归。","唯有荒台露，薄暮濕征衣。"]', '诗', 'shi', '', NULL, '夕次舊吳 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5934743-bc79-4911-9fdb-e6625d9aba1b', '早秋出塞寄東臺詳正學士', '早秋出塞寄东台詳正学士', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["促駕踰三水，長驅望五原。","天階分斗極，地理接樓煩。","溪月明關隴，戎雲聚塞垣。","山川殊物候，風壤異涼喧。","戍古秋塵合，沙寒宿霧繁。","昔余迷學步，投迹忝詞源。","蘭渚浮延閣，蓬山款禁園。","彯纓陪紱冕，載筆偶璵璠。","汲冢寧詳蠹，秦牢詎辨冤。","一朝從篚服，千里騖輕軒。","鄉夢隨魂斷，邊聲入聽喧。","南圖終鎩翮，北上遽催轅。","弔影慙連茹，浮生倦觸藩。","數奇何以託，桃李自無言。"]', '["促駕踰三水，长驱望五原。","天階分斗極，地理接楼煩。","溪月明关隴，戎云聚塞垣。","山川殊物候，风壤異涼喧。","戍古秋塵合，沙寒宿霧繁。","昔余迷学步，投迹忝词源。","蘭渚浮延閣，蓬山款禁园。","彯纓陪紱冕，載笔偶璵璠。","汲冢寧詳蠹，秦牢詎辨冤。","一朝從篚服，千里騖轻軒。","乡梦隨魂斷，邊声入听喧。","南圖終鎩翮，北上遽催轅。","弔影慙連茹，浮生倦觸藩。","數奇何以託，桃李自無言。"]', '诗', 'shi', '', NULL, '早秋出塞寄東臺詳正學士 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36dd309e-3630-4f6d-9bfe-1c0b5e534d61', '幽縶書情通簡知己', '幽縶书情通簡知己', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["昔歲逢楊意，觀光貴楚材。","穴疑丹鳳起，場似白駒來。","一命淪驕餌，三緘慎禍胎。","不言勞倚伏，忽此遘邅迴。","驄馬刑章峻，蒼鷹獄吏猜。","絕縑非易辨，疑璧果難裁。","揆畫慙周道，端憂滯夏臺。","生涯一滅裂，岐路幾裴徊。","青陸春芳動，黃沙旅思催。","圓扉長寂寂，疎網尚恢恢。","入穽先搖尾，迷津正曝腮。","覆盆徒望日，蟄戶未經雷。","霜歇蘭猶敗，風多木屢摧。","地幽蠶室閉，門靜雀羅開。","自憫秦冤痛，誰憐楚奏哀。","漢陽窮鳥客，梁甫臥龍才。","有氣還衝斗，無時會鑿坏。","莫言韓長孺，長作不然灰。"]', '["昔歲逢楊意，观光貴楚材。","穴疑丹鳳起，場似白駒来。","一命淪驕餌，三緘慎禍胎。","不言勞倚伏，忽此遘邅迴。","驄马刑章峻，蒼鷹獄吏猜。","絕縑非易辨，疑璧果难裁。","揆畫慙周道，端憂滯夏台。","生涯一滅裂，岐路幾裴徊。","青陸春芳动，黄沙旅思催。","圓扉长寂寂，疎網尚恢恢。","入穽先搖尾，迷津正曝腮。","覆盆徒望日，蟄戶未經雷。","霜歇蘭猶敗，风多木屢摧。","地幽蠶室閉，门静雀羅开。","自憫秦冤痛，誰怜楚奏哀。","漢陽窮鸟客，梁甫臥龙才。","有氣還衝斗，無时會鑿坏。","莫言韓长孺，长作不然灰。"]', '诗', 'shi', '', NULL, '幽縶書情通簡知己 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabe664b-6a0c-428d-8823-ca5471fc8ef2', '久戍邊城有懷京邑', '久戍邊城有懷京邑', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["擾擾風塵地，遑遑名利途。","盈虛一易舛，心迹兩難俱。","弱齡小山志，寧期大丈夫。","九微光賁玉，千仞忽彈珠。","棘寺游三禮，蓬山簉八儒。","懷鉛慙後進，投筆願前驅。","北走非通趙，西之似化胡。","錦車朝促候，刁斗夜傳呼。","戰士青絲絡，將軍黃石符。","連星入寶劍，半月上彫弧。","拜井開疎勒，鳴桴動密須。","戎機習短蔗，祆祲靜長榆。","季月炎初盡，邊亭草早枯。","層陰籠古木，窮色變寒蕪。","海鶴聲嘹唳，城烏尾畢逋。","葭繁秋色引，桂滿夕輪虛。","行役風霜久，鄉園夢想孤。","灞池遙夏國，秦海望陽紆。","沙塞三千里，京城十二衢。","楊溝連鳳闕，槐路擬鴻都。","璧殿規宸象，金堤法斗樞。","雲浮西北蓋，月照東南隅。","寶帳垂連理，銀牀轉轆轤。","廣筵留上客，豐饌引中廚。","漏緩金徒箭，嬌繁玉女壺。","秋濤飛喻馬，秋水泛仙艫。","意氣風雲合，言忘道術趨。","共矜名已泰，詎肯沫相濡。","有志慙雕朽，無庸類散樗。","關山暫超忽，形影歎艱虞。","結網空知羨，圖榮豈自誣。","忘情同塞馬，比德類宛駒。","隴阪肝腸絕，陽關亭候迂。","迷魂驚落雁，離恨斷飛鳧。","春去榮華盡，年來歲月蕪。","邊愁傷郢調，鄉思繞吳歈。","河氣通中國，山途限外區。","相思若可寄，冰泮有銜蘆。"]', '["擾擾风塵地，遑遑名利途。","盈虛一易舛，心迹兩难俱。","弱齡小山志，寧期大丈夫。","九微光賁玉，千仞忽彈珠。","棘寺游三禮，蓬山簉八儒。","懷鉛慙後進，投笔願前驱。","北走非通趙，西之似化胡。","錦车朝促候，刁斗夜傳呼。","戰士青絲絡，將軍黄石符。","連星入寶劍，半月上彫弧。","拜井开疎勒，鳴桴动密須。","戎機習短蔗，祆祲静长榆。","季月炎初尽，邊亭草早枯。","層陰籠古木，窮色变寒蕪。","海鹤声嘹唳，城烏尾畢逋。","葭繁秋色引，桂满夕輪虛。","行役风霜久，乡园梦想孤。","灞池遙夏国，秦海望陽紆。","沙塞三千里，京城十二衢。","楊溝連鳳闕，槐路擬鴻都。","璧殿規宸象，金堤法斗樞。","云浮西北蓋，月照东南隅。","寶帳垂連理，銀牀轉轆轤。","廣筵留上客，豐饌引中廚。","漏緩金徒箭，嬌繁玉女壺。","秋濤飞喻马，秋水泛仙艫。","意氣风云合，言忘道術趨。","共矜名已泰，詎肯沫相濡。","有志慙雕朽，無庸類散樗。","关山暫超忽，形影歎艱虞。","結網空知羨，圖榮豈自誣。","忘情同塞马，比德類宛駒。","隴阪肝腸絕，陽关亭候迂。","迷魂驚落雁，離恨斷飞鳧。","春去榮华尽，年来歲月蕪。","邊愁傷郢調，乡思繞吳歈。","河氣通中国，山途限外區。","相思若可寄，冰泮有銜蘆。"]', '诗', 'shi', '', NULL, '久戍邊城有懷京邑 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aad284b-d25d-4776-bfe1-5bebc6ebe062', '在軍登城樓', '在軍登城楼', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["城上風威冷，江中水氣寒。","戎衣何日定，歌舞入長安。"]', '["城上风威冷，江中水氣寒。","戎衣何日定，歌舞入长安。"]', '诗', 'shi', '', NULL, '在軍登城樓 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc9a6bbc-8a05-4c89-a41c-74c271b6065b', '於易水送人', '於易水送人', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["此地別燕丹，壯士髪衝冠。","昔時人已沒，今日水猶寒。"]', '["此地別燕丹，壯士髪衝冠。","昔时人已沒，今日水猶寒。"]', '诗', 'shi', '', NULL, '於易水送人 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccef7202-1a53-43fa-907c-462aa0e07525', '詠鏡', '詠镜', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["寫月無芳桂，照日有花菱。","不持光謝水，翻將影學冰。"]', '["寫月無芳桂，照日有花菱。","不持光謝水，翻將影学冰。"]', '诗', 'shi', '', NULL, '詠鏡 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd37f32-04db-41de-895b-45202c59f88c', '挑燈杖', '挑灯杖', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["稟質非貪熱，焦心豈憚熬。","終知不自潤，何處用脂膏。"]', '["稟質非貪熱，焦心豈憚熬。","終知不自潤，何处用脂膏。"]', '诗', 'shi', '', NULL, '挑燈杖 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93fbc3f7-f7be-4276-bf47-08dd2dd2cc2b', '詠塵', '詠塵', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["凌波起羅襪，含風染素衣。","別有知音調，聞歌應自飛。"]', '["凌波起羅襪，含风染素衣。","別有知音調，闻歌應自飞。"]', '诗', 'shi', '', NULL, '詠塵 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3384767-fea6-41d4-9d35-11c4eb73f95f', '翫初月', '翫初月', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["忌滿光先缺，乘昏影暫流。","既能明似鏡，何用曲如鉤。"]', '["忌满光先缺，乘昏影暫流。","既能明似镜，何用曲如鉤。"]', '诗', 'shi', '', NULL, '翫初月 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6131d6e0-1ee4-42b8-848c-eb4744bbe385', '送別', '送別', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["寒更承夜永，涼夕向秋澄。","離心何以贈，自有玉壺冰。"]', '["寒更承夜永，涼夕向秋澄。","離心何以贈，自有玉壺冰。"]', '诗', 'shi', '', NULL, '送別 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19be5ca-d1d4-4844-8397-89b4df030477', '憶蜀地佳人', '憶蜀地佳人', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["東西吳蜀關山遠，魚來雁去兩難聞。","莫怪常有千行淚，只爲陽臺一片雲。"]', '["东西吳蜀关山远，鱼来雁去兩难闻。","莫怪常有千行泪，只爲陽台一片云。"]', '诗', 'shi', '', NULL, '憶蜀地佳人 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b038a31d-5b14-42bc-bc8e-ce616ebb390d', '詠鵝', '詠鵝', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["鵝，鵝，鵝，曲項向天歌。","白毛浮綠水，紅掌撥清波。"]', '["鵝，鵝，鵝，曲項向天歌。","白毛浮綠水，紅掌撥清波。"]', '诗', 'shi', '', NULL, '詠鵝 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22de88cd-87c4-4892-bf6c-8f2b3cfecdee', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["此地巖壑數千重，吾君駕鶴□乘龍。","掩暎葉光含翡翠，參差石影帶芙蓉。","白日將移衝疊巘，玄雲欲度礙高峰。","對酒鳴琴追野趣，時聞清吹入長松。"]', '["此地巖壑數千重，吾君駕鹤□乘龙。","掩暎葉光含翡翠，參差石影带芙蓉。","白日將移衝叠巘，玄云欲度礙高峰。","对酒鳴琴追野趣，时闻清吹入长松。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03baef25-f668-4ca3-85b9-da900235eb6f', '仙鶴篇', '仙鹤篇', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["白鶴乘空何處來？青田紫蓋本相依。","緱山七月雖長去，遼水千年會憶歸。","緱山杳杳翔寥廓，遼水纍纍歎城郭。","經隨羽客步丹丘，曾逐仙人遊碧落。","迢迢碧落斷氛埃，霞堂雲閣幾重開。","欲尋東海黃金竈，仍向西山白玉臺。","九臯獨唳方清切，五里驚羣俄斷絕。","月下分行似度雲，風前颺影疑迴雪。","風前月下路漫漫，水宿雲翔去幾般。","宛轉能傾吳國市，裴回巧拂漢皇壇。","琴中作曲從來易，鼓裏傳聲有甚難。","夜夜恆飛銀漢曲，朝朝常飲玉池瀾。","別有聞簫出紫煙，還如化履上青天。","霜毛忽控三神下，玉羽俄看二客旋。","燕雀終迷橫海志，蜉蝣豈識在陰年。","莫言一舉輕千里，爲與三山送九仙。"]', '["白鹤乘空何处来？青田紫蓋本相依。","緱山七月雖长去，遼水千年會憶归。","緱山杳杳翔寥廓，遼水纍纍歎城郭。","經隨羽客步丹丘，曾逐仙人游碧落。","迢迢碧落斷氛埃，霞堂云閣幾重开。","欲尋东海黄金竈，仍向西山白玉台。","九臯独唳方清切，五里驚羣俄斷絕。","月下分行似度云，风前颺影疑迴雪。","风前月下路漫漫，水宿云翔去幾般。","宛轉能傾吳国市，裴回巧拂漢皇壇。","琴中作曲從来易，鼓裏傳声有甚难。","夜夜恆飞銀漢曲，朝朝常饮玉池瀾。","別有闻簫出紫煙，還如化履上青天。","霜毛忽控三神下，玉羽俄看二客旋。","燕雀終迷橫海志，蜉蝣豈識在陰年。","莫言一舉轻千里，爲與三山送九仙。"]', '诗', 'shi', '', NULL, '仙鶴篇 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab1bdbd-2f09-4776-b270-27340a1780b4', '宴龍泓', '宴龙泓', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["登臨開勝託，眺矚盡良遊。","巖崿縈紆上，澄潭屈曲流。","泛蘭清興洽，折桂野文遒。","別後相思處，崎嶇碧澗幽。"]', '["登臨开勝託，眺矚尽良游。","巖崿縈紆上，澄潭屈曲流。","泛蘭清兴洽，折桂野文遒。","別後相思处，崎嶇碧澗幽。"]', '诗', 'shi', '', NULL, '宴龍泓 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e17f8c-056d-4f4a-945f-3cf140f88c4b', '凝碧池侍宴應制得出水槎', '凝碧池侍宴應制得出水槎', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["彼木生何代，爲槎復幾年。","欲乘銀漢曲，先泛玉池邊。","擁溜根橫岸，沈波影倒懸。","無勞問蜀客，此處即高天。"]', '["彼木生何代，爲槎复幾年。","欲乘銀漢曲，先泛玉池邊。","擁溜根橫岸，沈波影倒懸。","無勞问蜀客，此处即高天。"]', '诗', 'shi', '', NULL, '凝碧池侍宴應制得出水槎 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b2a93e-276f-49a2-89b6-6d39744ebdad', '奉和宴小山池賦得谿字應制', '奉和宴小山池賦得谿字應制', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["年光開碧沼，雲色歛青谿。","凍解魚方戲，風暄鳥欲啼。","巖泉飛野鶴，石鏡舞山雞。","柳發龍鱗出，松新麈尾齊。","九韶從此驗，三月定應迷。"]', '["年光开碧沼，云色歛青谿。","凍解鱼方戲，风暄鸟欲啼。","巖泉飞野鹤，石镜舞山雞。","柳發龙鱗出，松新麈尾齊。","九韶從此驗，三月定應迷。"]', '诗', 'shi', '', NULL, '奉和宴小山池賦得谿字應制 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4c0cfa-7fcb-4be5-b4c4-d77c7dfb3f65', '奉和過梁王宅即目應制', '奉和過梁王宅即目應制', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["巖居多水石，野宅滿風煙。","本謂開三徑，俄欣降九天。","穿林移步輦，拂岸轉行旃。","鳳竹初垂籜，龜河未吐蓮。","願持山作壽，恆用劫爲年。"]', '["巖居多水石，野宅满风煙。","本謂开三徑，俄欣降九天。","穿林移步輦，拂岸轉行旃。","鳳竹初垂籜，龟河未吐蓮。","願持山作壽，恆用劫爲年。"]', '诗', 'shi', '', NULL, '奉和過梁王宅即目應制 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d441a467-c7a4-4a9b-8f4a-bcba626c16d8', '奉和春日游龍門應制', '奉和春日游龙门應制', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["鳳架臨香地，龍輿上翠微。","星宮含雨氣，月殿抱春輝。","碧澗長虹下，雕梁早燕歸。","雲疑浮寶蓋，石似拂天衣。","露草侵階長，風花遶席飛。","日斜宸賞洽，清吹入重闈。"]', '["鳳架臨香地，龙輿上翠微。","星宮含雨氣，月殿抱春輝。","碧澗长虹下，雕梁早燕归。","云疑浮寶蓋，石似拂天衣。","露草侵階长，风花遶席飞。","日斜宸賞洽，清吹入重闈。"]', '诗', 'shi', '', NULL, '奉和春日游龍門應制 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d547f652-9a67-484b-8dba-375f39461e1e', '秋日于天中寺尋復禮上人', '秋日于天中寺尋复禮上人', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["妙域三時殿，香巖七寶宮。","金繩先界道，玉柄即談空。","喻筏知何極，傳燈竟不窮。","彌天高義遠，初地勝因通。","理詣歸一處，心行不二中。","有無雙惑遣，真俗兩緣同。","摘葉疑焚翠，投花若散紅。","網珠遙映日，檐鐸近吟風。","定沼寒光素，禪枝暝色葱。","願隨方便力，長冀釋塵籠。"]', '["妙域三时殿，香巖七寶宮。","金繩先界道，玉柄即談空。","喻筏知何極，傳灯竟不窮。","彌天高義远，初地勝因通。","理詣归一处，心行不二中。","有無雙惑遣，真俗兩緣同。","摘葉疑焚翠，投花若散紅。","網珠遙映日，檐鐸近吟风。","定沼寒光素，禪枝暝色葱。","願隨方便力，长冀釋塵籠。"]', '诗', 'shi', '', NULL, '秋日于天中寺尋復禮上人 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('459d5ac2-2367-4ab4-817c-d6e9b21867e4', '句', '句', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["雲螭非易匹，月駟本難儔。"]', '["云螭非易匹，月駟本难儔。"]', '诗', 'shi', '', NULL, '句 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36164dcf-cc54-4fbe-8a1c-010f4076b182', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '8c6d0222-cd7a-4245-84ee-9243a6a08e1c', '唐', '["六龍驤首曉駸駸，七聖陪軒集潁陰。","千丈松蘿交翠幕，一丘山水當鳴琴。","青鳥白雲王母使，垂藤斷葛野人心。","山中日暮幽巖下，泠然香吹落花深。"]', '["六龙驤首晓駸駸，七聖陪軒集潁陰。","千丈松蘿交翠幕，一丘山水當鳴琴。","青鸟白云王母使，垂藤斷葛野人心。","山中日暮幽巖下，泠然香吹落花深。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 張易之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942dd601-a3d6-47a6-b960-1efd6eddb24d', '侍從過公主南宅侍宴探得風字應制', '侍從過公主南宅侍宴探得风字應制', '8c6d0222-cd7a-4245-84ee-9243a6a08e1c', '唐', '["逐賞平陽第，鳴笳上苑東。","鳥吟千戶竹，蝶舞百花叢。","時攀小山桂，共挹大王風。","坐客無勞起，秦簫曲未終。"]', '["逐賞平陽第，鳴笳上苑东。","鸟吟千戶竹，蝶舞百花叢。","时攀小山桂，共挹大王风。","坐客無勞起，秦簫曲未終。"]', '诗', 'shi', '', NULL, '侍從過公主南宅侍宴探得風字應制 張易之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5091b00a-4a76-456b-9623-f5b50eb1252e', '出塞', '出塞', '8c6d0222-cd7a-4245-84ee-9243a6a08e1c', '唐', '["俠客重恩光，駿馬飾金裝。","瞥聞傳羽檄，馳突救邊荒。","轉戰磨笄地，橫行戴斗鄉。","將軍占太白，小婦怨流黃。","騕褭青絲騎，娉婷紅粉妝。","一春鶯度曲，八月雁成行。","誰堪坐秋思，羅袖拂空牀。"]', '["俠客重恩光，駿马飾金裝。","瞥闻傳羽檄，驰突救邊荒。","轉戰磨笄地，橫行戴斗乡。","將軍占太白，小婦怨流黄。","騕褭青絲騎，娉婷紅粉妝。","一春鶯度曲，八月雁成行。","誰堪坐秋思，羅袖拂空牀。"]', '诗', 'shi', '', NULL, '出塞 張易之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2864c4b-9c98-44f0-802a-490a8478304b', '泛舟侍宴應制', '泛舟侍宴應制', '8c6d0222-cd7a-4245-84ee-9243a6a08e1c', '唐', '["平明出御溝，解纜坐迴舟。","綠水澄明月，紅羅結綺樓。","弦歌爭浦入，冠蓋逐川流。","白魚臣作伴，相對舞王舟。"]', '["平明出御溝，解纜坐迴舟。","綠水澄明月，紅羅結綺楼。","弦歌爭浦入，冠蓋逐川流。","白鱼臣作伴，相对舞王舟。"]', '诗', 'shi', '', NULL, '泛舟侍宴應制 張易之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44c9bf8-b76d-400b-8455-2d17c3af2d4a', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '75f375f5-ccde-4c1e-b79e-0453c71a242a', '唐', '["雲車遙裔三珠樹，帳殿交陰八桂叢。","磵險泉聲疑度雨，川平橋勢若晴虹。","叔夜彈琴歌白雪，孫登長嘯韻清風。","即此陪歡遊閬苑，無勞辛苦向崆峒。"]', '["云车遙裔三珠樹，帳殿交陰八桂叢。","磵險泉声疑度雨，川平橋勢若晴虹。","叔夜彈琴歌白雪，孫登长嘯韻清风。","即此陪歡游閬苑，無勞辛苦向崆峒。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 張昌宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86629c14-0fcf-4095-9206-7243637e8a31', '少年行', '少年行', '75f375f5-ccde-4c1e-b79e-0453c71a242a', '唐', '["少年不識事，落魄遊韓魏。","珠軒流水車，玉勒浮雲騎。","縱橫意不一，然諾心無二。","白璧贈穰苴，黃金奉毛遂。","妙舞飄龍管，清歌吟鳳吹。","三春小苑遊，千日中山醉。","直言身可沈，誰論名與利。","依倚孟嘗君，自知能市義。"]', '["少年不識事，落魄游韓魏。","珠軒流水车，玉勒浮云騎。","縱橫意不一，然諾心無二。","白璧贈穰苴，黄金奉毛遂。","妙舞飄龙管，清歌吟鳳吹。","三春小苑游，千日中山醉。","直言身可沈，誰論名與利。","依倚孟嘗君，自知能市義。"]', '诗', 'shi', '', NULL, '少年行 張昌宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b786ad-a9ee-4453-991e-5f366bff798a', '太平公主山亭侍宴', '太平公主山亭侍宴', '75f375f5-ccde-4c1e-b79e-0453c71a242a', '唐', '["淮南有小山，嬴女隱其間。","折桂芙蓉浦，吹簫明月灣。","扇掩將雛曲，釵承墮馬鬟。","歡情本無限，莫掩洛城關。"]', '["淮南有小山，嬴女隐其间。","折桂芙蓉浦，吹簫明月灣。","扇掩將雛曲，釵承墮马鬟。","歡情本無限，莫掩洛城关。"]', '诗', 'shi', '', NULL, '太平公主山亭侍宴 張昌宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b0e58c-a5c6-4211-b86e-9e779ba63437', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["玉洞幽尋更是天，朱霞綠景鎮韶年。","飛花藉藉迷行路，囀鳥遙遙作管弦。","霧隱長林成翠幄，風吹細雨即虹泉。","此中碧酒恆參聖，浪道崑山別有仙。"]', '["玉洞幽尋更是天，朱霞綠景鎮韶年。","飞花藉藉迷行路，囀鸟遙遙作管弦。","霧隐长林成翠幄，风吹細雨即虹泉。","此中碧酒恆參聖，浪道崑山別有仙。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f499d7-37a4-4d0f-9cec-7976c13e53e8', '子夜冬歌', '子夜冬歌', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["朔風扣羣木，嚴霜凋百草。","借問月中人，安得長不老。"]', '["朔风扣羣木，嚴霜凋百草。","借问月中人，安得长不老。"]', '诗', 'shi', '', NULL, '子夜冬歌 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f903c883-52c3-4871-b133-abdbccff5360', '舞馬篇', '舞马篇', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["星精龍種競騰驤，雙眼黃金紫豔光。","一朝逢遇昇平代，伏皂銜圖事帝王。","我皇盛德苞六宇，俗泰時和虞石拊。","昔聞九代有餘名，今日百獸先來舞。","鉤陳周衞儼旌旄，鐘鎛陶匏聲殷地。","承雲嘈囋駭日靈，調露鏗鈜動天駟。","奔塵飛箭若麟螭，躡景追風忽見知。","咀銜拉鐵並權奇，被服雕章何陸離。","紫玉鳴珂臨寶鐙，青絲綵絡帶金羈。","隨歌鼓而電驚，逐丸劒而飆馳。","態聚𨄳還急，驕凝驟不移。","光敵白日下，氣擁綠煙垂。","婉轉盤跚殊未已，懸空步驟紅塵起。","驚鳧翔鷺不堪儔，矯鳳迴鸞那足擬。","蘅垂桂褭香氛氳，長鳴汗血盡浮雲。","不辭辛苦來東道，祗爲簫韶朝夕聞。","閶闔間，玉臺側，承恩煦兮生光色。","鸞鏘鏘，車翼翼，備國容兮爲戎飾。","充雲翹兮天子庭，荷日用兮情無極。","吉良乘兮一千歲，神是得兮天地期。","大易占云南山壽，䟃𧽼共樂聖明時。"]', '["星精龙種競腾驤，雙眼黄金紫豔光。","一朝逢遇昇平代，伏皂銜圖事帝王。","我皇盛德苞六宇，俗泰时和虞石拊。","昔闻九代有餘名，今日百獸先来舞。","鉤陳周衞儼旌旄，鐘鎛陶匏声殷地。","承云嘈囋駭日靈，調露鏗鈜动天駟。","奔塵飞箭若麟螭，躡景追风忽见知。","咀銜拉鐵並權奇，被服雕章何陸離。","紫玉鳴珂臨寶鐙，青絲綵絡带金羈。","隨歌鼓而電驚，逐丸劒而飆驰。","態聚𨄳還急，驕凝驟不移。","光敵白日下，氣擁綠煙垂。","婉轉盤跚殊未已，懸空步驟紅塵起。","驚鳧翔鷺不堪儔，矯鳳迴鸾那足擬。","蘅垂桂褭香氛氳，长鳴汗血尽浮云。","不辞辛苦来东道，祗爲簫韶朝夕闻。","閶闔间，玉台側，承恩煦兮生光色。","鸾鏘鏘，车翼翼，備国容兮爲戎飾。","充云翹兮天子庭，荷日用兮情無極。","吉良乘兮一千歲，神是得兮天地期。","大易占云南山壽，䟃𧽼共乐聖明时。"]', '诗', 'shi', '', NULL, '舞馬篇 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f22d13-9972-49eb-9895-f5282431c96c', '正夜侍宴應詔', '正夜侍宴應詔', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["重關鐘漏通，夕敞鳳皇宮。","雙闕祥煙裏，千門明月中。","酒杯浮湛露，歌曲唱風流。","侍臣咸醉止，恆慙恩遇崇。"]', '["重关鐘漏通，夕敞鳳皇宮。","雙闕祥煙裏，千门明月中。","酒杯浮湛露，歌曲唱风流。","侍臣咸醉止，恆慙恩遇崇。"]', '诗', 'shi', '', NULL, '正夜侍宴應詔 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('699f7536-1aab-43d2-bdef-4dc1658197be', '送道士入天台', '送道士入天台', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["洛陽陌上多離別，蓬萊山下足波潮。","碧海桑田何處在？笙歌一聽一遙遙。"]', '["洛陽陌上多離別，蓬萊山下足波潮。","碧海桑田何处在？笙歌一听一遙遙。"]', '诗', 'shi', '', NULL, '送道士入天台 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1565b0d-731a-459c-ad6e-b88afffb7832', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '092008d9-de65-47c7-9f90-6b90e95ab9a2', '唐', '["山中別有神仙地，屈曲幽深碧澗垂。","巖前暫駐黃金輦，席上還飛白玉巵。","遠近風泉俱合雜，高低雲石共參差。","林壑偏能留睿賞，長天莫遽下丹曦。"]', '["山中別有神仙地，屈曲幽深碧澗垂。","巖前暫駐黄金輦，席上還飞白玉巵。","远近风泉俱合杂，高低云石共參差。","林壑偏能留睿賞，长天莫遽下丹曦。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 楊敬述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a98c2e-ca0d-4d77-82f6-2c10adc4aeae', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["九旗雲布臨嵩室，萬騎星陳集潁川。","瑞液含滋登禹膳，飛流薦響入虞弦。","山扉野徑朝花積，帳殿帷宮夏葉連。","微臣獻壽迎千壽，願奉堯年倚萬年。"]', '["九旗云布臨嵩室，万騎星陳集潁川。","瑞液含滋登禹膳，飞流薦响入虞弦。","山扉野徑朝花積，帳殿帷宮夏葉連。","微臣獻壽迎千壽，願奉堯年倚万年。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d795435-6662-4bc1-ad09-a94080bfe33a', '詠雲', '詠云', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["瑞雲千里映，祥輝四望新。","隨風亂鳥翅，汎水結魚鱗。","布葉疑臨夏，開花詎待春。","願得承嘉景，無令掩桂輪。"]', '["瑞云千里映，祥輝四望新。","隨风亂鸟翅，汎水結鱼鱗。","布葉疑臨夏，开花詎待春。","願得承嘉景，無令掩桂輪。"]', '诗', 'shi', '', NULL, '詠雲 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c3b82b5-0a24-441f-8add-e5c75179794d', '詠螢', '詠螢', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["卉草誠幽賤，枯朽絕因依。","忽逢借羽翼，不覺生光輝。","直念恩華重，長嗟報効微。","方思助日月，爲許願曾飛。"]', '["卉草誠幽賤，枯朽絕因依。","忽逢借羽翼，不覺生光輝。","直念恩华重，长嗟報効微。","方思助日月，爲許願曾飞。"]', '诗', 'shi', '', NULL, '詠螢 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d4703aa-4250-441a-9ee5-2cc12fb24172', '早春洛陽荅杜審言', '早春洛陽荅杜審言', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["梓澤年光往復來，杜霸遊人去不迴。","若非載筆登麟閣，定是吹簫伴鳳臺。","路傍桃李花猶嫩，波上芙蕖葉未開。","分明寄語長安道，莫教留滯洛陽才。"]', '["梓澤年光往复来，杜霸游人去不迴。","若非載笔登麟閣，定是吹簫伴鳳台。","路傍桃李花猶嫩，波上芙蕖葉未开。","分明寄語长安道，莫教留滯洛陽才。"]', '诗', 'shi', '', NULL, '早春洛陽荅杜審言 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8abe5f3-34ae-4547-a239-bb4702616074', '詠項羽', '詠項羽', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["北伐雖全趙，東歸不王秦。","空歌拔山力，羞作渡江人。"]', '["北伐雖全趙，东归不王秦。","空歌拔山力，羞作渡江人。"]', '诗', 'shi', '', NULL, '詠項羽 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cac9992-e0ef-4f2b-80c5-f0324df74d74', '詠漢高祖', '詠漢高祖', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["百戰方夷項，三章且代秦。","功歸蕭相國，氣盡戚夫人。"]', '["百戰方夷項，三章且代秦。","功归蕭相国，氣尽戚夫人。"]', '诗', 'shi', '', NULL, '詠漢高祖 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cab8d79-a3be-4aed-bb77-f95c280982fc', '南行別弟', '南行別弟', '96732339-216a-4c10-baaf-ecaacbb30df0', '唐', '["萬里人南去，三春雁北飛。","不知何歲月？得與爾同歸。"]', '["万里人南去，三春雁北飞。","不知何歲月？得與爾同归。"]', '诗', 'shi', '', NULL, '南行別弟 于季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6cccf1-5d2e-451f-830f-33327a652461', '長信宮中樹', '长信宮中樹', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["婀娜當軒樹，䒠茸倚蘭殿。","葉豔九春華，香搖五明扇。","餘花鳥弄盡，新葉蟲書徧。","零落心自知，芳菲君不見。"]', '["婀娜當軒樹，䒠茸倚蘭殿。","葉豔九春华，香搖五明扇。","餘花鸟弄尽，新葉蟲书徧。","零落心自知，芳菲君不见。"]', '诗', 'shi', '', NULL, '長信宮中樹 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e93af1d-9385-458d-809d-8589ac15ae3e', '下山逢故夫', '下山逢故夫', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["妾身本薄命，輕棄城南隅。","庭前厭芍藥，山上采蘼蕪。","春風罥紈袖，零露濕羅襦。","羞將憔悴日，提籠逢故夫。"]', '["妾身本薄命，轻棄城南隅。","庭前厭芍藥，山上采蘼蕪。","春风罥紈袖，零露濕羅襦。","羞將憔悴日，提籠逢故夫。"]', '诗', 'shi', '', NULL, '下山逢故夫 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be65f9a4-d8ad-4161-ae02-fb8d6eeaea69', '巫山高', '巫山高', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["巫山十二峰，參差互隱見。","潯陽幾千里，周覽忽已徧。","想像神女姿，摘芳共珍薦。","楚雲何逶迤，紅樹日葱蒨。","楚雲沒湘源，紅樹斷荆門。","郢路不可見，況復夜聞猨。"]', '["巫山十二峰，參差互隐见。","潯陽幾千里，周覽忽已徧。","想像神女姿，摘芳共珍薦。","楚云何逶迤，紅樹日葱蒨。","楚云沒湘源，紅樹斷荆门。","郢路不可见，況复夜闻猨。"]', '诗', 'shi', '', NULL, '巫山高 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e40b25-da95-4352-84a4-142e54f65062', '棄妾篇', '棄妾篇', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["妾本叢臺右，君在鴈門陲。","悠悠淇水曲，綵燕入桑枝。","不因媒結好，本以容相知。","容謝君應去，情移會有離。","還君結縷帶，歸妾識成詩。","此物雖輕賤，不用使人嗤。"]', '["妾本叢台右，君在鴈门陲。","悠悠淇水曲，綵燕入桑枝。","不因媒結好，本以容相知。","容謝君應去，情移會有離。","還君結縷带，归妾識成诗。","此物雖轻賤，不用使人嗤。"]', '诗', 'shi', '', NULL, '棄妾篇 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625e49c0-43ec-4636-91f1-03eb749ad9d6', '苦寒行', '苦寒行', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["胡天夜清迥，孤雲獨飄颺。","遙裔出鴈關，逶迤含晶光。","陰陵久裴回，幽都無多陽。","初寒凍巨海，殺氣流大荒。","朔馬飲寒冰，行子履胡霜。","路有從役倦，臥死黃沙場。","羈旅因相依，慟之淚霑裳。","由來從軍行，賞存不賞亡。","亡者誠已矣，徒令存者傷。"]', '["胡天夜清迥，孤云独飄颺。","遙裔出鴈关，逶迤含晶光。","陰陵久裴回，幽都無多陽。","初寒凍巨海，殺氣流大荒。","朔马饮寒冰，行子履胡霜。","路有從役倦，臥死黄沙場。","羈旅因相依，慟之泪霑裳。","由来從軍行，賞存不賞亡。","亡者誠已矣，徒令存者傷。"]', '诗', 'shi', '', NULL, '苦寒行 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c9d22c-64a8-4cc6-a4a2-e89a2cad02cf', '從軍行', '從軍行', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["南庭結白露，北風掃黃葉。","此時鴻鴈來，驚鳴催思妾。","曲房理針線，平砧擣文練。","鴛綺裁易成，龍鄉信難見。","窈窕九重閨，寂寞十年啼。","紗窗白雲宿，羅幌月光棲。","雲月隱微微，夜上流黃機。","玉霜凍珠履，金吹薄羅衣。","漢家已得地，君去將何事。","宛轉結蠶書，寂寥無鴈使。","生平荷恩信，本爲榮華進。","況復落紅顏，蟬聲催綠鬢。"]', '["南庭結白露，北风掃黄葉。","此时鴻鴈来，驚鳴催思妾。","曲房理針線，平砧擣文練。","鴛綺裁易成，龙乡信难见。","窈窕九重閨，寂寞十年啼。","紗窗白云宿，羅幌月光棲。","云月隐微微，夜上流黄機。","玉霜凍珠履，金吹薄羅衣。","漢家已得地，君去將何事。","宛轉結蠶书，寂寥無鴈使。","生平荷恩信，本爲榮华進。","況复落紅顏，蟬声催綠鬢。"]', '诗', 'shi', '', NULL, '從軍行 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340d98e9-d8ec-4e7d-9a23-cce3bc41ee92', '擬古贈陳子昂', '擬古贈陳子昂', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["惸惸孤形影，悄悄獨遊心。","以此從王事，常與子同衾。","別離三河間，征戰二庭深。","胡天夜雨霜，胡鴈晨南翔。","節物感離居，同衾違故鄉。","南歸日將遠，北方尚蓬飄。","孟秋七月時，相送出外郊。","海風吹涼木，邊聲響梢梢。","勤役千萬里，將臨五十年。","心事爲誰道，抽琴歌坐筵。","一彈再三歎，賓御淚潺湲。","送君竟此曲，從茲長絕弦。"]', '["惸惸孤形影，悄悄独游心。","以此從王事，常與子同衾。","別離三河间，征戰二庭深。","胡天夜雨霜，胡鴈晨南翔。","節物感離居，同衾違故乡。","南归日將远，北方尚蓬飄。","孟秋七月时，相送出外郊。","海风吹涼木，邊声响梢梢。","勤役千万里，將臨五十年。","心事爲誰道，抽琴歌坐筵。","一彈再三歎，賓御泪潺湲。","送君竟此曲，從茲长絕弦。"]', '诗', 'shi', '', NULL, '擬古贈陳子昂 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec4bfedf-b0a4-4958-9ba9-6c5dc25a3add', '定情篇', '定情篇', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["共君結新婚，歲寒心未卜。","相與遊春園，各隨情所逐。","君愛菖蒲花，妾感苦寒竹。","菖花多豔姿，寒竹有貞葉。","此時妾比君，君心不如妾。","簪玉步河堤，妖韶援綠荑。","鳧鴈將子遊，鶯燕從雙栖。","君念春光好，妾向春光啼。","君時不得意，棄妾還金閨。","結言本同心，悲歡何未齊。","怨咽前致辭，願得申所悲。","人間丈夫易，世路婦難爲。","始如經天月，終若流星馳。","天月相終始，流星無定期。","長信佳麗人，失意非蛾眉。","廬江小吏婦，非關織作遲。","本願長相對，今已長相思。","復有遊宦子，結援從梁陳。","燕居崇三朝，去來歷九春。","誓心妾終始，蠶桑奉所親。","歸願未克從，黃金贈路人。","潔婦懷明義，從泛河之津。","于今千萬年，誰當問水濱。","更憶娼家樓，夫婿事封侯。","去時恩灼灼，去罷心悠悠。","不憐妾歲[晏]，十載隴西頭。","以茲常惕惕，百慮恆盈積。","由來共結褵，幾人同匪石。","故歲雕梁燕，雙去今來隻。","今日玉庭梅，朝紅暮成碧。","碧榮始芬敷，黃葉已淅瀝。","何用念芳春，芳春有流易。","何用重歡娛，歡娛俄戚戚。","家本巫山陽，歸去路何長。","敘言情未盡，採菉已盈筐。","桑榆日及景，物色盈高岡。","下有碧流水，上有丹桂香。","桂花不須折，碧流清且潔。","贈君比芳菲，愛惠常不歇。","贈君比潺湲，相思無斷絕。","妾有秦家鏡，寶匣裝珠璣。","鑑來年二八，不記易陰暉。","妾無光寂寂，委照影依依。","今日持爲贈，相識莫相違。"]', '["共君結新婚，歲寒心未卜。","相與游春园，各隨情所逐。","君愛菖蒲花，妾感苦寒竹。","菖花多豔姿，寒竹有貞葉。","此时妾比君，君心不如妾。","簪玉步河堤，妖韶援綠荑。","鳧鴈將子游，鶯燕從雙栖。","君念春光好，妾向春光啼。","君时不得意，棄妾還金閨。","結言本同心，悲歡何未齊。","怨咽前致辞，願得申所悲。","人间丈夫易，世路婦难爲。","始如經天月，終若流星驰。","天月相終始，流星無定期。","长信佳丽人，失意非蛾眉。","廬江小吏婦，非关织作遲。","本願长相对，今已长相思。","复有游宦子，結援從梁陳。","燕居崇三朝，去来歷九春。","誓心妾終始，蠶桑奉所親。","归願未克從，黄金贈路人。","潔婦懷明義，從泛河之津。","于今千万年，誰當问水濱。","更憶娼家楼，夫婿事封侯。","去时恩灼灼，去罷心悠悠。","不怜妾歲[晏]，十載隴西头。","以茲常惕惕，百慮恆盈積。","由来共結褵，幾人同匪石。","故歲雕梁燕，雙去今来隻。","今日玉庭梅，朝紅暮成碧。","碧榮始芬敷，黄葉已淅瀝。","何用念芳春，芳春有流易。","何用重歡娛，歡娛俄戚戚。","家本巫山陽，归去路何长。","敘言情未尽，採菉已盈筐。","桑榆日及景，物色盈高岡。","下有碧流水，上有丹桂香。","桂花不須折，碧流清且潔。","贈君比芳菲，愛惠常不歇。","贈君比潺湲，相思無斷絕。","妾有秦家镜，寶匣裝珠璣。","鑑来年二八，不記易陰暉。","妾無光寂寂，委照影依依。","今日持爲贈，相識莫相違。"]', '诗', 'shi', '', NULL, '定情篇 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2005e3a-aac5-4459-8045-8b7e770f34f1', '綠珠篇', '綠珠篇', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["石家金谷重新聲，明珠十斛買娉婷。","此日可憐君自許，此時可喜得人情。","君家閨閣不曾難，常將歌舞借人看。","意氣雄豪非分理，驕矜勢力橫相干。","辭君去君終不忍，徒勞掩袂傷鉛粉。","百年離別在高樓，一旦紅顏爲君盡。"]', '["石家金谷重新声，明珠十斛買娉婷。","此日可怜君自許，此时可喜得人情。","君家閨閣不曾难，常將歌舞借人看。","意氣雄豪非分理，驕矜勢力橫相干。","辞君去君終不忍，徒勞掩袂傷鉛粉。","百年離別在高楼，一旦紅顏爲君尽。"]', '诗', 'shi', '', NULL, '綠珠篇 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b622f0d-7563-4e59-9b01-cc69147ac4e2', '和李侍郎古意', '和李侍郎古意', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["妾家巫山隔漢川，君度南庭向胡苑。","高樓迢遰想金天，河漢昭回更愴然。","夜如何其夜未央，閑花照月愁洞房。","自矜夫婿勝王昌，三十曾作侍中郎。","一從流落戍漁陽，懷哉萬恨結中腸。","南山冪冪兔絲花，北陵青青女蘿樹。","由來花葉同一根，今日枝條分兩處。","三星差池光照灼，北斗西指秋雲薄。","莖枯花謝枝憔悴，香銷色盡花零落。","美人長歎豔容萎，含情收取摧折枝。","調絲獨彈聲未移，感君行坐星歲遲。","閨中宛轉今若斯，誰能爲報征人知。"]', '["妾家巫山隔漢川，君度南庭向胡苑。","高楼迢遰想金天，河漢昭回更愴然。","夜如何其夜未央，闲花照月愁洞房。","自矜夫婿勝王昌，三十曾作侍中郎。","一從流落戍漁陽，懷哉万恨結中腸。","南山冪冪兔絲花，北陵青青女蘿樹。","由来花葉同一根，今日枝條分兩处。","三星差池光照灼，北斗西指秋云薄。","莖枯花謝枝憔悴，香銷色尽花零落。","美人长歎豔容萎，含情收取摧折枝。","調絲独彈声未移，感君行坐星歲遲。","閨中宛轉今若斯，誰能爲報征人知。"]', '诗', 'shi', '', NULL, '和李侍郎古意 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c5c4ae-6682-48d7-8a67-bf15e0181c90', '倡女行', '倡女行', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["石榴酒，葡萄漿，蘭桂芳，茱萸香。","願君駐金鞍，暫此共年芳。","願君解羅襦，一醉同匡牀。","文君正新寡，結念在歌倡。","昨宵綺帳迎韓壽，今朝羅袖引潘郎。","莫吹羌笛驚鄰里，不用琵琶喧洞房。","且歌新夜曲，莫弄楚明光。","此曲怨且豔，哀音斷人腸。"]', '["石榴酒，葡萄漿，蘭桂芳，茱萸香。","願君駐金鞍，暫此共年芳。","願君解羅襦，一醉同匡牀。","文君正新寡，結念在歌倡。","昨宵綺帳迎韓壽，今朝羅袖引潘郎。","莫吹羌笛驚鄰里，不用琵琶喧洞房。","且歌新夜曲，莫弄楚明光。","此曲怨且豔，哀音斷人腸。"]', '诗', 'shi', '', NULL, '倡女行 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd5ac002-dc5f-491d-b8b1-c4e6fd09d31a', '羸駿篇', '羸駿篇', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["噴玉長鳴西北來，自言當代是龍媒。","萬里鐵關行入貢，九重金闕爲君開。","蹀躞朝馳過上苑，䟃𧽼暝走發章臺。","玉勒金鞍荷裝飾，路傍觀者無窮極。","小山桂樹比權奇，上林桃花況顏色。","忽聞天將出龍沙，漢主持將駕鼓車。","去去山川勞日夜，遙遙關塞斷煙霞。","山川關塞十年征，汗血流離赴月營。","肌膚銷遠道，膂力盡長城。","長城日夕苦風霜，中有連年百戰場。","搖珂嚙勒金羈盡，爭鋒足頓鐵菱傷。","垂耳罷輕齎，棄置在寒谿。","大宛蒲海北，滇壑雋崖西。","沙平留緩步，路遠闇頻嘶。","從來力盡君須棄，何必尋途我已迷。","歲歲年年奔遠道，朝朝暮暮催疲老。","扣冰晨飲黃河源，拂雪夜食天山草。","楚水澶谿征戰事，吳塞烏江辛苦地。","持來報主不辭勞，宿昔立功非重利。","丹心素節本無求，長鳴向君君不留。","祗應澶漫歸田里，萬里低昂任生死。","君王倘若不見遺，白骨黃金猶可市。"]', '["噴玉长鳴西北来，自言當代是龙媒。","万里鐵关行入貢，九重金闕爲君开。","蹀躞朝驰過上苑，䟃𧽼暝走發章台。","玉勒金鞍荷裝飾，路傍观者無窮極。","小山桂樹比權奇，上林桃花況顏色。","忽闻天將出龙沙，漢主持將駕鼓车。","去去山川勞日夜，遙遙关塞斷煙霞。","山川关塞十年征，汗血流離赴月營。","肌膚銷远道，膂力尽长城。","长城日夕苦风霜，中有連年百戰場。","搖珂嚙勒金羈尽，爭鋒足頓鐵菱傷。","垂耳罷轻齎，棄置在寒谿。","大宛蒲海北，滇壑雋崖西。","沙平留緩步，路远闇頻嘶。","從来力尽君須棄，何必尋途我已迷。","歲歲年年奔远道，朝朝暮暮催疲老。","扣冰晨饮黄河源，拂雪夜食天山草。","楚水澶谿征戰事，吳塞烏江辛苦地。","持来報主不辞勞，宿昔立功非重利。","丹心素節本無求，长鳴向君君不留。","祗應澶漫归田里，万里低昂任生死。","君王倘若不见遺，白骨黄金猶可市。"]', '诗', 'shi', '', NULL, '羸駿篇 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbf9c280-2c3d-458f-b189-8019915f597f', '銅雀妓', '銅雀妓', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["金閣惜分香，鉛華不重妝。","空餘歌舞地，猶是爲君王。","哀弦調已絕，豔曲不須長。","共看西陵暮，秋煙起白楊。"]', '["金閣惜分香，鉛华不重妝。","空餘歌舞地，猶是爲君王。","哀弦調已絕，豔曲不須长。","共看西陵暮，秋煙起白楊。"]', '诗', 'shi', '', NULL, '銅雀妓 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa46acf-2a22-4559-868f-9f31d7259563', '侍宴應制得分字', '侍宴應制得分字', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["紫禁肅晴氛，朱樓落曉雲。","豫遊龍駕轉，天樂鳳簫聞。","竹外仙亭出，花間輦路分。","微臣一何幸，詞賦奉明君。"]', '["紫禁肅晴氛，朱楼落晓云。","豫游龙駕轉，天乐鳳簫闻。","竹外仙亭出，花间輦路分。","微臣一何幸，词賦奉明君。"]', '诗', 'shi', '', NULL, '侍宴應制得分字 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6e99ce-4cfd-4740-a2cf-de2717d46c6a', '梨園亭子侍宴', '梨园亭子侍宴', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["年光陌上發，香輦禁中遊。","草綠鴛鴦殿，花紅翡翠樓。","天杯承露酌，仙管雜風流。","今日陪歡豫，皇恩不可酬。"]', '["年光陌上發，香輦禁中游。","草綠鴛鴦殿，花紅翡翠楼。","天杯承露酌，仙管杂风流。","今日陪歡豫，皇恩不可酬。"]', '诗', 'shi', '', NULL, '梨園亭子侍宴 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77828789-8bb8-4b4c-b6b0-4bc3db6e4bc6', '和蘇員外寓直', '和蘇員外寓直', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["自昔重爲郎，伊人練國章。","三旬登建禮，五夜直明光。","墨草尚書奏，衣飄侍御香。","開軒竹氣靜，拂簟蕙風涼。","曉漏離閶闔，鳴鐘出未央。","從來宿臺上，天子貴文強。"]', '["自昔重爲郎，伊人練国章。","三旬登建禮，五夜直明光。","墨草尚书奏，衣飄侍御香。","开軒竹氣静，拂簟蕙风涼。","晓漏離閶闔，鳴鐘出未央。","從来宿台上，天子貴文強。"]', '诗', 'shi', '', NULL, '和蘇員外寓直 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b740c39-e58f-4831-b5da-29be6fb4d1ab', '哭故人', '哭故人', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["生死久離居，悽涼歷舊廬。","歎茲三徑斷，不踐十年餘。","古木巢禽合，荒庭愛客疎。","匣留彈罷劒，牀積讀殘書。","玉沒終無像，蘭言強問虛。","平生不得意，泉路復何如。"]', '["生死久離居，悽涼歷旧廬。","歎茲三徑斷，不踐十年餘。","古木巢禽合，荒庭愛客疎。","匣留彈罷劒，牀積读殘书。","玉沒終無像，蘭言強问虛。","平生不得意，泉路复何如。"]', '诗', 'shi', '', NULL, '哭故人 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192b781a-ddfa-42f7-bda0-de181dc59d39', '折楊柳', '折楊柳', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["可憐濯濯春楊柳，攀折將來就纖手。","妾容與此同盛衰，何必君恩能獨久。"]', '["可怜濯濯春楊柳，攀折將来就纖手。","妾容與此同盛衰，何必君恩能独久。"]', '诗', 'shi', '', NULL, '折楊柳 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40574096-1599-41ea-8388-00ffbd043b00', '人日登高', '人日登高', '3ff293d7-4b80-4419-8cc8-d4e1cc05268c', '唐', '["僕本多悲者，年來不悟春。","登高一遊目，始覺柳條新。","杜陵猶識漢，桃源不辨秦。","蹔若升雲霧，還似出囂塵。","賴得煙霞氣，淹留攀桂人。"]', '["僕本多悲者，年来不悟春。","登高一游目，始覺柳條新。","杜陵猶識漢，桃源不辨秦。","蹔若升云霧，還似出囂塵。","賴得煙霞氣，淹留攀桂人。"]', '诗', 'shi', '', NULL, '人日登高 喬侃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe00ac4c-7b96-4129-800a-28952ad69f65', '出塞', '出塞', '7902da67-399b-4060-aac6-d860d7122958', '唐', '["沙場三萬里，猛將五千兵。","旌斷冰谿戍，笳吹鐵關城。","陰雲暮下雪，寒日晝無晶。","直爲懷恩苦，誰知邊塞情。"]', '["沙場三万里，猛將五千兵。","旌斷冰谿戍，笳吹鐵关城。","陰云暮下雪，寒日晝無晶。","直爲懷恩苦，誰知邊塞情。"]', '诗', 'shi', '', NULL, '出塞 喬備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6403a5d8-e1fd-48e8-9ee7-375b162dc62c', '長門怨', '长门怨', '7902da67-399b-4060-aac6-d860d7122958', '唐', '["秋入長門殿，木落洞房虛。","妾思宵徒靜，君恩日更疎。","墜露清金閣，流螢點玉除。","還將閨裏恨，遙問馬相如。"]', '["秋入长门殿，木落洞房虛。","妾思宵徒静，君恩日更疎。","墜露清金閣，流螢点玉除。","還將閨裏恨，遙问马相如。"]', '诗', 'shi', '', NULL, '長門怨 喬備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a99df2-5e23-45d7-a9c6-283277760654', '將軍行', '將軍行', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["將軍闢轅門，耿介當風立。","諸將欲言事，逡巡不敢入。","劒氣射雲天，鼓聲振原隰。","黃塵塞路起，走馬追兵急。","彎弓從此去，飛箭如雨集。","截圍一百里，斬首五千級。","代馬流血死，胡人抱鞍泣。","古來養甲兵，有事常討襲。","乘我廟堂運，坐使干戈戢。","獻凱歸京師，軍容何翕習。"]', '["將軍闢轅门，耿介當风立。","諸將欲言事，逡巡不敢入。","劒氣射云天，鼓声振原隰。","黄塵塞路起，走马追兵急。","彎弓從此去，飞箭如雨集。","截圍一百里，斬首五千級。","代马流血死，胡人抱鞍泣。","古来養甲兵，有事常討襲。","乘我廟堂運，坐使干戈戢。","獻凱归京師，軍容何翕習。"]', '诗', 'shi', '', NULL, '將軍行 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72f7516-3859-484d-9984-bab0438b736e', '從軍行', '從軍行', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["秋天風颯颯，羣胡馬行疾。","嚴城晝不開，伏兵暗相失。","天子廟堂拜，將軍凶門出。","紛紛伊洛道，戎馬幾萬匹。","軍門壓黃河，兵氣衝白日。","平生懷仗劒，慷慨即投筆。","南登漢月孤，北走代雲密。","近取韓彭計，早知孫吳術。","丈夫清萬里，誰能掃一室。"]', '["秋天风颯颯，羣胡马行疾。","嚴城晝不开，伏兵暗相失。","天子廟堂拜，將軍凶门出。","紛紛伊洛道，戎马幾万匹。","軍门壓黄河，兵氣衝白日。","平生懷仗劒，慷慨即投笔。","南登漢月孤，北走代云密。","近取韓彭計，早知孫吳術。","丈夫清万里，誰能掃一室。"]', '诗', 'shi', '', NULL, '從軍行 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5d84f0-cb26-4687-b1c9-c708e7dae9d8', '春女行', '春女行', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["春女顏如玉，怨歌陽春曲。","巫山春樹紅，沅湘春草綠。","自憐妖豔姿，妝成獨見時。","愁心伴楊柳，春盡亂如絲。","目極千餘里，悠悠春江水。","頻想玉關人，愁臥金閨裏。","尚言春花落，不知秋風起。","嬌愛猶未終，悲涼從此始。","憶昔楚王宮，玉樓粧粉紅。","纖腰弄明月，長袖舞春風。","容華委西山，光陰不可還。","桑林變東海，富貴今何在？","寄言桃李容，胡爲閨閤重。","但看楚王墓，唯有數株松。"]', '["春女顏如玉，怨歌陽春曲。","巫山春樹紅，沅湘春草綠。","自怜妖豔姿，妝成独见时。","愁心伴楊柳，春尽亂如絲。","目極千餘里，悠悠春江水。","頻想玉关人，愁臥金閨裏。","尚言春花落，不知秋风起。","嬌愛猶未終，悲涼從此始。","憶昔楚王宮，玉楼粧粉紅。","纖腰弄明月，长袖舞春风。","容华委西山，光陰不可還。","桑林变东海，富貴今何在？","寄言桃李容，胡爲閨閤重。","但看楚王墓，唯有數株松。"]', '诗', 'shi', '', NULL, '春女行 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2adcb31-928f-4481-8207-fada8940a00f', '孤松篇', '孤松篇', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["蠶月桑葉青，鸎時柳花白。","澹豔煙雨姿，敷芬陽春陌。","如何秋風起，零落從此始。","獨有南澗松，不歎東流水。","玄陰天地冥，皓雪朝夜零。","豈不罹寒暑，爲君留青青。","青青好顏色，落落任孤直。","羣樹遙相望，衆草不敢逼。","靈龜卜真隱，仙鳥宜棲息。","恥受秦帝封，願言唐侯食。","寒山夜月明，山冷氣清清。","淒兮歸鳳集，吹之作琴聲。","松子臥仙岑，寂聽疑野心。","清泠有真曲，樵採無知音。","美人何時來？幽徑委綠苔。","吁嗟深澗底，棄捐廣廈材。"]', '["蠶月桑葉青，鸎时柳花白。","澹豔煙雨姿，敷芬陽春陌。","如何秋风起，零落從此始。","独有南澗松，不歎东流水。","玄陰天地冥，皓雪朝夜零。","豈不罹寒暑，爲君留青青。","青青好顏色，落落任孤直。","羣樹遙相望，衆草不敢逼。","靈龟卜真隐，仙鸟宜棲息。","恥受秦帝封，願言唐侯食。","寒山夜月明，山冷氣清清。","淒兮归鳳集，吹之作琴声。","松子臥仙岑，寂听疑野心。","清泠有真曲，樵採無知音。","美人何时来？幽徑委綠苔。","吁嗟深澗底，棄捐廣廈材。"]', '诗', 'shi', '', NULL, '孤松篇 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd58a01b-8e6f-435a-a7a8-3843c83e0ece', '嵩嶽聞笙', '嵩嶽闻笙', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["月出嵩山東，月明山益空。","山人愛清景，散髪臥秋風。","風止夜何清，獨夜草蟲鳴。","仙人不可見，乘月近吹笙。","絳脣吸靈氣，玉指調真聲。","真聲是何曲，三山鸞鶴情。","昔去落塵俗，願言聞此曲。","今來臥嵩岑，何幸承幽音。","神仙樂吾事，笙歌銘夙心。"]', '["月出嵩山东，月明山益空。","山人愛清景，散髪臥秋风。","风止夜何清，独夜草蟲鳴。","仙人不可见，乘月近吹笙。","絳脣吸靈氣，玉指調真声。","真声是何曲，三山鸾鹤情。","昔去落塵俗，願言闻此曲。","今来臥嵩岑，何幸承幽音。","神仙乐吾事，笙歌銘夙心。"]', '诗', 'shi', '', NULL, '嵩嶽聞笙 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128b7cf2-1333-4e85-bd06-cd9b2f472aab', '秋日題汝陽潭壁', '秋日題汝陽潭壁', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["獨坐秋陰生，悲來從所適。","行見汝陽潭，飛蘿蒙水石。","懸瓢木葉上，風吹何歷歷。","幽人不耐煩，振衣步閑寂。","迴流清見底，金沙覆銀礫。","錯落非一文，空朧幾千尺。","魚鱗可憐紫，鴨毛自然碧。","吟詠秋水篇，渺然忘損益。","秋水隨形影，清濁混心迹。","歲暮歸去來，東山余宿昔。"]', '["独坐秋陰生，悲来從所適。","行见汝陽潭，飞蘿蒙水石。","懸瓢木葉上，风吹何歷歷。","幽人不耐煩，振衣步闲寂。","迴流清见底，金沙覆銀礫。","錯落非一文，空朧幾千尺。","鱼鱗可怜紫，鴨毛自然碧。","吟詠秋水篇，渺然忘損益。","秋水隨形影，清濁混心迹。","歲暮归去来，东山余宿昔。"]', '诗', 'shi', '', NULL, '秋日題汝陽潭壁 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e61f13a4-8f37-4c7d-b4d6-693001f9925b', '采桑', '采桑', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["楊柳送行人，青青西入秦。","誰家采桑女，樓上不勝春。","盈盈灞水曲，步步春芳綠。","紅臉耀明珠，絳脣含白玉。","回首渭橋東，遙憐春色同。","青絲嬌落日，緗綺弄春風。","攜籠長歎息，逶遲戀春色。","看花若有情，倚樹疑無力。","薄暮思悠悠，使君南陌頭。","相逢不相識，歸去夢青樓。"]', '["楊柳送行人，青青西入秦。","誰家采桑女，楼上不勝春。","盈盈灞水曲，步步春芳綠。","紅臉耀明珠，絳脣含白玉。","回首渭橋东，遙怜春色同。","青絲嬌落日，緗綺弄春风。","携籠长歎息，逶遲戀春色。","看花若有情，倚樹疑無力。","薄暮思悠悠，使君南陌头。","相逢不相識，归去梦青楼。"]', '诗', 'shi', '', NULL, '采桑 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973f20b5-ae5e-406a-b4e8-2c3ba92ed895', '謁漢世祖廟', '謁漢世祖廟', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["舂陵氣初發，漸臺首未傳。","列營百萬衆，持國十八年。","運開朱旗後，道合赤符先。","宛城劒鳴匣，昆陽鏑應弦。","獷獸血塗地，巨人聲沸天。","長驅過北趙，短兵出南燕。","太守迎門外，王郎死道邊。","昇壇九城陌，端拱千秋年。","朝廷方雀躍，劒珮幾聯翩。","至德刑四海，神儀翳九泉。","宗子行舊邑，恭聞清廟篇。","君容穆而聖，臣像儼猶賢。","攢木承危柱，疎蘿挂朽椽。","祠庭巢鳥啄，祭器網蟲緣。","懷古江山在，惟新曆數遷。","空餘今夜月，長似舊時懸。"]', '["舂陵氣初發，漸台首未傳。","列營百万衆，持国十八年。","運开朱旗後，道合赤符先。","宛城劒鳴匣，昆陽鏑應弦。","獷獸血塗地，巨人声沸天。","长驱過北趙，短兵出南燕。","太守迎门外，王郎死道邊。","昇壇九城陌，端拱千秋年。","朝廷方雀躍，劒珮幾聯翩。","至德刑四海，神儀翳九泉。","宗子行旧邑，恭闻清廟篇。","君容穆而聖，臣像儼猶賢。","攢木承危柱，疎蘿挂朽椽。","祠庭巢鸟啄，祭器網蟲緣。","懷古江山在，惟新曆數遷。","空餘今夜月，长似旧时懸。"]', '诗', 'shi', '', NULL, '謁漢世祖廟 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16d007eb-e119-499d-aa10-77c6524727ec', '巫山懷古', '巫山懷古', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["巫山幽陰地，神女豔陽年。","襄王伺容色，落日望悠然。","歸來高唐夜，金釭燄青煙。","頹想臥瑤席，夢魂何翩翩。","搖落殊未已，榮華倏徂遷。","愁思瀟湘浦，悲涼雲夢田。","猿啼秋風夜，鴈飛明月天。","巴歌不可聽，聽此益潺湲。"]', '["巫山幽陰地，神女豔陽年。","襄王伺容色，落日望悠然。","归来高唐夜，金釭燄青煙。","頹想臥瑤席，梦魂何翩翩。","搖落殊未已，榮华倏徂遷。","愁思瀟湘浦，悲涼云梦田。","猿啼秋风夜，鴈飞明月天。","巴歌不可听，听此益潺湲。"]', '诗', 'shi', '', NULL, '巫山懷古 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ed2a27-6c6b-46d7-b41c-1df254a6e6f2', '歸山', '归山', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["歸去嵩山道，煙花覆青草。","草綠山無塵，山青楊柳春。","日暮松聲合，空歌思殺人。"]', '["归去嵩山道，煙花覆青草。","草綠山無塵，山青楊柳春。","日暮松声合，空歌思殺人。"]', '诗', 'shi', '', NULL, '歸山 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('865f621d-c2f6-48f3-a8ca-5a6dbb46c507', '代閨人春日', '代閨人春日', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["珠簾的曉光，玉顏豔春彩。","林間鳥鳴喚，戶外花相待。","花鳥惜芳菲，鳥鳴花亂飛。","人今伴花鳥，日暮不能歸。","池月憐歌扇，山雲愛舞衣。","佳期楊柳陌，攜手莫相違。"]', '["珠簾的晓光，玉顏豔春彩。","林间鸟鳴喚，戶外花相待。","花鸟惜芳菲，鸟鳴花亂飞。","人今伴花鸟，日暮不能归。","池月怜歌扇，山云愛舞衣。","佳期楊柳陌，携手莫相違。"]', '诗', 'shi', '', NULL, '代閨人春日 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5d15f2-8429-49ca-9708-e1b20ece4504', '蜀城懷古', '蜀城懷古', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["蜀土遶水竹，吳天積風霜。","窮覽通表裏，氣色何蒼蒼。","舊國有年代，青樓思豔妝。","古人無歲月，白骨冥丘荒。","寂歷彈琴地，幽流讀書堂。","玄龜埋卜室，彩鳳滅詞場。","陣圖一一在，栢樹雙雙行。","鬼神清漢廟，鳥雀參秦倉。","歎世已多感，懷心益自傷。","賴蒙靈丘境，時當明月光。"]', '["蜀土遶水竹，吳天積风霜。","窮覽通表裏，氣色何蒼蒼。","旧国有年代，青楼思豔妝。","古人無歲月，白骨冥丘荒。","寂歷彈琴地，幽流读书堂。","玄龟埋卜室，彩鳳滅词場。","陣圖一一在，栢樹雙雙行。","鬼神清漢廟，鸟雀參秦倉。","歎世已多感，懷心益自傷。","賴蒙靈丘境，时當明月光。"]', '诗', 'shi', '', NULL, '蜀城懷古 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232f945b-61d2-4c44-a382-efa15de48831', '洛川懷古', '洛川懷古', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["萋萋春草綠，悲歌牧征馬。","行見白頭翁，坐泣青竹下。","感歎前問之，贈予辛苦詞。","歲月移今古，山河更盛衰。","晉家都洛濱，朝廷多近臣。","詞賦歸潘岳，繁華稱季倫。","梓澤春草菲，河陽亂華飛。","綠珠不可奪，白首同所歸。","高樓倏冥滅，茂林久摧折。","昔時歌舞臺，今成狐兔穴。","人事互消亡，世路多悲傷。","北邙是吾宅，東嶽爲吾鄉。","君看北邙道，髑髏縈蔓草。","芳□□□□，□□□□□。","碑塋或半存，荆棘斂幽魂。","揮涕棄之去，不忍聞此言。"]', '["萋萋春草綠，悲歌牧征马。","行见白头翁，坐泣青竹下。","感歎前问之，贈予辛苦词。","歲月移今古，山河更盛衰。","晉家都洛濱，朝廷多近臣。","词賦归潘岳，繁华稱季倫。","梓澤春草菲，河陽亂华飞。","綠珠不可奪，白首同所归。","高楼倏冥滅，茂林久摧折。","昔时歌舞台，今成狐兔穴。","人事互消亡，世路多悲傷。","北邙是吾宅，东嶽爲吾乡。","君看北邙道，髑髏縈蔓草。","芳□□□□，□□□□□。","碑塋或半存，荆棘斂幽魂。","揮涕棄之去，不忍闻此言。"]', '诗', 'shi', '', NULL, '洛川懷古 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26340e1c-ac83-497e-910e-281647d85a2d', '春日行歌', '春日行歌', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["山樹落梅花，飛落野人家。","野人何所有，滿甕陽春酒。","攜酒上春臺，行歌伴落梅。","醉罷臥明月，乘夢遊天台。"]', '["山樹落梅花，飞落野人家。","野人何所有，满甕陽春酒。","携酒上春台，行歌伴落梅。","醉罷臥明月，乘梦游天台。"]', '诗', 'shi', '', NULL, '春日行歌 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48809356-a51f-40dd-bb2d-ce803947f2dc', '江南曲八首 一', '江南曲八首 一', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["暮宿南洲草，晨行北岸林。","日懸滄海闊，水隔洞庭深。","煙景無留意，風波有異潯。","歲遊難極目，春戲易爲心。","朝夕無榮遇，芳菲已滿襟。"]', '["暮宿南洲草，晨行北岸林。","日懸滄海闊，水隔洞庭深。","煙景無留意，风波有異潯。","歲游难極目，春戲易爲心。","朝夕無榮遇，芳菲已满襟。"]', '诗', 'shi', '', NULL, '江南曲八首 一 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb70e8de-52d5-4728-a097-63c50fbee3b8', '江南曲八首 二', '江南曲八首 二', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["豔唱潮初落，江花露未晞。","春洲驚翡翠，朱服弄芳菲。","畫舫煙中淺，青陽日際微。","錦帆衝浪濕，羅袖拂行衣。","含情罷所採，相歎惜流暉。"]', '["豔唱潮初落，江花露未晞。","春洲驚翡翠，朱服弄芳菲。","畫舫煙中淺，青陽日際微。","錦帆衝浪濕，羅袖拂行衣。","含情罷所採，相歎惜流暉。"]', '诗', 'shi', '', NULL, '江南曲八首 二 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e859bf-e12e-485d-a4e8-d0d560c5ec21', '江南曲八首 三', '江南曲八首 三', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["君爲隴西客，妾遇江南春。","朝遊含靈果，夕採弄風蘋。","果氣時不歇，蘋花日自新。","以此江南物，持贈隴西人。","空盈萬里懷，欲贈竟無因。"]', '["君爲隴西客，妾遇江南春。","朝游含靈果，夕採弄风蘋。","果氣时不歇，蘋花日自新。","以此江南物，持贈隴西人。","空盈万里懷，欲贈竟無因。"]', '诗', 'shi', '', NULL, '江南曲八首 三 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be9142f-2262-4efa-be9a-91d29ca77981', '江南曲八首 四', '江南曲八首 四', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["皓如楚江月，靄若吳岫雲。","波中自皎鏡，山上亦氤氳。","明月留照妾，輕雲持贈君。","山川各離散，光氣乃殊分。","天涯一爲別，江北不相聞。"]', '["皓如楚江月，靄若吳岫云。","波中自皎镜，山上亦氤氳。","明月留照妾，轻云持贈君。","山川各離散，光氣乃殊分。","天涯一爲別，江北不相闻。"]', '诗', 'shi', '', NULL, '江南曲八首 四 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bde1ef7-e93d-4dd5-bfbd-dc16c137b440', '江南曲八首 五', '江南曲八首 五', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["艤舟乘潮去，風帆振早涼。","潮平見楚甸，天際望維揚。","洄泝經千里，煙波接兩鄉。","雲明江嶼出，日照海流長。","此中逢歲[晏]，浦樹落花芳。"]', '["艤舟乘潮去，风帆振早涼。","潮平见楚甸，天際望維揚。","洄泝經千里，煙波接兩乡。","云明江嶼出，日照海流长。","此中逢歲[晏]，浦樹落花芳。"]', '诗', 'shi', '', NULL, '江南曲八首 五 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e1c53d-c15a-4a29-9a22-4a2e2859855d', '江南曲八首 六', '江南曲八首 六', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["暮春三月晴，維揚吳楚城。","城臨大江汜，回映洞浦清。","晴雲曲金閣，珠樓碧煙裏。","月明芳樹羣鳥飛，風過長林雜花起。","可憐離別誰家子，於此一至情何已。"]', '["暮春三月晴，維揚吳楚城。","城臨大江汜，回映洞浦清。","晴云曲金閣，珠楼碧煙裏。","月明芳樹羣鸟飞，风過长林杂花起。","可怜離別誰家子，於此一至情何已。"]', '诗', 'shi', '', NULL, '江南曲八首 六 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906bf983-de04-4551-b6dd-5d090a524a8c', '江南曲八首 七', '江南曲八首 七', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["北堂紅草盛䒠茸，南湖碧水照芙蓉。","朝遊暮起金花盡，漸覺羅裳珠露濃。","自惜妍華三五歲，已歎關山千萬重。","人情一去無還日，欲贈懷芳怨不逢。"]', '["北堂紅草盛䒠茸，南湖碧水照芙蓉。","朝游暮起金花尽，漸覺羅裳珠露濃。","自惜妍华三五歲，已歎关山千万重。","人情一去無還日，欲贈懷芳怨不逢。"]', '诗', 'shi', '', NULL, '江南曲八首 七 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a2b682-8acd-4362-97e9-7bf9b4e0f834', '江南曲八首 八', '江南曲八首 八', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["憶昔江南年盛時，平生怨在長洲曲。","冠蓋星繁江水上，衝風摽落洞庭淥。","落花兩袖紅紛紛，朝霞高閣洗晴雲。","誰言此處嬋娟子，珠玉爲心以奉君。"]', '["憶昔江南年盛时，平生怨在长洲曲。","冠蓋星繁江水上，衝风摽落洞庭淥。","落花兩袖紅紛紛，朝霞高閣洗晴云。","誰言此处嬋娟子，珠玉爲心以奉君。"]', '诗', 'shi', '', NULL, '江南曲八首 八 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0c6f83-70ad-415d-8afd-61ee109a9a93', '擣衣篇', '擣衣篇', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["秋天瑟瑟夜漫漫，夜白風清玉露漙。","燕山遊子衣裳薄，秦地佳人閨閣寒。","欲向樓中縈楚練，還來機上裂齊紈。","攬紅袖兮愁徙倚，盼青砧兮悵盤桓。","盤桓徙倚夜已久，螢火雙飛入簾牖。","西北風來吹細腰，東南月上浮纖手。","此時秋月可憐明，此時秋風別有情。","君看月下參差影，爲聽莎間斷續聲。","絳河轉兮青雲曉，飛鳥鳴兮行人少。","攢眉緝縷思紛紛，對影穿鍼魂悄悄。","聞道還家未有期，誰憐登隴不勝悲。","夢見形容亦舊日，爲許裁縫改昔時。","緘書遠寄交河曲，須及明年春草綠。","莫言衣上有斑斑，只爲思君淚相續。"]', '["秋天瑟瑟夜漫漫，夜白风清玉露漙。","燕山游子衣裳薄，秦地佳人閨閣寒。","欲向楼中縈楚練，還来機上裂齊紈。","攬紅袖兮愁徙倚，盼青砧兮悵盤桓。","盤桓徙倚夜已久，螢火雙飞入簾牖。","西北风来吹細腰，东南月上浮纖手。","此时秋月可怜明，此时秋风別有情。","君看月下參差影，爲听莎间斷續声。","絳河轉兮青云晓，飞鸟鳴兮行人少。","攢眉緝縷思紛紛，对影穿鍼魂悄悄。","闻道還家未有期，誰怜登隴不勝悲。","梦见形容亦旧日，爲許裁縫改昔时。","緘书远寄交河曲，須及明年春草綠。","莫言衣上有斑斑，只爲思君泪相續。"]', '诗', 'shi', '', NULL, '擣衣篇 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d7cd25-b545-481e-8495-8332854f47e7', '公子行', '公子行', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["天津橋下陽春水，天津橋上繁華子。","馬聲迴合青雲外，人影動搖綠波裏。","綠波蕩漾玉爲砂，青雲離披錦作霞。","可憐楊柳傷心樹，可憐桃李斷腸花。","此日遨遊邀美女，此時歌舞入娼家。","娼家美女鬱金香，飛來飛去公子傍。","的的珠簾白日映，娥娥玉顏紅粉妝。","花際裴回雙蛺蝶，池邊顧步兩鴛鴦。","傾國傾城漢武帝，爲雲爲雨楚襄王。","古來容光人所羨，況復今日遙相見。","願作輕羅著細腰，願爲明鏡分嬌面。","與君相向轉相親，與君雙棲共一身。","願作貞松千歲古，誰論芳槿一朝新。","百年同謝西山日，千秋萬古北邙塵。"]', '["天津橋下陽春水，天津橋上繁华子。","马声迴合青云外，人影动搖綠波裏。","綠波蕩漾玉爲砂，青云離披錦作霞。","可怜楊柳傷心樹，可怜桃李斷腸花。","此日遨游邀美女，此时歌舞入娼家。","娼家美女鬱金香，飞来飞去公子傍。","的的珠簾白日映，娥娥玉顏紅粉妝。","花際裴回雙蛺蝶，池邊顧步兩鴛鴦。","傾国傾城漢武帝，爲云爲雨楚襄王。","古来容光人所羨，況复今日遙相见。","願作轻羅著細腰，願爲明镜分嬌面。","與君相向轉相親，與君雙棲共一身。","願作貞松千歲古，誰論芳槿一朝新。","百年同謝西山日，千秋万古北邙塵。"]', '诗', 'shi', '', NULL, '公子行 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a05868-c889-4fc4-b835-b97f83e18ec6', '代悲白頭吟', '代悲白头吟', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["洛陽城東桃李花，飛來飛去落誰家。","洛陽女兒好顏色，坐見落花長歎息。","今年花落顏色改，明年花開復誰在。","已見松柏摧爲薪，更闻桑田變成海。","古人無復洛城東，今人還對落花風。","年年歲歲花相似，歲歲年年人不同。","寄言全盛紅顏子，應憐半死白頭翁。","此翁白頭真可憐，伊昔紅顏美少年。","公子王孫芳樹下，清歌妙舞落花前。","光祿池臺開錦繡，將軍樓閣畫神仙。","一朝臥病無相識，三春行樂在誰邊。","宛轉蛾眉能幾時，須臾鶴髪亂如絲。","但看古來歌舞地，惟有黃昏鳥雀悲。"]', '["洛陽城东桃李花，飞来飞去落誰家。","洛陽女兒好顏色，坐见落花长歎息。","今年花落顏色改，明年花开复誰在。","已见松柏摧爲薪，更闻桑田变成海。","古人無复洛城东，今人還对落花风。","年年歲歲花相似，歲歲年年人不同。","寄言全盛紅顏子，應怜半死白头翁。","此翁白头真可怜，伊昔紅顏美少年。","公子王孫芳樹下，清歌妙舞落花前。","光祿池台开錦繡，將軍楼閣畫神仙。","一朝臥病無相識，三春行乐在誰邊。","宛轉蛾眉能幾时，須臾鹤髪亂如絲。","但看古来歌舞地，惟有黄昏鸟雀悲。"]', '诗', 'shi', '', NULL, '代悲白頭吟 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd02e272-f109-4e8d-ad3d-266581d3b286', '代秦女赠行人', '代秦女赠行人', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["鸞鏡曉含春，蛾眉向影嚬。","開□衣裳破，那堪粉黛新。","春還洛陽道，爲憶春階草。","楊葉未能攀，梅花待君掃。","今朝喜鵲傍人飛，應是狂夫走馬歸。","遙想行歌共遊樂，迎前含笑著春衣。"]', '["鸾镜晓含春，蛾眉向影嚬。","开□衣裳破，那堪粉黛新。","春還洛陽道，爲憶春階草。","楊葉未能攀，梅花待君掃。","今朝喜鵲傍人飞，應是狂夫走马归。","遙想行歌共游乐，迎前含笑著春衣。"]', '诗', 'shi', '', NULL, '代秦女赠行人 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530ee513-c67b-4265-9416-bdd137545c4f', '洛中晴月送殷四入關', '洛中晴月送殷四入关', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["清洛浮橋南渡頭，天晶萬里散華洲。","晴看石瀨光無數，曉入寒潭浸不流。","微雲一點曙煙起，南陌憧憧遍行子。","欲將此意與君論，復道秦關尚千里。"]', '["清洛浮橋南渡头，天晶万里散华洲。","晴看石瀨光無數，晓入寒潭浸不流。","微云一点曙煙起，南陌憧憧遍行子。","欲將此意與君論，复道秦关尚千里。"]', '诗', 'shi', '', NULL, '洛中晴月送殷四入關 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baff64d7-4897-4299-b03c-700f301bd255', '入塞', '入塞', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["將軍陷虜圍，邊務息戎機。","霜雪交河盡，旌旗入塞飛。","曉光隨馬度，春色伴人歸。","課績朝明主，臨軒拜武威。"]', '["將軍陷虜圍，邊務息戎機。","霜雪交河尽，旌旗入塞飞。","晓光隨马度，春色伴人归。","課績朝明主，臨軒拜武威。"]', '诗', 'shi', '', NULL, '入塞 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e3d1ad-b195-4540-90e6-37795c589e9e', '覽鏡', '覽镜', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["青樓挂明鏡，臨照不勝悲。","白髮今如此，人生能幾時。","秋風下山路，明月上春期。","歎息君恩盡，容顏不可思。"]', '["青楼挂明镜，臨照不勝悲。","白髮今如此，人生能幾时。","秋风下山路，明月上春期。","歎息君恩尽，容顏不可思。"]', '诗', 'shi', '', NULL, '覽鏡 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ff0552-4213-4edd-bc94-b7e70888f5ce', '晚春', '晚春', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["佳人眠洞房，回首見垂楊。","寒盡鴛鴦被，春生玳瑁牀。","庭陰幕青靄，簾影散紅芳。","寄語同心伴，迎春且薄妝。"]', '["佳人眠洞房，回首见垂楊。","寒尽鴛鴦被，春生玳瑁牀。","庭陰幕青靄，簾影散紅芳。","寄語同心伴，迎春且薄妝。"]', '诗', 'shi', '', NULL, '晚春 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78b77857-c252-4c50-92bd-f57b928279fe', '送友人之新豐', '送友人之新豐', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["日暮秋風起，關山斷別情。","淚隨黃葉下，愁向綠樽生。","野路歸驂轉，河洲宿鳥驚。","賓遊寬旅宴，王事促嚴程。"]', '["日暮秋风起，关山斷別情。","泪隨黄葉下，愁向綠樽生。","野路归驂轉，河洲宿鸟驚。","賓游寬旅宴，王事促嚴程。"]', '诗', 'shi', '', NULL, '送友人之新豐 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9d2877-a8da-4d84-a00c-a39925f523ba', '餞李秀才赴舉', '餞李秀才赴舉', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["鴻鵠振羽翮，翻飛入帝鄉。","朝鳴集銀樹，暝宿下金塘。","日月天門近，風煙夜路長。","自憐窮浦鴈，歲歲不隨陽。"]', '["鴻鵠振羽翮，翻飞入帝乡。","朝鳴集銀樹，暝宿下金塘。","日月天门近，风煙夜路长。","自怜窮浦鴈，歲歲不隨陽。"]', '诗', 'shi', '', NULL, '餞李秀才赴舉 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8770df95-5fd5-4c31-bbed-84673c44bf0d', '夜集張諲所居', '夜集張諲所居', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["江南成久客，門館日蕭條。","惟有圖書在，多傷鬢髪凋。","諸生陪講誦，稚子給漁樵。","隱室寒燈淨，空階落葉飄。","滄洲自有趣，誰道隱須招。"]', '["江南成久客，门館日蕭條。","惟有圖书在，多傷鬢髪凋。","諸生陪講誦，稚子給漁樵。","隐室寒灯淨，空階落葉飄。","滄洲自有趣，誰道隐須招。"]', '诗', 'shi', '', NULL, '夜集張諲所居 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b25c1a-99ee-47af-9293-8c97360fd8a7', '故園置酒', '故园置酒', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["酒熟人須飲，春還鬢已秋。","願逢千日醉，得緩百年憂。","舊里多青草，新知盡白頭。","風前燈易滅，川上月難留。","卒卒周姬旦，栖栖魯孔丘。","平生能幾日，不及且遨遊。"]', '["酒熟人須饮，春還鬢已秋。","願逢千日醉，得緩百年憂。","旧里多青草，新知尽白头。","风前灯易滅，川上月难留。","卒卒周姬旦，栖栖魯孔丘。","平生能幾日，不及且遨游。"]', '诗', 'shi', '', NULL, '故園置酒 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91716c18-5b2d-48a2-a931-a2235491a32d', '晚憩南陽旅館', '晚憩南陽旅館', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["旅館何年廢，征夫此日過。","途窮人自哭，春至鳥還歌。","行路新知少，荒田古徑多。","池篁覆丹谷，墳樹遶清波。","日照蓬陰轉，風微野氣和。","傷心不可去，回首怨如何。"]', '["旅館何年廢，征夫此日過。","途窮人自哭，春至鸟還歌。","行路新知少，荒田古徑多。","池篁覆丹谷，墳樹遶清波。","日照蓬陰轉，风微野氣和。","傷心不可去，回首怨如何。"]', '诗', 'shi', '', NULL, '晚憩南陽旅館 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb7b5ad-2563-408b-ba48-dc181ce10a8b', '慶雲章', '慶云章', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["崑崙元氣，實生慶雲。","大人作矣，五色氤氳。","昔在帝嬀，南風既薰。","叢芳爛熳，郁郁纷纷。","曠矣千祀，慶雲來止。","玉葉金柯，祚我天子。","非我天子，慶雲誰昌。","非我聖母，慶雲誰光。","慶雲光矣，周道昌矣。","九萬八千，天授皇年。"]', '["崑崙元氣，實生慶云。","大人作矣，五色氤氳。","昔在帝嬀，南风既薰。","叢芳爛熳，郁郁纷纷。","曠矣千祀，慶云来止。","玉葉金柯，祚我天子。","非我天子，慶云誰昌。","非我聖母，慶云誰光。","慶云光矣，周道昌矣。","九万八千，天授皇年。"]', '诗', 'shi', '', NULL, '慶雲章 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb031d03-9ba9-46fb-917c-a031de89c0e0', '感遇詩三十八首 一', '感遇诗三十八首 一', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["微月生西海，幽陽始代昇。","圓光正東滿，陰魂已朝凝。","太極生天地，三元更廢興。","至精諒斯在，三五誰能徵。"]', '["微月生西海，幽陽始代昇。","圓光正东满，陰魂已朝凝。","太極生天地，三元更廢兴。","至精諒斯在，三五誰能徵。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 一 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('813e4c17-280a-4b7f-929e-ade3aea6615f', '感遇詩三十八首 二', '感遇诗三十八首 二', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["蘭若生春夏，芊蔚何青青。","幽獨空林色，朱蕤冒紫莖。","遲遲白日晚，嫋嫋秋風生。","歲華盡搖落，芳意竟何成。"]', '["蘭若生春夏，芊蔚何青青。","幽独空林色，朱蕤冒紫莖。","遲遲白日晚，嫋嫋秋风生。","歲华尽搖落，芳意竟何成。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccdfb12e-2b17-46dd-b76b-fcb3fd9c1df8', '感遇詩三十八首 三', '感遇诗三十八首 三', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["蒼蒼丁零塞，今古緬荒途。","亭堠何摧兀，暴骨無全軀。","黃沙幕南起，白日隱西隅。","漢甲三十萬，曾以事匈奴。","但見沙場死，誰憐塞上孤。"]', '["蒼蒼丁零塞，今古緬荒途。","亭堠何摧兀，暴骨無全軀。","黄沙幕南起，白日隐西隅。","漢甲三十万，曾以事匈奴。","但见沙場死，誰怜塞上孤。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5018154-99a3-4b60-a73f-6f2c020d3026', '感遇詩三十八首 四', '感遇诗三十八首 四', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["樂羊爲魏將，食子殉軍功。","骨肉且相薄，他人安得忠。","吾聞中山相，乃屬放麑翁。","孤獸猶不忍，況以奉君終。"]', '["乐羊爲魏將，食子殉軍功。","骨肉且相薄，他人安得忠。","吾闻中山相，乃屬放麑翁。","孤獸猶不忍，況以奉君終。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 四 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96def3fd-c079-48be-a7b0-61c98b158751', '感遇詩三十八首 五', '感遇诗三十八首 五', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["市人矜巧智，於道若童蒙。","傾奪相夸侈，不知身所終。","曷見玄真子，觀世玉壺中。","窅然遺天地，乘化入無窮。"]', '["市人矜巧智，於道若童蒙。","傾奪相夸侈，不知身所終。","曷见玄真子，观世玉壺中。","窅然遺天地，乘化入無窮。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 五 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35a0467d-7ae0-4322-8f0b-4933fa5a358c', '感遇詩三十八首 六', '感遇诗三十八首 六', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["吾觀龍變化，乃知至陽精。","石林何冥密，幽洞無留行。","古之得仙道，信與元化幷。","玄感非象識，誰能測沈冥。","世人拘目見，酣酒笑丹經。","崑崙有瑤樹，安得采其英。"]', '["吾观龙变化，乃知至陽精。","石林何冥密，幽洞無留行。","古之得仙道，信與元化幷。","玄感非象識，誰能測沈冥。","世人拘目见，酣酒笑丹經。","崑崙有瑤樹，安得采其英。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 六 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e07e0f-d8b4-41ce-8fc6-40dbff5ff6f9', '感遇詩三十八首 七', '感遇诗三十八首 七', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["白日每不歸，青陽時暮矣。","茫茫吾何思，林臥觀無始。","衆芳委時晦，鶗鴂鳴悲耳。","鴻荒古已頹，誰識巢居子。"]', '["白日每不归，青陽时暮矣。","茫茫吾何思，林臥观無始。","衆芳委时晦，鶗鴂鳴悲耳。","鴻荒古已頹，誰識巢居子。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 七 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('993937e9-e699-4105-b851-30f0c081a142', '感遇詩三十八首 八', '感遇诗三十八首 八', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["吾觀崑崙化，日月淪洞冥。","精魄相交會，天壤以羅生。","仲尼推太極，老聃貴窈冥。","西方金仙子，崇義乃無明。","空色皆寂滅，緣業定何成。","名教信紛藉，死生俱未停。"]', '["吾观崑崙化，日月淪洞冥。","精魄相交會，天壤以羅生。","仲尼推太極，老聃貴窈冥。","西方金仙子，崇義乃無明。","空色皆寂滅，緣業定何成。","名教信紛藉，死生俱未停。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 八 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9791cbe9-4036-4c6b-95ed-656f2afc2e1b', '感遇詩三十八首 九', '感遇诗三十八首 九', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["聖人秘元命，懼世亂其真。","如何嵩公輩，詼譎誤時人。","先天誠爲美，階亂禍誰因。","長城備胡寇，嬴禍發其親。","赤精既迷漢，子年何救秦。","去去桃李花，多言死如麻。"]', '["聖人秘元命，懼世亂其真。","如何嵩公輩，詼譎誤时人。","先天誠爲美，階亂禍誰因。","长城備胡寇，嬴禍發其親。","赤精既迷漢，子年何救秦。","去去桃李花，多言死如麻。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 九 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb8a1b3-116e-4376-ad2c-2e2851ef7b9a', '感遇詩三十八首 十', '感遇诗三十八首 十', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["深居觀元化，悱然爭朵頤。","讒說相啖食，利害紛㘈㘈。","便便夸毘子，榮耀更相持。","務光讓天下，商賈競刀錐。","已矣行采芝，萬世同一時。"]', '["深居观元化，悱然爭朵頤。","讒说相啖食，利害紛㘈㘈。","便便夸毘子，榮耀更相持。","務光讓天下，商賈競刀錐。","已矣行采芝，万世同一时。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f95606-1644-4604-aa41-9236c8aff802', '感遇詩三十八首 十一', '感遇诗三十八首 十一', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["吾愛鬼谷子，青谿無垢氛。","囊括經世道，遺身在白雲。","七雄方龍鬬，天下久無君。","浮榮不足貴，遵養晦時文。","舒可彌宇宙，卷之不盈分。","豈徒山木壽，空與麋鹿羣。"]', '["吾愛鬼谷子，青谿無垢氛。","囊括經世道，遺身在白云。","七雄方龙鬬，天下久無君。","浮榮不足貴，遵養晦时文。","舒可彌宇宙，卷之不盈分。","豈徒山木壽，空與麋鹿羣。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十一 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c4857c-2d99-433f-9814-4958dee37b34', '感遇詩三十八首 十二', '感遇诗三十八首 十二', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["呦呦南山鹿，罹罟以媒和。","招搖青桂樹，幽蠹亦成科。","世情甘近習，榮耀紛如何。","怨憎未相復，親愛生禍羅。","瑤臺傾巧笑，玉杯殞雙蛾。","誰見枯城蘖，青青成斧柯。"]', '["呦呦南山鹿，罹罟以媒和。","招搖青桂樹，幽蠹亦成科。","世情甘近習，榮耀紛如何。","怨憎未相复，親愛生禍羅。","瑤台傾巧笑，玉杯殞雙蛾。","誰见枯城蘖，青青成斧柯。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十二 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('056991fb-c566-4e84-a542-9fe39ec434f4', '感遇詩三十八首 十三', '感遇诗三十八首 十三', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["林居病時久，水木澹孤清。","閑臥觀物化，悠悠念無生。","青春始萌達，朱火已滿盈。","徂落方自此，感歎何時平。"]', '["林居病时久，水木澹孤清。","闲臥观物化，悠悠念無生。","青春始萌達，朱火已满盈。","徂落方自此，感歎何时平。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十三 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16be7346-e99d-4633-b2a6-241ccb74ca37', '感遇詩三十八首 十四', '感遇诗三十八首 十四', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["臨岐泣世道，天命良悠悠。","昔日殷王子，玉馬遂朝周。","寶鼎淪伊穀，瑤臺成古丘。","西山傷遺老，東陵有故侯。"]', '["臨岐泣世道，天命良悠悠。","昔日殷王子，玉马遂朝周。","寶鼎淪伊穀，瑤台成古丘。","西山傷遺老，东陵有故侯。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十四 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e33779-9055-47f0-81bd-5f426ac8b973', '感遇詩三十八首 十五', '感遇诗三十八首 十五', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["貴人難得意，賞愛在須臾。","莫以心如玉，探他明月珠。","昔稱夭桃子，今爲舂市徒。","鴟鴞悲東國，麋鹿泣姑蘇。","誰見鴟夷子，扁舟去五湖。"]', '["貴人难得意，賞愛在須臾。","莫以心如玉，探他明月珠。","昔稱夭桃子，今爲舂市徒。","鴟鴞悲东国，麋鹿泣姑蘇。","誰见鴟夷子，扁舟去五湖。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十五 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364ee260-96ec-4e74-979b-32c80c990221', '感遇詩三十八首 十六', '感遇诗三十八首 十六', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["聖人去已久，公道緬良難。","蚩蚩夸毘子，堯禹以爲謾。","驕榮貴工巧，勢利迭相干。","燕王尊樂毅，分國願同歡。","魯連讓齊爵，遺組去邯鄲。","伊人信往矣，感激爲誰歎。"]', '["聖人去已久，公道緬良难。","蚩蚩夸毘子，堯禹以爲謾。","驕榮貴工巧，勢利迭相干。","燕王尊乐毅，分国願同歡。","魯連讓齊爵，遺組去邯鄲。","伊人信往矣，感激爲誰歎。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十六 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed6ec42-d293-4c71-ad8a-20cca19915ef', '感遇詩三十八首 十七', '感遇诗三十八首 十七', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["幽居觀天運，悠悠念羣生。","終古代興沒，豪聖莫能爭。","三季淪周赧，七雄滅秦嬴。","復聞赤精子，提劒入咸京。","炎光既無象，晉虜復縱橫。","堯禹道已昧，昏虐勢方行。","豈無當世雄，天道與胡兵。","咄咄安可言，時醉而未醒。","仲尼溺東魯，伯陽遁西溟。","大運自古來，旅人胡歎哉。"]', '["幽居观天運，悠悠念羣生。","終古代兴沒，豪聖莫能爭。","三季淪周赧，七雄滅秦嬴。","复闻赤精子，提劒入咸京。","炎光既無象，晉虜复縱橫。","堯禹道已昧，昏虐勢方行。","豈無當世雄，天道與胡兵。","咄咄安可言，时醉而未醒。","仲尼溺东魯，伯陽遁西溟。","大運自古来，旅人胡歎哉。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十七 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83724c68-655e-4d34-9190-46c957dd5cbe', '感遇詩三十八首 十八', '感遇诗三十八首 十八', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["逶迤勢已久，骨鯁道斯窮。","豈無感激者，時俗頹此風。","灌園何其鄙，皎皎於陵中。","世道不相容，嗟嗟張長公。"]', '["逶迤勢已久，骨鯁道斯窮。","豈無感激者，时俗頹此风。","灌园何其鄙，皎皎於陵中。","世道不相容，嗟嗟張长公。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十八 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4028319-c3b7-4542-93fa-5b45440058c1', '感遇詩三十八首 十九', '感遇诗三十八首 十九', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["聖人不利己，憂濟在元元。","黃屋非堯意，瑤臺安可論。","吾聞西方化，清淨道彌敦。","奈何窮金玉，雕刻以爲尊。","雲構山林盡，瑤圖珠翠煩。","鬼工尚未可，人力安能存。","夸愚適增累，矜智道逾昏。"]', '["聖人不利己，憂濟在元元。","黄屋非堯意，瑤台安可論。","吾闻西方化，清淨道彌敦。","奈何窮金玉，雕刻以爲尊。","云構山林尽，瑤圖珠翠煩。","鬼工尚未可，人力安能存。","夸愚適增累，矜智道逾昏。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 十九 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b7aa6ce-fd41-40c7-bd5b-cda1eb3a7b9f', '感遇詩三十八首 二十', '感遇诗三十八首 二十', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["玄天幽且默，羣議曷嗤嗤。","聖人教猶在，世運久陵夷。","一繩將何繫？憂醉不能持。","去去行采芝，勿爲塵所欺。"]', '["玄天幽且默，羣議曷嗤嗤。","聖人教猶在，世運久陵夷。","一繩將何繫？憂醉不能持。","去去行采芝，勿爲塵所欺。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8061b8a8-5483-4707-ac47-91370377239d', '感遇詩三十八首 二十一', '感遇诗三十八首 二十一', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["蜻蛉遊天地，與世本無患。","飛飛未能止，黃雀來相干。","穰侯富秦寵，金石比交歡。","出入咸陽裏，諸侯莫敢言。","寧知山東客，激怒秦王肝。","布衣取丞相，千載爲辛酸。"]', '["蜻蛉游天地，與世本無患。","飞飞未能止，黄雀来相干。","穰侯富秦寵，金石比交歡。","出入咸陽裏，諸侯莫敢言。","寧知山东客，激怒秦王肝。","布衣取丞相，千載爲辛酸。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十一 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9aebc27-e033-4186-bd86-a8a57cf9a9de', '感遇詩三十八首 二十二', '感遇诗三十八首 二十二', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["微霜知歲晏，斧柯始青青。","況乃金天夕，浩露沾羣英。","登山望宇宙，白日已西暝。","雲海方蕩潏，孤鱗安得寧。"]', '["微霜知歲晏，斧柯始青青。","況乃金天夕，浩露沾羣英。","登山望宇宙，白日已西暝。","云海方蕩潏，孤鱗安得寧。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十二 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03aa639d-0376-49da-aede-eca417244862', '感遇詩三十八首 二十三', '感遇诗三十八首 二十三', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["翡翠巢南海，雄雌珠樹林。","何知美人意，驕愛比黃金。","殺身炎州裏，委羽玉堂陰。","旖旎光首飾，葳蕤爛錦衾。","豈不在遐遠，虞羅忽見尋。","多材信爲累，歎息此珍禽。"]', '["翡翠巢南海，雄雌珠樹林。","何知美人意，驕愛比黄金。","殺身炎州裏，委羽玉堂陰。","旖旎光首飾，葳蕤爛錦衾。","豈不在遐远，虞羅忽见尋。","多材信爲累，歎息此珍禽。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十三 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cb21e9-3cef-4923-a647-12cd22882279', '感遇詩三十八首 二十四', '感遇诗三十八首 二十四', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["挈瓶者誰子，姣服當青春。","三五明月滿，盈盈不自珍。","高堂委金玉，微縷懸千鈞。","如何負公鼎，被敓笑時人。"]', '["挈瓶者誰子，姣服當青春。","三五明月满，盈盈不自珍。","高堂委金玉，微縷懸千鈞。","如何負公鼎，被敓笑时人。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十四 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f21f3856-bffc-42dc-94ae-f115ce424d82', '感遇詩三十八首 二十五', '感遇诗三十八首 二十五', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["玄蟬號白露，茲歲已蹉跎。","羣物從大化，孤英將奈何？","瑤臺有青鳥，遠食玉山禾。","崑崙見玄鳳，豈復虞雲羅。"]', '["玄蟬號白露，茲歲已蹉跎。","羣物從大化，孤英將奈何？","瑤台有青鸟，远食玉山禾。","崑崙见玄鳳，豈复虞云羅。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十五 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c5742a-ee23-4525-980d-7ca6c75270c1', '感遇詩三十八首 二十六', '感遇诗三十八首 二十六', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["荒哉穆天子，好與白雲期。","宮女多怨曠，層城閉蛾眉。","日耽瑤池樂，豈傷桃李時。","青苔空萎絕，白髮生羅帷。"]', '["荒哉穆天子，好與白云期。","宮女多怨曠，層城閉蛾眉。","日耽瑤池乐，豈傷桃李时。","青苔空萎絕，白髮生羅帷。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十六 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57f92e6-bbe4-4e84-b826-6c674992c5b0', '感遇詩三十八首 二十七', '感遇诗三十八首 二十七', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["朝發宜都渚，浩然思故鄉。","故鄉不可見，路隔巫山陽。","巫山綵雲沒，高丘正微茫。","佇立望已久，涕落沾衣裳。","豈茲越鄉感，憶昔楚襄王。","朝雲無處所，荆國亦淪亡。"]', '["朝發宜都渚，浩然思故乡。","故乡不可见，路隔巫山陽。","巫山綵云沒，高丘正微茫。","佇立望已久，涕落沾衣裳。","豈茲越乡感，憶昔楚襄王。","朝云無处所，荆国亦淪亡。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十七 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a49874e5-df2b-4261-b092-4a30cdf0663a', '感遇詩三十八首 二十八', '感遇诗三十八首 二十八', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["昔日章華宴，荆王樂荒淫。","霓旌翠羽蓋，射兕雲夢林。","朅來高唐觀，悵望雲陽岑。","雄圖今何在？黃雀空哀吟。"]', '["昔日章华宴，荆王乐荒淫。","霓旌翠羽蓋，射兕云梦林。","朅来高唐观，悵望云陽岑。","雄圖今何在？黄雀空哀吟。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十八 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab6fb82-2158-4a2a-9ebb-88a8b5927246', '感遇詩三十八首 二十九', '感遇诗三十八首 二十九', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["丁亥歲云暮，西山事甲兵。","贏糧匝邛道，荷戟爭羗城。","嚴冬陰風勁，窮岫泄雲生。","昏噎無晝夜，羽檄復相驚。","拳跼競萬仞，崩危走九冥。","籍籍峰壑裏，哀哀冰雪行。","聖人御宇宙，聞道泰階平。","肉食謀何失，藜藿緬縱橫。"]', '["丁亥歲云暮，西山事甲兵。","贏糧匝邛道，荷戟爭羗城。","嚴冬陰风勁，窮岫泄云生。","昏噎無晝夜，羽檄复相驚。","拳跼競万仞，崩危走九冥。","籍籍峰壑裏，哀哀冰雪行。","聖人御宇宙，闻道泰階平。","肉食謀何失，藜藿緬縱橫。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 二十九 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d98247-7ed3-421e-82b7-8442cf1125bc', '感遇詩三十八首 三十', '感遇诗三十八首 三十', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["可憐瑤臺樹，灼灼佳人姿。","碧華映朱實，攀折青春時。","豈不盛光寵，榮君白玉墀。","但恨紅芳歇，凋傷感所思。"]', '["可怜瑤台樹，灼灼佳人姿。","碧华映朱實，攀折青春时。","豈不盛光寵，榮君白玉墀。","但恨紅芳歇，凋傷感所思。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45485010-1065-4afa-8ab2-13158115bfbe', '感遇詩三十八首 三十一', '感遇诗三十八首 三十一', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["朅來豪遊子，勢利禍之門。","如何蘭膏歎，感激自生冤。","衆趨明所避，時棄道猶存。","雲淵既已失，羅網與誰論。","箕山有高節，湘水有清源。","唯應白鷗鳥，可爲洗心言。"]', '["朅来豪游子，勢利禍之门。","如何蘭膏歎，感激自生冤。","衆趨明所避，时棄道猶存。","云淵既已失，羅網與誰論。","箕山有高節，湘水有清源。","唯應白鷗鸟，可爲洗心言。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十一 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a08f964-d36e-482c-b11d-b83485d3cdbb', '感遇詩三十八首 三十二', '感遇诗三十八首 三十二', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["索居猶幾日，炎夏忽然衰。","陽彩皆陰翳，親友盡暌違。","登山望不見，涕泣久漣洏。","宿夢感顏色，若與白雲期。","馬上驕豪子，驅逐正蚩蚩。"]', '["索居猶幾日，炎夏忽然衰。","陽彩皆陰翳，親友尽暌違。","登山望不见，涕泣久漣洏。","宿梦感顏色，若與白云期。","马上驕豪子，驱逐正蚩蚩。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十二 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d40fe2f-d6fa-4ac0-b831-791da1ed9e48', '感遇詩三十八首 三十三', '感遇诗三十八首 三十三', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["金鼎合神丹，世人將見欺。","飛飛騎羊子，胡乃在峨眉。","變化固幽類，芳菲能幾時。","疲痾苦淪世，憂痗日侵淄。","眷然顧幽褐，白雲空涕洟。"]', '["金鼎合神丹，世人將见欺。","飞飞騎羊子，胡乃在峨眉。","变化固幽類，芳菲能幾时。","疲痾苦淪世，憂痗日侵淄。","眷然顧幽褐，白云空涕洟。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十三 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f37f8a2e-4acd-40ae-8294-04dd22581cdd', '感遇詩三十八首 三十四', '感遇诗三十八首 三十四', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["朔風吹海樹，蕭條邊已秋。","亭上誰家子，哀哀明月樓。","自言幽燕客，結髮事遠遊。","赤丸殺公吏，白刃報私讎。","避讎至海上，被役此邊州。","故鄉三千里，遼水復悠悠。","每憤胡兵入，常爲漢國羞。","何知七十戰，白首未封侯。"]', '["朔风吹海樹，蕭條邊已秋。","亭上誰家子，哀哀明月楼。","自言幽燕客，結髮事远游。","赤丸殺公吏，白刃報私讎。","避讎至海上，被役此邊州。","故乡三千里，遼水复悠悠。","每憤胡兵入，常爲漢国羞。","何知七十戰，白首未封侯。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十四 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc7d672-2be6-4bc3-b162-2914c8ff3264', '感遇詩三十八首 三十五', '感遇诗三十八首 三十五', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["本爲貴公子，平生實愛才。","感時思報國，拔劒起蒿萊。","西馳丁零塞，北上單于臺。","登山見千里，懷古心悠哉。","誰言未忘禍，磨滅成塵埃。"]', '["本爲貴公子，平生實愛才。","感时思報国，拔劒起蒿萊。","西驰丁零塞，北上單于台。","登山见千里，懷古心悠哉。","誰言未忘禍，磨滅成塵埃。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十五 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e0c03f-0eb4-46f8-bb5c-18af10d98263', '感遇詩三十八首 三十六', '感遇诗三十八首 三十六', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["浩然坐何慕，吾蜀有峨眉。","念與楚狂子，悠悠白雲期。","時哉悲不會，涕泣久漣洏。","夢登綏山穴，南采巫山芝。","探元觀羣化，遺世從雲螭。","婉變時永矣，感悟不見之。"]', '["浩然坐何慕，吾蜀有峨眉。","念與楚狂子，悠悠白云期。","时哉悲不會，涕泣久漣洏。","梦登綏山穴，南采巫山芝。","探元观羣化，遺世從云螭。","婉变时永矣，感悟不见之。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十六 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103974bc-643c-4de0-a44e-7b0486f72387', '感遇詩三十八首 三十七', '感遇诗三十八首 三十七', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["朝入雲中郡，北望單于臺。","胡秦何密邇，沙朔氣雄哉。","藉藉天驕子，猖狂已復來。","塞垣無名將，亭堠空崔嵬。","咄嗟吾何歎，邊人塗草萊。"]', '["朝入云中郡，北望單于台。","胡秦何密邇，沙朔氣雄哉。","藉藉天驕子，猖狂已复来。","塞垣無名將，亭堠空崔嵬。","咄嗟吾何歎，邊人塗草萊。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十七 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ced57707-edca-47b8-a69f-60c22685e87e', '感遇詩三十八首 三十八', '感遇诗三十八首 三十八', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["仲尼探元化，幽鴻順陽和。","大運自盈縮，春秋遞來過。","盲飆忽號怒，萬物相紛劘。","溟海皆震蕩，孤鳳其如何。"]', '["仲尼探元化，幽鴻順陽和。","大運自盈縮，春秋遞来過。","盲飆忽號怒，万物相紛劘。","溟海皆震蕩，孤鳳其如何。"]', '诗', 'shi', '', NULL, '感遇詩三十八首 三十八 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5c637d-04bf-4ff8-9d4b-a0b2e6a97001', '觀荆玉篇', '观荆玉篇', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["鴟夷雙白玉，此玉有緇磷。","懸之千金價，舉世莫知真。","丹青非異色，輕重有殊倫。","勿信玉工言，徒悲荆國人。"]', '["鴟夷雙白玉，此玉有緇磷。","懸之千金價，舉世莫知真。","丹青非異色，轻重有殊倫。","勿信玉工言，徒悲荆国人。"]', '诗', 'shi', '', NULL, '觀荆玉篇 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b504905f-507a-447e-9f7d-8d7f1181eb2d', '鴛鴦篇', '鴛鴦篇', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["飛飛鴛鴦鳥，舉翼相蔽虧。","俱來綠潭裏，共向白雲涯。","音容相眷戀，羽翮兩逶迤。","蘋萍戲春渚，霜霰遶寒池。","浦沙連岸淨，汀樹拂潭垂。","年年此遊翫，歲歲來追隨。","鳳凰起丹穴，獨向梧桐枝。","鴻雁來紫塞，空憶稻粱肥。","烏啼倦依托，鶴鳴傷別離。","豈若此雙禽，飛翻不異林。","刷尾青江浦，交頸紫山岑。","文章負奇色，和鳴多好音。","聞有鴛鴦綺，復有鴛鴦衾。","持爲美人贈，勖此故交心。"]', '["飞飞鴛鴦鸟，舉翼相蔽虧。","俱来綠潭裏，共向白云涯。","音容相眷戀，羽翮兩逶迤。","蘋萍戲春渚，霜霰遶寒池。","浦沙連岸淨，汀樹拂潭垂。","年年此游翫，歲歲来追隨。","鳳凰起丹穴，独向梧桐枝。","鴻雁来紫塞，空憶稻粱肥。","烏啼倦依托，鹤鳴傷別離。","豈若此雙禽，飞翻不異林。","刷尾青江浦，交頸紫山岑。","文章負奇色，和鳴多好音。","闻有鴛鴦綺，复有鴛鴦衾。","持爲美人贈，勖此故交心。"]', '诗', 'shi', '', NULL, '鴛鴦篇 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b3ebe1-ee79-410d-820a-a10cbcc3a990', '與東方左史虬修竹篇', '與东方左史虬修竹篇', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["龍種生南嶽，孤翠鬱亭亭。","峰嶺上崇崒，煙雨下微冥。","夜聞鼯鼠呌，晝聒泉鶴聲。","春風正淡蕩，白露已清泠。","哀響激金奏，密色滋玉英。","歲寒霜雪苦，含彩獨青青。","豈不厭凝洌，羞比春木榮。","春木有榮歇，此節無凋零。","始願與金石，終古保堅貞。","不意伶倫子，吹之學鳳鳴。","遂偶雲和瑟，張樂奏天庭。","妙曲方千變，簫韶亦九成。","信蒙雕斲美，常願事仙靈。","驅馳翠虯駕，伊鬱紫鸞笙。","結交嬴臺女，吟弄昇天行。","攜手登白日，遠遊戲赤城。","低昂玄鶴舞，斷續綵雲生。","永隨衆仙逝，三山遊玉京。"]', '["龙種生南嶽，孤翠鬱亭亭。","峰嶺上崇崒，煙雨下微冥。","夜闻鼯鼠呌，晝聒泉鹤声。","春风正淡蕩，白露已清泠。","哀响激金奏，密色滋玉英。","歲寒霜雪苦，含彩独青青。","豈不厭凝洌，羞比春木榮。","春木有榮歇，此節無凋零。","始願與金石，終古保堅貞。","不意伶倫子，吹之学鳳鳴。","遂偶云和瑟，張乐奏天庭。","妙曲方千变，簫韶亦九成。","信蒙雕斲美，常願事仙靈。","驱驰翠虯駕，伊鬱紫鸾笙。","結交嬴台女，吟弄昇天行。","携手登白日，远游戲赤城。","低昂玄鹤舞，斷續綵云生。","永隨衆仙逝，三山游玉京。"]', '诗', 'shi', '', NULL, '與東方左史虬修竹篇 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ae934e-62e3-4fa6-97b7-7dfbf1859e69', '薊丘覽古贈盧居士藏用七首 軒轅臺', '薊丘覽古贈盧居士藏用七首 軒轅台', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["北登薊丘望，求古軒轅臺。","應龍已不見，牧馬空黃埃。","尚想廣成子，遺跡白雲隈。"]', '["北登薊丘望，求古軒轅台。","應龙已不见，牧马空黄埃。","尚想廣成子，遺跡白云隈。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 軒轅臺 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4b0e3f4-b442-400b-8b22-38ad077e0eb7', '薊丘覽古贈盧居士藏用七首 燕昭王', '薊丘覽古贈盧居士藏用七首 燕昭王', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["南登碣石坂，遙望黃金臺。","丘陵盡喬木，昭王安在哉。","霸圖悵已矣，驅馬復歸來。"]', '["南登碣石坂，遙望黄金台。","丘陵尽喬木，昭王安在哉。","霸圖悵已矣，驱马复归来。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 燕昭王 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c8bc3ce-65da-4e0e-95f3-fab8d8e3d8b3', '薊丘覽古贈盧居士藏用七首 樂生', '薊丘覽古贈盧居士藏用七首 乐生', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["王道已淪昧，戰國競貪兵。","樂生何感激，仗義下齊城。","雄圖竟中夭，遺歎寄阿衡。"]', '["王道已淪昧，戰国競貪兵。","乐生何感激，仗義下齊城。","雄圖竟中夭，遺歎寄阿衡。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 樂生 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5255d81f-b504-4cdd-9e06-1d46f46e8108', '薊丘覽古贈盧居士藏用七首 燕太子', '薊丘覽古贈盧居士藏用七首 燕太子', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["秦王日無道，太子怨亦深。","一聞田光義，匕首贈千金。","其事雖不立，千載爲傷心。"]', '["秦王日無道，太子怨亦深。","一闻田光義，匕首贈千金。","其事雖不立，千載爲傷心。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 燕太子 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a43e2d3f-22d9-4918-89e6-e415e78da015', '薊丘覽古贈盧居士藏用七首 田光先生', '薊丘覽古贈盧居士藏用七首 田光先生', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["自古皆有死，狥義良獨稀。","奈何燕太子，尚使田生疑。","伏劒誠已矣，感我涕沾衣。"]', '["自古皆有死，狥義良独稀。","奈何燕太子，尚使田生疑。","伏劒誠已矣，感我涕沾衣。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 田光先生 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69d5e93-b16e-479f-a1b0-88c8df11cf2d', '薊丘覽古贈盧居士藏用七首 鄒衍', '薊丘覽古贈盧居士藏用七首 鄒衍', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["大運淪三代，天人罕有窺。","鄒子何寥廓，漫說九瀛垂。","興亡已千載，今也則無推。"]', '["大運淪三代，天人罕有窺。","鄒子何寥廓，漫说九瀛垂。","兴亡已千載，今也則無推。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 鄒衍 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('564115e5-bb0b-4769-8e50-f5b8377a1561', '薊丘覽古贈盧居士藏用七首 郭隗', '薊丘覽古贈盧居士藏用七首 郭隗', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["逢時獨爲貴，歷代非無才。","隗君亦何幸，遂起黃金臺。"]', '["逢时独爲貴，歷代非無才。","隗君亦何幸，遂起黄金台。"]', '诗', 'shi', '', NULL, '薊丘覽古贈盧居士藏用七首 郭隗 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7cc16e-1a5a-4c62-9e33-8e1977d03932', '西還至散關答喬補闕知之', '西還至散关答喬補闕知之', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["葳蕤蒼梧鳳，嘹唳白露蟬。","羽翰本非匹，結交何獨全。","昔君事胡馬，余得奉戎旃。","攜手向沙塞，關河緬幽燕。","芳歲幾陽止，白日屢徂遷。","功業雲臺薄，平生玉佩捐。","歎此南歸日，猶聞北戍邊。","代水不可涉，巴江亦潺湲。","攬衣度函谷，銜涕望秦川。","蜀門自茲始，雲山方浩然。"]', '["葳蕤蒼梧鳳，嘹唳白露蟬。","羽翰本非匹，結交何独全。","昔君事胡马，余得奉戎旃。","携手向沙塞，关河緬幽燕。","芳歲幾陽止，白日屢徂遷。","功業云台薄，平生玉佩捐。","歎此南归日，猶闻北戍邊。","代水不可涉，巴江亦潺湲。","攬衣度函谷，銜涕望秦川。","蜀门自茲始，云山方浩然。"]', '诗', 'shi', '', NULL, '西還至散關答喬補闕知之 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8f273b-c73a-43f1-8d47-7f33dd88c9f5', '度峽口山贈喬補闕知之王二無競', '度峽口山贈喬補闕知之王二無競', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["峽口大漠南，橫絕界中國。","叢石何紛糺，赤山復翕赩。","遠望多衆容，逼之無異色。","崔崒乍孤斷，逶迤屢回直。","信關胡馬衝，亦距漢邊塞。","豈依河山險，將順休明德。","物壯誠有衰，勢雄良易極。","邐迤忽而盡，泱漭平不息。","之子黃金軀，如何此荒域。","雲臺盛多士，待君丹墀側。"]', '["峽口大漠南，橫絕界中国。","叢石何紛糺，赤山复翕赩。","远望多衆容，逼之無異色。","崔崒乍孤斷，逶迤屢回直。","信关胡马衝，亦距漢邊塞。","豈依河山險，將順休明德。","物壯誠有衰，勢雄良易極。","邐迤忽而尽，泱漭平不息。","之子黄金軀，如何此荒域。","云台盛多士，待君丹墀側。"]', '诗', 'shi', '', NULL, '度峽口山贈喬補闕知之王二無競 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c67a5e-4918-4804-b302-fcf3851dfaeb', '題居延古城贈喬十二知之', '題居延古城贈喬十二知之', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["聞君東山意，宿昔紫芝榮。","滄洲今何在？華髪旅邊城。","還漢功既薄，逐胡策未行。","徒嗟白日暮，坐對黃雲生。","桂枝芳欲晚，薏苡謗誰明。","無爲空自老，含歎負生平。"]', '["闻君东山意，宿昔紫芝榮。","滄洲今何在？华髪旅邊城。","還漢功既薄，逐胡策未行。","徒嗟白日暮，坐对黄云生。","桂枝芳欲晚，薏苡謗誰明。","無爲空自老，含歎負生平。"]', '诗', 'shi', '', NULL, '題居延古城贈喬十二知之 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85cdce99-a4ec-4656-826f-e2c462f398ab', '贈趙六貞固二首 一', '贈趙六貞固二首 一', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["回中[烽]火入，塞上追兵起。","此時邊朔寒，登隴思君子。","東顧望漢京，南山雲霧裏。"]', '["回中[烽]火入，塞上追兵起。","此时邊朔寒，登隴思君子。","东顧望漢京，南山云霧裏。"]', '诗', 'shi', '', NULL, '贈趙六貞固二首 一 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3020ff2-706e-46b0-bd06-e3c24a3f14be', '贈趙六貞固二首 二', '贈趙六貞固二首 二', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["赤螭媚其彩，婉孌蒼梧泉。","昔者瑯琊子，躬耕亦慨然。","美人豈遐曠，之子乃前賢。","良辰在何許，白日屢頹遷。","道心固微密，神用無留連。","舒可彌宇宙，攬之不盈拳。","蓬萊久蕪沒，金石徒精堅。","良寶委短褐，閑琴獨嬋娟。"]', '["赤螭媚其彩，婉孌蒼梧泉。","昔者瑯琊子，躬耕亦慨然。","美人豈遐曠，之子乃前賢。","良辰在何許，白日屢頹遷。","道心固微密，神用無留連。","舒可彌宇宙，攬之不盈拳。","蓬萊久蕪沒，金石徒精堅。","良寶委短褐，闲琴独嬋娟。"]', '诗', 'shi', '', NULL, '贈趙六貞固二首 二 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27fed33a-9147-49c8-abaa-8b1ed24acc0d', '答韓使同在邊', '答韓使同在邊', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["漢家失中策，胡馬屢南驅。","聞詔安邊使，曾是故人謨。","廢書悵懷古，負劒許良圖。","出關歲方晏，乘障日多虞。","虜入白登道，烽交紫塞途。","連兵屯北地，清野備東胡。","邊城方晏閉，斥堠始昭蘇。","復聞韓長孺，辛苦事匈奴。","雨雪顏容改，縱橫才位孤。","空懷老臣策，未獲趙軍租。","但蒙魏侯重，不受謗書誣。","當取金人祭，還歌凱入都。"]', '["漢家失中策，胡马屢南驱。","闻詔安邊使，曾是故人謨。","廢书悵懷古，負劒許良圖。","出关歲方晏，乘障日多虞。","虜入白登道，烽交紫塞途。","連兵屯北地，清野備东胡。","邊城方晏閉，斥堠始昭蘇。","复闻韓长孺，辛苦事匈奴。","雨雪顏容改，縱橫才位孤。","空懷老臣策，未獲趙軍租。","但蒙魏侯重，不受謗书誣。","當取金人祭，還歌凱入都。"]', '诗', 'shi', '', NULL, '答韓使同在邊 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41346e48-f881-4c5c-bfd1-035098fc2a35', '征東至淇門答宋十一參軍之問', '征东至淇门答宋十一參軍之问', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["南星中大火，將子涉清淇。","西林改微月，征斾空自持。","碧潭去已遠，瑤華折遺誰。","若問遼陽戍，悠悠天際旗。"]', '["南星中大火，將子涉清淇。","西林改微月，征斾空自持。","碧潭去已远，瑤华折遺誰。","若问遼陽戍，悠悠天際旗。"]', '诗', 'shi', '', NULL, '征東至淇門答宋十一參軍之問 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f499c1aa-a05e-4f24-b637-37d1de936769', '答洛陽主人', '答洛陽主人', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["平生白雲志，早愛赤松遊。","事親恨未立，從宦此中州。","主人亦何問，旅客非悠悠。","方謁明天子，清宴奉良籌。","再取連城璧，三陟平津侯。","不然拂衣去，歸從海上鷗。","寧隨當代子，傾側且沈浮。"]', '["平生白云志，早愛赤松游。","事親恨未立，從宦此中州。","主人亦何问，旅客非悠悠。","方謁明天子，清宴奉良籌。","再取連城璧，三陟平津侯。","不然拂衣去，归從海上鷗。","寧隨當代子，傾側且沈浮。"]', '诗', 'shi', '', NULL, '答洛陽主人 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1620671-e4e3-4866-b52f-ce4a04107fa5', '酬暉上人秋夜山亭有贈', '酬暉上人秋夜山亭有贈', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["皎皎白林秋，微微翠山靜。","禪居感物變，獨坐開軒屏。","風泉夜聲雜，月露宵光冷。","多謝忘機人，塵憂未能整。"]', '["皎皎白林秋，微微翠山静。","禪居感物变，独坐开軒屏。","风泉夜声杂，月露宵光冷。","多謝忘機人，塵憂未能整。"]', '诗', 'shi', '', NULL, '酬暉上人秋夜山亭有贈 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ed3eeb-86a6-4b77-9fc3-7f4dc78c241e', '酬李參軍崇嗣旅館見贈', '酬李參軍崇嗣旅館见贈', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["昨夜銀河畔，星文犯遙漢。","今朝紫氣新，物色果逢真。","言從天上落，乃是地仙人。","白璧疑冤楚，烏裘似入秦。","摧藏多古意，歷覽備艱辛。","樂廣雲雖覩，夷吾風未春。","鳳歌空有問，龍性詎能馴。","寶劒終應出，驪珠會見珍。","未及馮公老，何驚孺子貧。","青雲儻可致，北海憶孫賓。"]', '["昨夜銀河畔，星文犯遙漢。","今朝紫氣新，物色果逢真。","言從天上落，乃是地仙人。","白璧疑冤楚，烏裘似入秦。","摧藏多古意，歷覽備艱辛。","乐廣云雖覩，夷吾风未春。","鳳歌空有问，龙性詎能馴。","寶劒終應出，驪珠會见珍。","未及馮公老，何驚孺子貧。","青云儻可致，北海憶孫賓。"]', '诗', 'shi', '', NULL, '酬李參軍崇嗣旅館見贈 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4369b3bc-36be-45b7-95ea-3793ce68dad3', '酬暉上人夏日林泉', '酬暉上人夏日林泉', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["聞道白雲居，窈窕青蓮宇。","巖泉萬丈流，樹石千年古。","林臥對軒窗，山陰滿庭戶。","方釋塵事勞，從君襲蘭杜。"]', '["闻道白云居，窈窕青蓮宇。","巖泉万丈流，樹石千年古。","林臥对軒窗，山陰满庭戶。","方釋塵事勞，從君襲蘭杜。"]', '诗', 'shi', '', NULL, '酬暉上人夏日林泉 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00d5956-f824-4533-bd3a-9e7f99018575', '同宋參軍之問夢趙六贈盧陳二子之作', '同宋參軍之问梦趙六贈盧陳二子之作', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["曉霽望嵩丘，白雲半巖足。","氛氳涵翠微，宛如嬴臺曲。","故人昔所尚，幽琴歌斷續。","變化竟無常，人琴遂兩亡。","白雲失處所，夢想曖容光。","疇昔疑緣業，儒道兩相妨。","前期許幽報，迨此尚茫茫。","晤言既已失，感歎情何一。","始憶攜手期，雲臺與峨眉。","達兼濟天下，窮獨善其時。","諸君推管樂，之子慕巢夷。","奈何蒼生望，卒爲黃綬欺。","銘鼎功未立，山林事亦微。","撫孤一流慟，懷舊日暌違。","盧子尚高節，終南臥松雪。","宋侯逢聖君，驂馭遊青雲。","而我獨蹭蹬，語默道猶屯。","征戍在遼陽，蹉跎草再黃。","丹丘恨不及，白露已蒼蒼。","遠聞山陽賦，感涕下沾裳。"]', '["晓霽望嵩丘，白云半巖足。","氛氳涵翠微，宛如嬴台曲。","故人昔所尚，幽琴歌斷續。","变化竟無常，人琴遂兩亡。","白云失处所，梦想曖容光。","疇昔疑緣業，儒道兩相妨。","前期許幽報，迨此尚茫茫。","晤言既已失，感歎情何一。","始憶携手期，云台與峨眉。","達兼濟天下，窮独善其时。","諸君推管乐，之子慕巢夷。","奈何蒼生望，卒爲黄綬欺。","銘鼎功未立，山林事亦微。","撫孤一流慟，懷旧日暌違。","盧子尚高節，終南臥松雪。","宋侯逢聖君，驂馭游青云。","而我独蹭蹬，語默道猶屯。","征戍在遼陽，蹉跎草再黄。","丹丘恨不及，白露已蒼蒼。","远闻山陽賦，感涕下沾裳。"]', '诗', 'shi', '', NULL, '同宋參軍之問夢趙六贈盧陳二子之作 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf3dd81-c835-406b-a18d-8be09208ed3d', '送別出塞', '送別出塞', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["平生聞高義，書劒百夫雄。","言登青雲去，非此白頭翁。","胡兵屯塞下，漢騎屬雲中。","君爲白馬將，腰佩騂角弓。","單于不敢射，天子佇深功。","蜀山余方隱，良會何時同。"]', '["平生闻高義，书劒百夫雄。","言登青云去，非此白头翁。","胡兵屯塞下，漢騎屬云中。","君爲白马將，腰佩騂角弓。","單于不敢射，天子佇深功。","蜀山余方隐，良會何时同。"]', '诗', 'shi', '', NULL, '送別出塞 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ed5ca2-c7e5-4dbb-a7b5-dcc556b2b04b', '登薊丘樓送賈兵曹入都', '登薊丘楼送賈兵曹入都', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["東山宿昔意，北征非我心。","孤負平生願，感涕下沾襟。","暮登薊樓上，永望燕山岑。","遼海方漫漫，胡沙飛且深。","峨眉杳如夢，仙子曷由尋。","擊劒起歎息，白日忽西沈。","聞君洛陽使，因子寄南音。"]', '["东山宿昔意，北征非我心。","孤負平生願，感涕下沾襟。","暮登薊楼上，永望燕山岑。","遼海方漫漫，胡沙飞且深。","峨眉杳如梦，仙子曷由尋。","擊劒起歎息，白日忽西沈。","闻君洛陽使，因子寄南音。"]', '诗', 'shi', '', NULL, '登薊丘樓送賈兵曹入都 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159c0352-851d-4b1d-816f-282e339a46fa', '夏日暉上人房別李參軍崇嗣', '夏日暉上人房別李參軍崇嗣', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["四十九變化，一十三死生。","翕忽玄黃裏，驅馳風雨情。","是非紛妄作，寵辱坐相驚。","至人獨幽鑒，窈窕隨昏明。","咫尺山河道，軒窗日月庭。","別離焉足問，悲樂固能幷。","我輩何爲爾，棲皇猶未平。","金臺可攀陟，寶界絕將迎。","戶牖觀天地，階基上杳冥。","自超三界樂，安知萬里征。","中國要荒內，人寰宇宙榮。","弦望如朝夕，寧嗟蜀道行。"]', '["四十九变化，一十三死生。","翕忽玄黄裏，驱驰风雨情。","是非紛妄作，寵辱坐相驚。","至人独幽鑒，窈窕隨昏明。","咫尺山河道，軒窗日月庭。","別離焉足问，悲乐固能幷。","我輩何爲爾，棲皇猶未平。","金台可攀陟，寶界絕將迎。","戶牖观天地，階基上杳冥。","自超三界乐，安知万里征。","中国要荒內，人寰宇宙榮。","弦望如朝夕，寧嗟蜀道行。"]', '诗', 'shi', '', NULL, '夏日暉上人房別李參軍崇嗣 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e3a479-7c70-4400-9bf9-693905bb9d97', '秋園臥病呈暉上人', '秋园臥病呈暉上人', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["幽寂曠日遙，林園轉清密。","疲疴澹無豫，獨坐泛瑤瑟。","懷挾萬古情，憂虞百年疾。","綿綿多滯念，忽忽每如失。","緬想赤松遊，高尋白雲逸。","榮吝始都喪，幽人遂貞吉。","圖書紛滿床，山水藹盈室。","宿昔心所尚，平生自茲畢。","願言誰見知，梵筵有同術。","八月高秋晚，涼風正蕭瑟。"]', '["幽寂曠日遙，林园轉清密。","疲疴澹無豫，独坐泛瑤瑟。","懷挾万古情，憂虞百年疾。","綿綿多滯念，忽忽每如失。","緬想赤松游，高尋白云逸。","榮吝始都喪，幽人遂貞吉。","圖书紛满床，山水藹盈室。","宿昔心所尚，平生自茲畢。","願言誰见知，梵筵有同術。","八月高秋晚，涼风正蕭瑟。"]', '诗', 'shi', '', NULL, '秋園臥病呈暉上人 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('792eb9a6-3452-4a3d-a8f2-d44b2d832482', '登澤州城北樓讌', '登澤州城北楼讌', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["平生倦遊者，觀化久無窮。","復來登此國，臨望與君同。","坐見秦兵壘，遙聞趙將雄。","武安君何在，長平事已空。","且歌玄雲曲，御酒舞薰風。","勿使青衿子，嗟爾白頭翁。"]', '["平生倦游者，观化久無窮。","复来登此国，臨望與君同。","坐见秦兵壘，遙闻趙將雄。","武安君何在，长平事已空。","且歌玄云曲，御酒舞薰风。","勿使青衿子，嗟爾白头翁。"]', '诗', 'shi', '', NULL, '登澤州城北樓讌 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e21385b2-4aaa-44ba-b18d-ab5f9682713a', '山水粉圖', '山水粉圖', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["山圖之白雲兮，若巫山之高丘。","紛羣翠之鴻溶，又似蓬瀛海水之周流。","信夫人之好道，愛雲山以幽求。"]', '["山圖之白云兮，若巫山之高丘。","紛羣翠之鴻溶，又似蓬瀛海水之周流。","信夫人之好道，愛云山以幽求。"]', '诗', 'shi', '', NULL, '山水粉圖 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7aaa18-d2ee-4533-ba92-fc1a0dc790ea', '綵樹歌', '綵樹歌', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["嘉錦筵之珍樹兮，錯衆綵之氛氳。","狀瑤臺之微月，點巫山之朝雲。","青春兮不可逢，況蕙色之增芬。","結芳意而誰賞，怨絕世之無聞。","紅榮碧豔坐看歇，素華流年不待君。","故吾思崑崙之琪樹，厭桃李之繽紛。"]', '["嘉錦筵之珍樹兮，錯衆綵之氛氳。","狀瑤台之微月，点巫山之朝云。","青春兮不可逢，況蕙色之增芬。","結芳意而誰賞，怨絕世之無闻。","紅榮碧豔坐看歇，素华流年不待君。","故吾思崑崙之琪樹，厭桃李之繽紛。"]', '诗', 'shi', '', NULL, '綵樹歌 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b09e4b4-3d7e-4cdf-b91e-c2d50ec14e5f', '春臺引', '春台引', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["感陽春兮生碧草之油油，懷宇宙以傷遠，登高臺而寫憂。","遲美人兮不見，恐青歲之遂遒。","從畢公以酣飲，寄林塘而一留。","採芳蓀於北渚，憶桂樹於南州。","何雲木之美麗，而池館之崇幽。","星臺秀士，月旦諸子。","嘉青鳥之辰，迎火龍之始。","挾寶書與瑤瑟，芳蕙華而蘭靡。","乃掩白蘋，藉綠芷。","酒既醉，樂未已。","擊青鐘，歌淥水。","怨青春之萎絕，贈瑤臺之旖旎。","願一見而道意，結衆芳之綢繆。","曷余情之蕩漾，矚青雲以增愁。","悵三山之飛鶴，憶海上之白鷗。","重曰：羣仙去兮青春頹，歲華歇兮黃鳥哀。","富貴榮樂幾時兮，朱宮碧堂生青苔，白雲兮歸來。"]', '["感陽春兮生碧草之油油，懷宇宙以傷远，登高台而寫憂。","遲美人兮不见，恐青歲之遂遒。","從畢公以酣饮，寄林塘而一留。","採芳蓀於北渚，憶桂樹於南州。","何云木之美丽，而池館之崇幽。","星台秀士，月旦諸子。","嘉青鸟之辰，迎火龙之始。","挾寶书與瑤瑟，芳蕙华而蘭靡。","乃掩白蘋，藉綠芷。","酒既醉，乐未已。","擊青鐘，歌淥水。","怨青春之萎絕，贈瑤台之旖旎。","願一见而道意，結衆芳之綢繆。","曷余情之蕩漾，矚青云以增愁。","悵三山之飞鹤，憶海上之白鷗。","重曰：羣仙去兮青春頹，歲华歇兮黄鸟哀。","富貴榮乐幾时兮，朱宮碧堂生青苔，白云兮归来。"]', '诗', 'shi', '', NULL, '春臺引 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c244a5b4-0ed0-48fe-8694-95309acac184', '登幽州臺歌', '登幽州台歌', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["前不見古人，後不見來者。","念天地之悠悠，獨愴然而涕下。"]', '["前不见古人，後不见来者。","念天地之悠悠，独愴然而涕下。"]', '诗', 'shi', '', NULL, '登幽州臺歌 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff6e2546-b554-46b4-bf15-a3d455a6e375', '喜馬參軍相遇醉歌', '喜马參軍相遇醉歌', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["獨幽默以三月兮，深林潛居。","時歲忽兮，孤憤遐吟。","誰知我心，孺子孺子，其可與理分。"]', '["独幽默以三月兮，深林潛居。","时歲忽兮，孤憤遐吟。","誰知我心，孺子孺子，其可與理分。"]', '诗', 'shi', '', NULL, '喜馬參軍相遇醉歌 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4649fe31-583d-4ce4-a615-f8b3d21cd6f2', '度荆門望楚', '度荆门望楚', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["遙遙去巫峽，望望下章臺。","巴國山川盡，荆門煙霧開。","城分蒼野外，樹斷白雲隈。","今日狂歌客，誰知入楚來。"]', '["遙遙去巫峽，望望下章台。","巴国山川尽，荆门煙霧开。","城分蒼野外，樹斷白云隈。","今日狂歌客，誰知入楚来。"]', '诗', 'shi', '', NULL, '度荆門望楚 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b59f38cf-5ad0-456c-8da8-4df0536f8290', '晚次樂鄉縣', '晚次乐乡縣', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["故鄉杳無際，日暮且孤征。","川原迷舊國，道路入邊城。","野戍荒煙斷，深山古木平。","如何此時恨，噭噭夜猿鳴。"]', '["故乡杳無際，日暮且孤征。","川原迷旧国，道路入邊城。","野戍荒煙斷，深山古木平。","如何此时恨，噭噭夜猿鳴。"]', '诗', 'shi', '', NULL, '晚次樂鄉縣 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e45dcf4-2c6d-4fed-b4c2-319251e80563', '同王員外雨後登開元寺南樓因酬暉上人獨坐山亭有贈', '同王員外雨後登开元寺南楼因酬暉上人独坐山亭有贈', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["鐘梵經行罷，香林坐入禪。","巖庭交雜樹，石瀨瀉鳴泉。","水月心方寂，雲霞思獨玄。","寧知人世裏，疲病得攀緣。"]', '["鐘梵經行罷，香林坐入禪。","巖庭交杂樹，石瀨瀉鳴泉。","水月心方寂，云霞思独玄。","寧知人世裏，疲病得攀緣。"]', '诗', 'shi', '', NULL, '同王員外雨後登開元寺南樓因酬暉上人獨坐山亭有贈 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa56aaa-9f6c-4754-8124-2d5343927ef1', '東征答朝臣相送', '东征答朝臣相送', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["平生白雲意，疲薾愧爲雄。","君王謬殊寵，旌節此從戎。","挼繩當繫虜，單馬豈邀功。","孤劒將何托，長謠塞上風。"]', '["平生白云意，疲薾愧爲雄。","君王謬殊寵，旌節此從戎。","挼繩當繫虜，單马豈邀功。","孤劒將何托，长謠塞上风。"]', '诗', 'shi', '', NULL, '東征答朝臣相送 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f564368f-34c5-4519-9656-8e2291f3b619', '詠主人壁上畫鶴寄喬主簿崔著作', '詠主人壁上畫鹤寄喬主簿崔著作', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["古壁仙人畫，丹青尚有文。","獨舞紛如雪，孤飛曖似雲。","自矜彩色重，寧憶故池羣。","江海聯翩翼，長鳴誰復聞。"]', '["古壁仙人畫，丹青尚有文。","独舞紛如雪，孤飞曖似云。","自矜彩色重，寧憶故池羣。","江海聯翩翼，长鳴誰复闻。"]', '诗', 'shi', '', NULL, '詠主人壁上畫鶴寄喬主簿崔著作 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5a260f-9d71-435f-b293-5b875a36b0fa', '居延海樹聞鶯同作', '居延海樹闻鶯同作', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["邊地無芳樹，鶯聲忽聽新。","間關如有意，愁絕若懷人。","明妃失漢寵，蔡女沒胡塵。","坐聞應落淚，況憶故園春。"]', '["邊地無芳樹，鶯声忽听新。","间关如有意，愁絕若懷人。","明妃失漢寵，蔡女沒胡塵。","坐闻應落泪，況憶故园春。"]', '诗', 'shi', '', NULL, '居延海樹聞鶯同作 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be041e20-6457-4a08-aeed-f318b3025324', '題李三書齋', '題李三书斋', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["灼灼青春仲，悠悠白日昇。","聲容何足恃，榮吝坐相矜。","願與金庭會，將待玉書徵。","還丹應有術，煙駕共君乘。"]', '["灼灼青春仲，悠悠白日昇。","声容何足恃，榮吝坐相矜。","願與金庭會，將待玉书徵。","還丹應有術，煙駕共君乘。"]', '诗', 'shi', '', NULL, '題李三書齋 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf8dcc9-e351-4348-9de9-465401d15de7', '送魏大從軍', '送魏大從軍', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["匈奴猶未滅，魏絳復從戎。","悵別三河道，言追六郡雄。","雁山橫代北，狐塞接雲中。","勿使燕然上，惟留漢將功。"]', '["匈奴猶未滅，魏絳复從戎。","悵別三河道，言追六郡雄。","雁山橫代北，狐塞接云中。","勿使燕然上，惟留漢將功。"]', '诗', 'shi', '', NULL, '送魏大從軍 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1cc583-7d7b-429d-bfda-f88f696001ec', '送殷大入蜀', '送殷大入蜀', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["禺山金碧路，此地饒英靈。","送君一爲別，悽斷故鄉情。","片雲生極浦，斜日隱離亭。","坐看征騎沒，惟見遠山青。"]', '["禺山金碧路，此地饒英靈。","送君一爲別，悽斷故乡情。","片云生極浦，斜日隐離亭。","坐看征騎沒，惟见远山青。"]', '诗', 'shi', '', NULL, '送殷大入蜀 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aafc4eea-04f2-43c0-b0b7-356194b8ef04', '落第西還別劉祭酒高明府', '落第西還別劉祭酒高明府', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["別館分周國，歸驂入漢京。","地連函谷塞，川接廣陽城。","望迥樓臺出，途遙煙霧生。","莫言長落羽，貧賤一交情。"]', '["別館分周国，归驂入漢京。","地連函谷塞，川接廣陽城。","望迥楼台出，途遙煙霧生。","莫言长落羽，貧賤一交情。"]', '诗', 'shi', '', NULL, '落第西還別劉祭酒高明府 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07965c4e-274f-448f-b259-770fd9479727', '落第西還別魏四懍', '落第西還別魏四懍', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["轉蓬方不定，落羽自驚弦。","山水一爲別，歡娛復幾年。","離亭暗風雨，征路入雲煙。","還因北山逕，歸守東陂田。"]', '["轉蓬方不定，落羽自驚弦。","山水一爲別，歡娛复幾年。","離亭暗风雨，征路入云煙。","還因北山逕，归守东陂田。"]', '诗', 'shi', '', NULL, '落第西還別魏四懍 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84790fee-2ec6-4e29-b63c-7c34a62bb647', '送客', '送客', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["故人洞庭去，楊柳春風生。","相送河洲晚，蒼茫別思盈。","白蘋已堪把，綠芷復含榮。","江南多桂樹，歸客贈生平。"]', '["故人洞庭去，楊柳春风生。","相送河洲晚，蒼茫別思盈。","白蘋已堪把，綠芷复含榮。","江南多桂樹，归客贈生平。"]', '诗', 'shi', '', NULL, '送客 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f2c0609-680d-41b8-ac33-d377d0ece8f5', '春夜別友人二首 一', '春夜別友人二首 一', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["銀燭吐青煙，金樽對綺筵。","離堂思琴瑟，別路遶山川。","明月隱高樹，長河沒曉天。","悠悠洛陽道，此會在何年。"]', '["銀燭吐青煙，金樽对綺筵。","離堂思琴瑟，別路遶山川。","明月隐高樹，长河沒晓天。","悠悠洛陽道，此會在何年。"]', '诗', 'shi', '', NULL, '春夜別友人二首 一 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cddc4453-683b-4476-8447-569bf85c15c2', '春夜別友人二首 二', '春夜別友人二首 二', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["紫塞白雲斷，青春明月初。","對此芳樽夜，離憂悵有餘。","清冷花露滿，滴瀝檐宇虛。","懷君欲何贈，願上大臣書。"]', '["紫塞白云斷，青春明月初。","对此芳樽夜，離憂悵有餘。","清冷花露满，滴瀝檐宇虛。","懷君欲何贈，願上大臣书。"]', '诗', 'shi', '', NULL, '春夜別友人二首 二 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d6804d-5f10-4cbe-b54d-b9ad12c6910a', '遂州南江別鄉曲故人', '遂州南江別乡曲故人', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["楚江復爲客，征棹方悠悠。","故人憫追送，置酒此南洲。","平生亦何恨，夙昔在林丘。","違此鄉山別，長謠去國愁。"]', '["楚江复爲客，征棹方悠悠。","故人憫追送，置酒此南洲。","平生亦何恨，夙昔在林丘。","違此乡山別，长謠去国愁。"]', '诗', 'shi', '', NULL, '遂州南江別鄉曲故人 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe399c82-1a77-41b8-8275-c9ab0f62aa39', '送東萊王學士無競', '送东萊王学士無競', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["寶劒千金買，平生未許人。","懷君萬里別，持贈結交親。","孤松宜晚歲，衆木愛芳春。","已矣將何道，無令白首新。"]', '["寶劒千金買，平生未許人。","懷君万里別，持贈結交親。","孤松宜晚歲，衆木愛芳春。","已矣將何道，無令白首新。"]', '诗', 'shi', '', NULL, '送東萊王學士無競 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('167422ef-6ad8-4fc5-ac5e-7ae43dd60491', '送梁李二明府', '送梁李二明府', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["負書猶在漢，懷策未聞秦。","復此窮秋日，芳樽別故人。","黃金裝屢盡，白首契逾新。","空羨雙鳧舄，俱飛向玉輪。"]', '["負书猶在漢，懷策未闻秦。","复此窮秋日，芳樽別故人。","黄金裝屢尽，白首契逾新。","空羨雙鳧舄，俱飞向玉輪。"]', '诗', 'shi', '', NULL, '送梁李二明府 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043898cb-8c03-4452-abc4-0044ab6d69c0', '送魏兵曹使嶲州得登字', '送魏兵曹使嶲州得登字', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["陽山淫霧雨，之子慎攀登。","羗笮多珍寶，人言有愛憎。","欲酬明主惠，當盡使臣能。","勿以王陽道，迢遞畏崚嶒。"]', '["陽山淫霧雨，之子慎攀登。","羗笮多珍寶，人言有愛憎。","欲酬明主惠，當尽使臣能。","勿以王陽道，迢遞畏崚嶒。"]', '诗', 'shi', '', NULL, '送魏兵曹使嶲州得登字 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f024768-7d7f-49d4-90c3-004541ece6e1', '送著作佐郎崔融等從梁王東征', '送著作佐郎崔融等從梁王东征', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["金天方肅殺，白露始專征。","王師非樂戰，之子慎佳兵。","海氣侵南部，邊風掃北平。","莫賣盧龍塞，歸邀麟閣名。"]', '["金天方肅殺，白露始專征。","王師非乐戰，之子慎佳兵。","海氣侵南部，邊风掃北平。","莫賣盧龙塞，归邀麟閣名。"]', '诗', 'shi', '', NULL, '送著作佐郎崔融等從梁王東征 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1383682-eae8-4a2e-b529-fdc760dff4ef', '春晦餞陶七於江南同用風字', '春晦餞陶七於江南同用风字', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["黃鶴煙雲去，青江琴酒同。","離帆方楚越，溝水復西東。","芙蓉生夏浦，楊柳送春風。","明日相思處，應對菊花叢。"]', '["黄鹤煙云去，青江琴酒同。","離帆方楚越，溝水复西东。","芙蓉生夏浦，楊柳送春风。","明日相思处，應对菊花叢。"]', '诗', 'shi', '', NULL, '春晦餞陶七於江南同用風字 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('309ab392-7ff3-4f0a-a294-340f2e3f9dad', '喜遇冀侍御珪崔司議泰之二使', '喜遇冀侍御珪崔司議泰之二使', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["謝病南山下，幽臥不知春。","使星入東井，云是故交親。","惠風吹寶瑟，微月憶清真。","憑軒一留醉，江海寄情人。"]', '["謝病南山下，幽臥不知春。","使星入东井，云是故交親。","惠风吹寶瑟，微月憶清真。","憑軒一留醉，江海寄情人。"]', '诗', 'shi', '', NULL, '喜遇冀侍御珪崔司議泰之二使 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5cb6407-7b81-4293-b304-3b5d33f89056', '登薊城西北樓送崔著作融入都', '登薊城西北楼送崔著作融入都', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["薊樓望燕國，負劒喜茲登。","清規子方奏，單戟我無能。","仲冬邊風急，雲漢復霜稜。","慷慨竟何道，西南恨失朋。"]', '["薊楼望燕国，負劒喜茲登。","清規子方奏，單戟我無能。","仲冬邊风急，云漢复霜稜。","慷慨竟何道，西南恨失朋。"]', '诗', 'shi', '', NULL, '登薊城西北樓送崔著作融入都 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a73f37fb-0d50-4144-9775-f2646e14373d', '月夜有懷', '月夜有懷', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["美人挾趙瑟，微月在西軒。","寂寞夜何久，殷勤玉指繁。","清光委衾枕，遙思屬湘沅。","空簾隔星漢，猶夢感精魂。"]', '["美人挾趙瑟，微月在西軒。","寂寞夜何久，殷勤玉指繁。","清光委衾枕，遙思屬湘沅。","空簾隔星漢，猶梦感精魂。"]', '诗', 'shi', '', NULL, '月夜有懷 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e0553c-9b06-4284-ad2d-fa905c0d60cc', '夏日遊暉上人房', '夏日游暉上人房', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["山水開精舍，琴歌列梵筵。","人疑白樓賞，地似竹林禪。","對戶池光亂，交軒巖翠連。","色空今已寂，乘月弄澄泉。"]', '["山水开精舍，琴歌列梵筵。","人疑白楼賞，地似竹林禪。","对戶池光亂，交軒巖翠連。","色空今已寂，乘月弄澄泉。"]', '诗', 'shi', '', NULL, '夏日遊暉上人房 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2592592-68d0-44db-8f57-bff9a4bef624', '春日登金華觀', '春日登金华观', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["白玉仙臺古，丹丘別望遙。","山川亂雲日，樓榭入煙霄。","鶴舞千年樹，虹飛百尺橋。","還疑赤松子，天路坐相邀。"]', '["白玉仙台古，丹丘別望遙。","山川亂云日，楼榭入煙霄。","鹤舞千年樹，虹飞百尺橋。","還疑赤松子，天路坐相邀。"]', '诗', 'shi', '', NULL, '春日登金華觀 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a6da3f-0fff-4bff-8b96-04a5f61bcf29', '羣公集畢氏林亭', '羣公集畢氏林亭', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["金門有遺世，鼎實恣和邦。","默語誰能識，琴樽寄北窗。","子牟戀魏闕，漁父愛滄江。","良時信同此，歲晚迹難雙。"]', '["金门有遺世，鼎實恣和邦。","默語誰能識，琴樽寄北窗。","子牟戀魏闕，漁父愛滄江。","良时信同此，歲晚迹难雙。"]', '诗', 'shi', '', NULL, '羣公集畢氏林亭 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc2c7e5-49f1-4d76-b79b-fe59babad367', '宴胡楚真禁所', '宴胡楚真禁所', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["人生固有命，天道信無言。","青繩一相點，白璧遂成冤。","請室閑逾邃，幽庭春未暄。","寄謝韓安國，何驚獄吏尊。"]', '["人生固有命，天道信無言。","青繩一相点，白璧遂成冤。","請室闲逾邃，幽庭春未暄。","寄謝韓安国，何驚獄吏尊。"]', '诗', 'shi', '', NULL, '宴胡楚真禁所 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8779ed36-367b-4eac-9238-d6de7d789d5f', '魏氏園林人賦一物得秋亭萱草', '魏氏园林人賦一物得秋亭萱草', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["昔時幽徑裏，榮耀雜春叢。","今來玉墀上，銷歇畏秋風。","細葉猶含綠，鮮花未吐紅。","忘憂誰見賞，空此北堂中。"]', '["昔时幽徑裏，榮耀杂春叢。","今来玉墀上，銷歇畏秋风。","細葉猶含綠，鲜花未吐紅。","忘憂誰见賞，空此北堂中。"]', '诗', 'shi', '', NULL, '魏氏園林人賦一物得秋亭萱草 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d089e270-7c9d-4cbf-811a-5b84c7a2dc7c', '晦日宴高氏林亭', '晦日宴高氏林亭', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["尋春遊上路，追宴入山家。","主第簪纓滿，皇州景望華。","玉池初吐溜，珠樹始開花。","歡娛方未極，林閣散餘霞。"]', '["尋春游上路，追宴入山家。","主第簪纓满，皇州景望华。","玉池初吐溜，珠樹始开花。","歡娛方未極，林閣散餘霞。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('902a1310-1b42-4d91-acea-152d386e8504', '晦日重宴高氏林亭', '晦日重宴高氏林亭', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["公子好追隨，愛客不知疲。","象筵開玉饌，翠羽飾金巵。","此時高宴所，詎減習家池。"]', '["公子好追隨，愛客不知疲。","象筵开玉饌，翠羽飾金巵。","此时高宴所，詎減習家池。"]', '诗', 'shi', '', NULL, '晦日重宴高氏林亭 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2955b0c3-7e1d-4ffb-aaac-01619e09266f', '上元夜效小庾體', '上元夜效小庾體', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["三五月華新，遨遊逐上春。","相邀洛城曲，追宴小平津。","樓上看珠妓，車中見玉人。","芳宵殊未極，隨意守燈輪。"]', '["三五月华新，遨游逐上春。","相邀洛城曲，追宴小平津。","楼上看珠妓，车中见玉人。","芳宵殊未極，隨意守灯輪。"]', '诗', 'shi', '', NULL, '上元夜效小庾體 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e277fe-052a-45b1-b5b6-d0a337f31ff6', '洛城觀酺應制', '洛城观酺應制', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["聖人信恭己，天命允昭回。","蒼極神功被，青雲祕籙開。","垂衣受金冊，張樂宴瑤臺。","雲鳳休徵滿，魚龍雜戲來。","崇恩踰五日，惠澤暢三才。","玉帛羣臣醉，徽章縟禮該。","方覩升中禪，言觀拜洛迴。","微臣固多幸，敢上萬年杯。"]', '["聖人信恭己，天命允昭回。","蒼極神功被，青云祕籙开。","垂衣受金冊，張乐宴瑤台。","云鳳休徵满，鱼龙杂戲来。","崇恩踰五日，惠澤暢三才。","玉帛羣臣醉，徽章縟禮該。","方覩升中禪，言观拜洛迴。","微臣固多幸，敢上万年杯。"]', '诗', 'shi', '', NULL, '洛城觀酺應制 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fecaefd1-4271-4114-ab80-bddd81bd5886', '奉和皇帝上禮撫事述懷應制', '奉和皇帝上禮撫事述懷應制', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["大君忘自我，應運居紫宸。","揖讓期明辟，謳歌且順人。","軒宮帝圖盛，皇極禮容申。","南面朝萬國，東堂會百神。","雲陛旂常滿，天庭玉帛陳。","鐘石和睿思，雷雨被深仁。","承平信娛樂，王業本艱辛。","願罷瑤池宴，來觀農扈春。","卑宮昭夏德，尊老睦堯親。","微臣敢拜手，歌舞頌維新。"]', '["大君忘自我，應運居紫宸。","揖讓期明辟，謳歌且順人。","軒宮帝圖盛，皇極禮容申。","南面朝万国，东堂會百神。","云陛旂常满，天庭玉帛陳。","鐘石和睿思，雷雨被深仁。","承平信娛乐，王業本艱辛。","願罷瑤池宴，来观農扈春。","卑宮昭夏德，尊老睦堯親。","微臣敢拜手，歌舞頌維新。"]', '诗', 'shi', '', NULL, '奉和皇帝上禮撫事述懷應制 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d4d9d7-31e7-473d-98be-9f049add404d', '酬田逸人遊巖見尋不遇題隱居里壁', '酬田逸人游巖见尋不遇題隐居里壁', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["遊人獻書去，薄暮返靈臺。","傳道尋仙友，青囊賣卜來。","聞鶯忽相訪，題鳳久裴回。","石髓空盈握，金經祕不開。","還疑縫掖子，復似洛陽才。"]', '["游人獻书去，薄暮返靈台。","傳道尋仙友，青囊賣卜来。","闻鶯忽相訪，題鳳久裴回。","石髓空盈握，金經祕不开。","還疑縫掖子，复似洛陽才。"]', '诗', 'shi', '', NULL, '酬田逸人遊巖見尋不遇題隱居里壁 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82d7998-836d-419e-90b6-cfda7568d8af', '白帝城懷古', '白帝城懷古', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["日落滄江晚，停橈問土風。","城臨巴子國，臺沒漢王宮。","荒服任周甸，深山尚禹功。","巖懸青壁斷，地險碧流通。","古木生雲際，孤帆出霧中。","川途去無限，客思坐何窮。"]', '["日落滄江晚，停橈问土风。","城臨巴子国，台沒漢王宮。","荒服任周甸，深山尚禹功。","巖懸青壁斷，地險碧流通。","古木生云際，孤帆出霧中。","川途去無限，客思坐何窮。"]', '诗', 'shi', '', NULL, '白帝城懷古 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ca35ce-c68f-491a-8455-cafd4dc421ed', '峴山懷古', '峴山懷古', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["秣馬臨荒甸，登高覽舊都。","猶悲墮淚碣，尚想臥龍圖。","城邑遙分楚，山川半入吳。","丘陵徒自出，賢聖幾凋枯。","野樹蒼煙斷，津樓晚氣孤。","誰知萬里客，懷古正躊躕。"]', '["秣马臨荒甸，登高覽旧都。","猶悲墮泪碣，尚想臥龙圖。","城邑遙分楚，山川半入吳。","丘陵徒自出，賢聖幾凋枯。","野樹蒼煙斷，津楼晚氣孤。","誰知万里客，懷古正躊躕。"]', '诗', 'shi', '', NULL, '峴山懷古 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('373d9a22-c9c0-4b03-b44f-32364e8a0eeb', '宿空舲峽青樹邨浦', '宿空舲峽青樹邨浦', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["的的明月水，啾啾寒夜猿。","客思浩方亂，洲浦寂無喧。","憶作千金子，寧知九逝魂。","虛聞事朱闕，結綬騖華軒。","委別高堂愛，窺覦明主恩。","今成轉蓬去，歎息復何言。"]', '["的的明月水，啾啾寒夜猿。","客思浩方亂，洲浦寂無喧。","憶作千金子，寧知九逝魂。","虛闻事朱闕，結綬騖华軒。","委別高堂愛，窺覦明主恩。","今成轉蓬去，歎息复何言。"]', '诗', 'shi', '', NULL, '宿空舲峽青樹邨浦 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b8f8b9-fa3b-4388-b2d6-49e42a1cb796', '宿襄河驛浦', '宿襄河驛浦', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["沿流辭北渚，結纜宿南洲。","合岸昏初夕，廻塘暗不流。","臥聞塞鴻斷，坐聽峽猿愁。","沙浦明如月，汀葭晦若秋。","不及能鳴雁，徒思海上鷗。","天河殊未曉，滄海信悠悠。"]', '["沿流辞北渚，結纜宿南洲。","合岸昏初夕，廻塘暗不流。","臥闻塞鴻斷，坐听峽猿愁。","沙浦明如月，汀葭晦若秋。","不及能鳴雁，徒思海上鷗。","天河殊未晓，滄海信悠悠。"]', '诗', 'shi', '', NULL, '宿襄河驛浦 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe27593-d067-4479-8a8c-7eec5ede7e92', '贈嚴倉曹乞推命錄', '贈嚴倉曹乞推命錄', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["少學縱橫術，遊楚復遊燕。","棲遑長委命，富貴未知天。","聞道沈冥客，青囊有秘篇。","九宮探萬象，三算極重玄。","願奉唐生訣，將知躍馬年。","非同墨翟問，空滯殺龍川。"]', '["少学縱橫術，游楚复游燕。","棲遑长委命，富貴未知天。","闻道沈冥客，青囊有秘篇。","九宮探万象，三算極重玄。","願奉唐生訣，將知躍马年。","非同墨翟问，空滯殺龙川。"]', '诗', 'shi', '', NULL, '贈嚴倉曹乞推命錄 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5789d8-49a7-44eb-8957-09443c891107', '和陸明府贈將軍重出塞', '和陸明府贈將軍重出塞', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["忽聞天上將，關塞重橫行。","始返樓蘭國，還向朔方城。","黃金裝戰馬，白羽集神兵。","星月開天陣，山川列地營。","晚風吹畫角，春色耀飛旌。","寧知班定遠，猶是一書生。"]', '["忽闻天上將，关塞重橫行。","始返楼蘭国，還向朔方城。","黄金裝戰马，白羽集神兵。","星月开天陣，山川列地營。","晚风吹畫角，春色耀飞旌。","寧知班定远，猶是一书生。"]', '诗', 'shi', '', NULL, '和陸明府贈將軍重出塞 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b21246a-746d-4d0a-b438-7e55eb793ca8', '江上暫別蕭四劉三旋欣接遇', '江上暫別蕭四劉三旋欣接遇', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["昨夜滄江別，言乖天漢遊。","寧期此相遇，尚接武陵洲。","結綬還逢育，銜杯且對劉。","波潭一瀰瀰，臨望幾悠悠。","山水丹青雜，煙雲紫翠浮。","終愧神仙友，來接野人舟。"]', '["昨夜滄江別，言乖天漢游。","寧期此相遇，尚接武陵洲。","結綬還逢育，銜杯且对劉。","波潭一瀰瀰，臨望幾悠悠。","山水丹青杂，煙云紫翠浮。","終愧神仙友，来接野人舟。"]', '诗', 'shi', '', NULL, '江上暫別蕭四劉三旋欣接遇 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a0e625-bdbe-4bae-bf49-d4db36e135db', '秋日遇荆州府崔兵曹使宴', '秋日遇荆州府崔兵曹使宴', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["輶軒鳳皇使，林藪鶡雞冠。","江湖一相許，雲霧坐交歡。","興盡崔亭伯，言忘釋道安。","林光稍欲暮，歲物已將闌。","古樹蒼煙斷，虛亭白露寒。","瑤琴山水曲，今日爲君彈。"]', '["輶軒鳳皇使，林藪鶡雞冠。","江湖一相許，云霧坐交歡。","兴尽崔亭伯，言忘釋道安。","林光稍欲暮，歲物已將闌。","古樹蒼煙斷，虛亭白露寒。","瑤琴山水曲，今日爲君彈。"]', '诗', 'shi', '', NULL, '秋日遇荆州府崔兵曹使宴 陳子昂 shi');
